cmocl5nie00h6jebtukk38rdw	pct	pct	{"meta": {"id": "PCT", "code": "PCT", "name": "Patent Cooperation Treaty", "tags": ["treaty", "international_phase", "pct", "strict_formatting"], "office": "WIPO – International Bureau", "status": "active", "version": 1, "continent": "Global", "createdAt": "2025-01-01T00:00:00Z", "languages": ["ar", "zh", "en", "fr", "de", "ja", "ko", "pt", "ru", "es"], "officeUrl": "https://www.wipo.int/pct/en/", "updatedAt": "2025-01-01T00:00:00Z", "inheritsFrom": null, "applicationTypes": ["international"]}, "rules": {"claims": {"unityStandard": "PCT_Rule_13", "forbiddenPhrases": [], "preferredConnectors": ["comprising"], "twoPartFormPreferred": false, "discouragedConnectors": [], "allowMultipleDependent": true, "maxTotalClaimsRecommended": 20, "requireSupportInDescription": true, "allowReferenceNumeralsInClaims": true, "maxIndependentClaimsBeforeExtraFee": 3, "prohibitMultipleDependentOnMultipleDependent": true}, "global": {"allowTables": true, "allowEquations": true, "maxPagesRecommended": 100, "paragraphNumberingRequired": false}, "abstract": {"wordLimit": 150, "noClaimLanguage": true, "singleParagraph": true, "noBenefitsOrAdvantages": true}, "drawings": {"lineStyle": "black_and_white_solid", "paperSize": "A4", "marginTopCm": 2, "colorAllowed": false, "marginLeftCm": 2.5, "marginRightCm": 2, "marginBottomCm": 2, "minReferenceTextSizePt": 8, "requiredWhenApplicable": true, "referenceNumeralsMandatoryWhenDrawings": true}, "language": {"allowedLanguages": ["ar", "zh", "en", "fr", "de", "ja", "ko", "pt", "ru", "es"], "requiresOfficialTranslation": true}, "pageLayout": {"minMarginTopCm": 2, "defaultPageSize": "A4", "minMarginLeftCm": 2.5, "allowedPageSizes": ["A4"], "minMarginRightCm": 2, "minMarginBottomCm": 2, "recommendedFontFamily": "Times New Roman", "recommendedFontSizePt": 12, "recommendedLineSpacing": 1.5}, "procedural": {"idsRequired": false, "gracePeriodMonths": 12, "allowProvisionalPriority": true, "priorArtDisclosureThreshold": "material_to_novelty_inventive_step", "foreignFilingLicenseRequired": false}, "description": {"avoidClaimLanguage": true, "allowReferenceNumerals": true, "requireBestModeDisclosure": true, "requireEmbodimentSupportForAllClaims": true, "industrialApplicabilitySectionRequired": false}, "sequenceListing": {"notes": "For international applications filed on or after 1 July 2022 that disclose nucleotide or amino acid sequences, a sequence listing complying with WIPO Standard ST.26 in XML format is required. Depending on how and when the listing is furnished (for example, as a missing part of the description under PCT Rule 20.5), late submission may lead to correction of the international filing date or to limitations on the international search.", "format": "ST.26-XML", "affectsFilingDate": true, "allowLateFurnishing": true, "requiredIfSeqDisclosed": true, "additionalFormatsAllowedForReference": ["TXT", "PDF"]}, "designatedStates": {"mode": "all_by_default", "notes": "Under PCT Rule 4.9(a), filing a PCT application automatically designates all PCT Contracting States. Elections for the purposes of international preliminary examination under Chapter II are made later via the demand, which generally results in the election of all previously designated States.", "electionRequired": true}}, "export": {"documentTypes": [{"id": "pct_spec_pdf", "label": "PCT Specification PDF", "pageSize": "A4", "fontFamily": "Times New Roman", "fontSizePt": 12, "lineSpacing": 1.5, "marginTopCm": 2, "marginLeftCm": 2.5, "marginRightCm": 2, "addPageNumbers": true, "marginBottomCm": 2, "includesSections": ["title", "field", "background", "summary", "brief_drawings", "detailed_description", "claims", "abstract"], "addParagraphNumbers": false}], "sectionHeadings": {"field": "TECHNICAL FIELD", "claims": "CLAIMS", "summary": "DISCLOSURE OF INVENTION", "abstract": "ABSTRACT", "background": "BACKGROUND ART", "brief_drawings": "BRIEF DESCRIPTION OF DRAWINGS", "detailed_description": "MODE(S) FOR CARRYING OUT THE INVENTION"}}, "prompts": {"sections": {"field": {"topUp": {"additions": ["Required section under PCT Rule 5.1(a)(i)", "Should be suitable for international classification purposes"], "constraints": ["1-3 sentences", "Must make sense to a skilled person", "No advantages, embodiments, or detailed features"], "instruction": "Per PCT Rule 5.1(a)(i), draft Technical Field indicating the technical field to which the invention relates."}, "constraints": ["Limit to 1–3 sentences.", "State the technical field without describing advantages or embodiments.", "Ensure the field statement would make sense on its own to a skilled person."], "instruction": "Draft the Technical Field section for the PCT description."}, "title": {"topUp": {"additions": ["Title appears in the international publication (WIPO)", "Should be suitable for translation into multiple languages"], "constraints": ["Maximum 500 characters", "Brief and descriptive of the technical subject", "No trademarks, trade names, or fanciful expressions", "Suitable for publication in multiple PCT member states"], "instruction": "Per PCT Rule 4.3, draft a title that is short, precise, and indicates the subject matter to which the invention relates."}, "constraints": ["Do not exceed 500 characters.", "Do not use trademarks or the word 'patent'."], "instruction": "Draft a concise technical title for the PCT international application."}, "claims": {"topUp": {"additions": ["3+ independent claims or 15+ total claims may trigger additional search fees", "Consider national phase requirements when drafting (some offices prefer two-part form)", "Claims must be numbered consecutively in Arabic numerals"], "constraints": ["Each claim as single sentence where practicable", "Clear, consistent terminology", "Unity of invention under Rule 13 (single general inventive concept)", "Multiple dependent claims cannot depend on other multiple dependents", "Reference numerals may be included in claims (Rule 6.2(a))"], "instruction": "Per PCT Rules 6 and 13, draft claims that define the matter for which protection is sought, supported by the description."}, "constraints": ["Use 'comprising' as the preferred open-ended connector unless a closed or alternative formulation is justified.", "Avoid two-part 'characterized in that' format unless specifically requested for a designated Office.", "Each dependent claim must refer back to a single previous claim and not to another multiple dependent claim.", "All claim features must be supported by the description of the mode(s) for carrying out the invention."], "instruction": "Draft a complete set of claims compliant with PCT Rule 6 and Rule 13."}, "summary": {"topUp": {"additions": ["Required section under PCT Rule 5.1(a)(iii)", "Critical for international preliminary examination under Chapter II"], "constraints": ["Technical problem and solution must be clear", "Advantageous effects compared to prior art", "Align with independent claims"], "instruction": "Per PCT Rule 5.1(a)(iii), draft Disclosure of Invention so the technical problem and solution can be understood, with advantageous effects relative to background art."}, "constraints": ["Explain the invention as defined in the claims so that the technical problem and its solution can be understood.", "Mention advantageous effects of the invention compared with the background art, where appropriate.", "Ensure consistency with the independent claims."], "instruction": "Draft the Disclosure of Invention section."}, "abstract": {"topUp": {"additions": ["Published by WIPO in international publication", "Include reference to most illustrative figure (Rule 8.1(c))", "ISA may amend abstract if needed (Rule 38.2)"], "constraints": ["50-150 words (strictly, max 150)", "Technical field, problem, solution, principal use", "No merits, advantages, or speculative applications", "No claim-style language"], "instruction": "Per PCT Rule 8, draft an Abstract for searching purposes that permits quick understanding of the technical disclosure."}, "constraints": ["Preferably 50–150 words; do not exceed 150 words.", "Summarize the technical disclosure so that the field, problem, solution and principal use can be understood.", "Do not include statements on alleged merits, advantages or speculative applications.", "Do not use claim-style language."], "instruction": "Draft the Abstract for the PCT application."}, "background": {"topUp": {"additions": ["Prior art citations are useful for international search", "This section helps the ISA understand the technical context"], "constraints": ["Cite relevant prior art documents where known", "Describe limitations objectively", "Do not concede obviousness or lack of novelty"], "instruction": "Per PCT Rule 5.1(a)(ii), draft Background Art indicating prior art useful for understanding, searching, and examining the invention."}, "constraints": ["Describe relevant prior art and its limitations, preferably citing representative documents where appropriate.", "Avoid explicit admissions that specific references are prior art unless clearly intended.", "Do not state that the invention is obvious or trivial."], "instruction": "Draft the Background Art section."}, "fieldOfInvention": {"topUp": {"additions": ["Required section under PCT Rule 5.1(a)(i)"], "constraints": ["1-3 sentences", "Must make sense to a skilled person", "No advantages, embodiments, or detailed features"], "instruction": "Per PCT Rule 5.1(a)(i), draft Technical Field indicating the technical field to which the invention relates."}}, "detailedDescription": {"topUp": {"additions": ["Required under PCT Rule 5.1(a)(v)"], "constraints": ["Best mode must be disclosed", "Sufficient detail for enablement", "Support for all independent claims"], "instruction": "Per PCT Rule 5.1(a)(v), draft Mode(s) for Carrying Out the Invention setting out at least the best mode contemplated by the applicant."}, "constraints": ["Describe embodiments in sufficient detail that a skilled person can carry out the invention without undue experimentation.", "Set out at least the best mode contemplated by the applicant.", "Ensure that each independent claim has at least one fully supporting embodiment.", "Reference the drawings and reference numerals where applicable."], "instruction": "Draft the section describing the mode(s) for carrying out the invention."}, "briefDescriptionOfDrawings": {"topUp": {"additions": ["Format: 'Fig. X is a [view type] showing [subject]'"], "constraints": ["One sentence per figure", "Brief description only", "Required if drawings are present"], "instruction": "Per PCT Rule 5.1(a)(iv), briefly describe each figure of the drawings."}, "importFiguresDirectly": true}}, "baseStyle": {"tone": "technical, neutral, precise", "avoid": ["marketing language", "unsupported advantages", "statements on commercial merit", "overly legalistic boilerplate"], "voice": "impersonal_third_person"}, "promptMergeStrategy": "append"}, "diagrams": {"figureLabelFormat": "Fig. {number}", "supportedDiagramTypes": ["block", "flowchart", "schematic", "perspective_view"], "diagramGenerationHints": {"block": "Use rectangles for components and arrows for data/control flow.", "flowchart": "Use standard flowchart symbols for processes and decisions.", "schematic": "Show functional relationships and reference numerals clearly.", "perspective_view": "Use where overall physical form is important."}, "requiredWhenApplicable": true, "autoGenerateReferenceTable": true}, "structure": {"variants": [{"id": "pct_standard", "label": "Standard PCT International Application", "sections": [{"id": "title", "ui": {"helpText": "Enter a short, specific technical title. Do not include trademarks or the word 'patent'.", "placeholder": "Enter a concise technical title"}, "group": "header", "label": "Title", "order": 1, "required": true, "canonicalKeys": ["title"], "maxLengthChars": 500}, {"id": "cross_reference", "ui": {"helpText": "Use this section for priority and benefit claims (for example, earlier national, regional or international applications) and related applications, consistent with PCT Rule 4.10.", "placeholder": "Identify related applications and priority claims, if any."}, "group": "header", "label": "Cross-Reference to Related Applications", "order": 2, "required": false, "canonicalKeys": ["cross_reference"]}, {"id": "field", "ui": {"helpText": "1–3 sentences specifying the technical field as required by PCT Rule 5.1(a)(i); do not describe advantages or embodiments here.", "placeholder": "State the technical field to which the invention relates."}, "group": "body", "label": "Technical Field", "order": 3, "required": true, "canonicalKeys": ["technical_field"]}, {"id": "background", "ui": {"helpText": "Indicate background art useful for understanding, searching and examining the invention, preferably citing documents, as per PCT Rule 5.1(a)(ii). Avoid statements that the invention is obvious.", "placeholder": "Describe the background art and its limitations."}, "group": "body", "label": "Background Art", "order": 4, "required": false, "canonicalKeys": ["background_art"]}, {"id": "summary", "ui": {"helpText": "Explain the invention as claimed so that the technical problem and its solution can be understood, and state advantageous effects, if any, with reference to the background art, as per PCT Rule 5.1(a)(iii).", "placeholder": "Provide a high-level disclosure of the invention as claimed."}, "group": "body", "label": "Disclosure of Invention", "order": 5, "required": true, "canonicalKeys": ["disclosure_of_invention"]}, {"id": "brief_drawings", "ui": {"helpText": "One sentence per figure, briefly describing what is shown, to satisfy PCT Rule 5.1(a)(iv).", "placeholder": "Briefly describe each figure of the drawings."}, "group": "body", "label": "Brief Description of Drawings", "order": 6, "required": false, "canonicalKeys": ["brief_description_of_drawings"]}, {"id": "detailed_description", "ui": {"helpText": "Set forth at least the best mode contemplated by the applicant for carrying out the invention, using examples and referring to the drawings where appropriate, as per PCT Rule 5.1(a)(v). The description must be sufficiently clear and complete for a person skilled in the art.", "placeholder": "Describe at least one way of carrying out the invention in full detail."}, "group": "body", "label": "Mode(s) for Carrying Out the Invention", "order": 7, "required": true, "canonicalKeys": ["best_mode", "detailed_description"]}, {"id": "claims", "ui": {"helpText": "Present the claims in the clearest possible form, each as a single sentence where practicable, numbered consecutively, and drafted in accordance with PCT Rule 6.", "placeholder": "Independent and dependent claims for the international application."}, "group": "claims", "label": "Claims", "order": 8, "required": true, "canonicalKeys": ["claims"]}, {"id": "abstract", "ui": {"helpText": "Summarize the disclosure so the technical field, problem, solution and principal use can be understood, preferably in 50–150 words, without statements on alleged merits or speculative applications, as per PCT Rule 8.1.", "placeholder": "Concise technical abstract (preferably 50–150 words)."}, "group": "abstract", "label": "Abstract", "order": 9, "required": true, "canonicalKeys": ["abstract"]}], "description": "International patent application filed under the Patent Cooperation Treaty for the international phase before entering national or regional phases."}], "defaultVariant": "standard"}, "validation": {"sectionChecks": {"title": [{"id": "title_length_words", "type": "maxWords", "limit": 25, "message": "Title appears long; consider making it more concise for clarity in the international phase.", "severity": "warning"}, {"id": "title_length_chars", "type": "maxChars", "limit": 500, "message": "Title exceeds the 500 character maximum typically permitted for PCT titles.", "severity": "error"}], "claims": [{"id": "claims_count_recommended", "type": "maxCount", "limit": 20, "message": "Number of claims exceeds the recommended 20; a large claim set may increase fees or complexity before some receiving Offices, International Authorities and designated Offices.", "severity": "warning"}], "abstract": [{"id": "abstract_word_limit", "type": "maxWords", "limit": 150, "message": "Abstract exceeds 150 words; PCT practice recommends an abstract of about 50–150 words.", "severity": "error"}]}, "crossSectionChecks": [{"id": "claims_supported_by_description", "from": "claims", "type": "support", "message": "Some claim elements may not be clearly supported in the description of the mode(s) for carrying out the invention.", "severity": "error", "mustBeSupportedBy": ["detailed_description"]}, {"id": "abstract_consistent_with_claims", "from": "abstract", "type": "consistency", "message": "Abstract may describe features not clearly reflected in the independent claims.", "severity": "warning", "mustBeConsistentWith": ["claims"]}]}, "crossChecks": {"checkList": [{"id": "drawings_vs_description", "from": "brief_drawings", "description": "Ensure all reference numerals in drawings are explained in the description.", "mustBeExplainedIn": ["detailed_description"]}, {"id": "claims_vs_drawings", "from": "claims", "description": "Ensure key claimed elements appear in at least one figure when drawings are present.", "mustBeShownIn": ["brief_drawings"]}], "enableSemanticCrossCheck": true}}	1	ACTIVE	cmocl5mv3000djebtgy5unzen	cmocl7qus0002i1z6g1t4dids	2026-04-24 07:25:15.974	2026-04-24 07:31:38.16
