cmoct38xm000mlyhxj9ncwoxh	cmoct35i7000dlyhxg0nquf1s	cmoct38x8000ilyhxdgdblrez	needs_review	gemini-2.5-pro	funding-guideline-v2	{"avoid": [{"key": "no_verbatim_objectives", "text": "Investigators should avoid copying the objectives from the call for proposals verbatim in their proposal.", "rationale": "Copying objectives suggests a lack of original thought and tailoring of the project to specific local needs.", "confidence": 1, "importance": "high", "sourceAnchors": [{"url": null, "note": null, "quote": "The investigators may give specific objectives related to the above in the proposal for STI Hub and should avoid copying above objectives verbatim.", "fieldKey": null, "confidence": null, "sourceType": "raw_text"}]}, {"key": "no_direct_welfare", "text": "Proposals must avoid direct welfare activities.", "rationale": "The program is focused on S&T-based empowerment and livelihood creation, not direct aid or welfare.", "confidence": 1, "importance": "high", "sourceAnchors": [{"url": null, "note": null, "quote": "Exclusions (must avoid): Direct welfare activities.", "fieldKey": null, "confidence": null, "sourceType": "raw_text"}]}, {"key": "no_routine_technologies", "text": "Avoid routine proposals on standardized technologies such as vermicompost, mushroom cultivation, or food processing.", "rationale": "The funder seeks innovative and impactful S&T solutions, not replication of common, well-established activities.", "confidence": 1, "importance": "high", "sourceAnchors": [{"url": null, "note": null, "quote": "Routine proposals on standardized technologies (e.g., vermicompost, mushroom cultivation, food processing).", "fieldKey": null, "confidence": null, "sourceType": "raw_text"}]}, {"key": "no_overlapping_activities", "text": "Avoid activities that overlap with the work of line ministries, KVK extensions, or NRLM/SRLM programmes.", "rationale": "This prevents duplication of effort and ensures the project fills a unique gap.", "confidence": 1, "importance": "high", "sourceAnchors": [{"url": null, "note": null, "quote": "Activities overlapping with line ministries, KVK extensions, NRLM/SRLM programmes.", "fieldKey": null, "confidence": null, "sourceType": "raw_text"}]}, {"key": "inappropriate_milestones", "text": "Do not list baseline surveys, recruitment of project staff, or the purchase of capital equipment as project milestones or targets.", "rationale": "Milestones should reflect project progress and deliverables, not administrative setup tasks.", "confidence": 0.98, "importance": "medium", "sourceAnchors": [{"url": null, "note": null, "quote": "Work plan and expected deliverables of project (please don't give baseline survey, recruitment of project staff and purchase of Capital as milestone/ target.", "fieldKey": null, "confidence": null, "sourceType": "raw_text"}]}], "priorities": [{"key": "sc_community_focus", "text": "The programme is exclusively for the development of SCHEDULED CASTE (SC) COMMUNITIES.", "rationale": "This is the primary target group and a non-negotiable focus of the funding call.", "confidence": 1, "importance": "high", "sourceAnchors": [{"url": null, "note": null, "quote": "invites project proposals for financial support under the Science Technology and Innovation (STI) Hubs programme for SCHEDULED CASTE (SC) COMMUNITIES only.", "fieldKey": null, "confidence": null, "sourceType": "raw_text"}]}, {"key": "livelihood_enhancement", "text": "Projects should leverage science and technology for community empowerment, livelihood enhancement, and sustainable development.", "rationale": "This describes the core strategic goal of the STI Hubs.", "confidence": 1, "importance": "high", "sourceAnchors": [{"url": null, "note": null, "quote": "This initiative aims to foster inclusive growth by leveraging science and technology for community empowerment, livelihood enhancement, and sustainable development.", "fieldKey": null, "confidence": null, "sourceType": "raw_text"}]}, {"key": "indigenous_knowledge_systems", "text": "Proposals should aim to harness, document, research, validate, and conserve Indigenous Knowledge Systems (IKS) by integrating them with modern science and technology.", "rationale": "This is listed as a key objective, signaling a preference for culturally integrated and sustainable solutions.", "confidence": 0.98, "importance": "medium", "sourceAnchors": [{"url": null, "note": null, "quote": "To harness, document, research, validate and conserve the Indigenous Knowledge Systems (IKS), skills and practices of different communities through inputs of Science and Technology to integrate IKS into appropriate technology, innovation and development for sustainable and economically viable development model of practices in livelihood systems.", "fieldKey": null, "confidence": null, "sourceType": "raw_text"}]}, {"key": "social_enterprise_creation", "text": "Projects should identify and create social enterprises based on the strengths in local livelihood systems.", "rationale": "This objective points towards a focus on creating self-sustaining economic models rather than one-off interventions.", "confidence": 0.98, "importance": "medium", "sourceAnchors": [{"url": null, "note": null, "quote": "To identify and create social enterprises based on the strengths in livelihood systems.", "fieldKey": null, "confidence": null, "sourceType": "raw_text"}]}], "budgetRules": [{"key": "no_international_travel", "text": "International travel is not a permissible expense under the project budget.", "rationale": "This is a strict exclusion to ensure funds are used for domestic project activities.", "confidence": 1, "importance": "high", "sourceAnchors": [{"url": null, "note": null, "quote": "International travel is not permissible under the projects.", "fieldKey": null, "confidence": null, "sourceType": "raw_text"}]}, {"key": "staff_payment_norms", "text": "Staff recruited for the project must be paid as per the norms and guidelines of the Department of Science and Technology (DST).", "rationale": "Ensures compliance with funder's salary regulations.", "confidence": 1, "importance": "high", "sourceAnchors": [{"url": null, "note": null, "quote": "Staff recruited for a project should be paid as per the norms and guidelines of the DST.", "fieldKey": null, "confidence": null, "sourceType": "raw_text"}]}, {"key": "construction_cost_limits", "text": "Budget under construction cost is only for low-cost structures like a Common Facility Centre (CFC) and/or renovation or refurbishing of existing space, not for construction of new buildings or structures.", "rationale": "This rule restricts large-scale construction, focusing funds on programmatic activities.", "confidence": 1, "importance": "high", "sourceAnchors": [{"url": null, "note": null, "quote": "The budget under construction cost is only for low-cost structures like Common Facility Centre (CFC) and/or renovation or refurbishing of existing space and not for construction of new buildings or structures.", "fieldKey": null, "confidence": null, "sourceType": "raw_text"}]}, {"key": "multi_institution_budget", "text": "In a multi-institutional project, the Principal Investigator must furnish a separate budget for each implementing institution.", "rationale": "Ensures financial clarity and accountability for each partner in a collaborative project.", "confidence": 1, "importance": "high", "sourceAnchors": [{"url": null, "note": null, "quote": "In case of multi-institutional project, the Principal Investigator (PI) must furnish formal agreement from the collaborating institutions/scientists along with separate budget for each of the implementing institutions.", "fieldKey": null, "confidence": null, "sourceType": "raw_text"}]}, {"key": "equipment_quotations", "text": "If the project is approved for funding, budgetary quotations (minimum 3) will be required in support of estimates for equipment.", "rationale": "This is a post-approval compliance step to ensure competitive and transparent procurement.", "confidence": 1, "importance": "medium", "sourceAnchors": [{"url": null, "note": null, "quote": "Budgetary quotations (min. 3 no.) will be required in support of estimates for equipment, if project is approved for financial support.", "fieldKey": null, "confidence": null, "sourceType": "raw_text"}]}, {"key": "financial_responsibility", "text": "The institution or organization receiving funds assumes all financial and administrative responsibility for the project.", "rationale": "Clarifies accountability for grant management.", "confidence": 1, "importance": "high", "sourceAnchors": [{"url": null, "note": null, "quote": "Institutions/Organization receiving funds would assume financial and other administrative responsibility of the project.", "fieldKey": null, "confidence": null, "sourceType": "raw_text"}]}], "formatRules": [{"key": "project_summary_limit", "text": "The project summary must be 250 words only.", "rationale": "Strict character limit for a key proposal section.", "confidence": 1, "importance": "high", "sourceAnchors": [{"url": null, "note": null, "quote": "Project Summary (in 250 words only...)", "fieldKey": null, "confidence": null, "sourceType": "raw_text"}]}, {"key": "pi_work_summary_limit", "text": "The summary of work accomplished by the PI/Lead Institute in the proposed area during the last 5 years is limited to 100 words.", "rationale": "Strict character limit for PI's background section.", "confidence": 1, "importance": "high", "sourceAnchors": [{"url": null, "note": null, "quote": "Summary of work accomplished by PI/ Lead Institute in the proposed area during last 5 years (100 words):", "fieldKey": null, "confidence": null, "sourceType": "raw_text"}]}, {"key": "problem_statement_limit", "text": "The statement of the problem and socio-economic status of the target population must be 200 words only.", "rationale": "Strict character limit for the problem statement.", "confidence": 1, "importance": "high", "sourceAnchors": [{"url": null, "note": null, "quote": "State the target population related problem you seek to address and brief of their Socio-Economic status, in 200 words only", "fieldKey": null, "confidence": null, "sourceType": "raw_text"}]}, {"key": "sustainability_plan_limit", "text": "The self-sustainability/revenue generation plan is limited to 100 words only.", "rationale": "Strict character limit for the sustainability plan.", "confidence": 1, "importance": "high", "sourceAnchors": [{"url": null, "note": null, "quote": "Self-sustainability/revenue generation plan of the project work, in 100 words only", "fieldKey": null, "confidence": null, "sourceType": "raw_text"}]}, {"key": "project_title_content", "text": "The project title should include the problem, proposed solution/technology, target community/beneficiaries, and the name of implementing Districts and State.", "rationale": "Provides specific guidance on how to construct an informative project title.", "confidence": 0.98, "importance": "medium", "sourceAnchors": [{"url": null, "note": null, "quote": "Project Title (should include problem, proposed solution/technology, target community/beneficiaries and name of implementing Districts and State for establishment of STI hub/ WTP/SUNIL etc.):", "fieldKey": null, "confidence": null, "sourceType": "raw_text"}]}], "mustAddress": [{"key": "sustainability_plan", "text": "The proposal must clearly enumerate the key points and processes for the long-term sustainability of the project after the funding period ends.", "rationale": "Ensures the project's impact continues beyond the grant duration.", "confidence": 1, "importance": "high", "sourceAnchors": [{"url": null, "note": null, "quote": "To create a robust system in place for long term sustainability of the project undertaken, key points of sustainability and process must be clearly enumerated.", "fieldKey": null, "confidence": null, "sourceType": "raw_text"}, {"url": null, "note": null, "quote": "The project must show and enable the community the pathway to achieve sustainability after the project period is over.", "fieldKey": null, "confidence": null, "sourceType": "raw_text"}]}, {"key": "pra_swot_analysis", "text": "The relevance of the project objectives must be clearly specified and strictly based on a PRA (Participatory Rural Appraisal) and SWOT analysis conducted in the targeted project area.", "rationale": "This requirement ensures that the project is grounded in local needs and realities, not just assumptions.", "confidence": 1, "importance": "high", "sourceAnchors": [{"url": null, "note": null, "quote": "The investigators may clearly specify the relevance of objectives strictly based on PRA and SWOT analysis done in the targeted project area.", "fieldKey": null, "confidence": null, "sourceType": "raw_text"}]}, {"key": "quantify_socioeconomic_enhancement", "text": "Investigators must clearly indicate the expected quantum increase in the socioeconomic enhancement of stakeholders resulting from the technological interventions.", "rationale": "This requires proposers to define and quantify the project's impact, making the proposal more concrete and measurable.", "confidence": 1, "importance": "high", "sourceAnchors": [{"url": null, "note": null, "quote": "The investigators may clearly indicate the quantum increase in socioeconomic enhancement of stake holders after intervention of the location specific technologies.", "fieldKey": null, "confidence": null, "sourceType": "raw_text"}]}, {"key": "justify_hub_establishment", "text": "The proposal must clearly establish the significance of establishing the STI Hub and its impact on the targeted areas.", "rationale": "This ensures the proposal justifies the need for the hub itself, not just the individual interventions.", "confidence": 1, "importance": "high", "sourceAnchors": [{"url": null, "note": null, "quote": "The investigators may clearly establish the significance of establishment of STI Hub and its impact on the targeted areas.", "fieldKey": null, "confidence": null, "sourceType": "raw_text"}]}, {"key": "define_partner_roles", "text": "The proposal must clearly define the significant role of any partner Institutions in the project.", "rationale": "Ensures that collaborations are meaningful and roles are well-defined.", "confidence": 1, "importance": "high", "sourceAnchors": [{"url": null, "note": null, "quote": "The investigators may clearly define the significant role of partner Institutions in the project.", "fieldKey": null, "confidence": null, "sourceType": "raw_text"}]}, {"key": "justify_technology_choice", "text": "Investigators must justify how the technologies to be implemented are essentially required for the livelihood enhancement of the SC community.", "rationale": "This links the technology directly to the core mission of the program.", "confidence": 1, "importance": "high", "sourceAnchors": [{"url": null, "note": null, "quote": "The investigators may justify how the technologies to be intervened in the targeted areas is essentially required for livelihood enhancement of the SC community.", "fieldKey": null, "confidence": null, "sourceType": "raw_text"}]}, {"key": "beneficiary_percentage", "text": "At least 60–70% of beneficiaries must belong to SC communities.", "rationale": "This is a mandatory quantitative target to ensure the project serves the intended primary demographic.", "confidence": 1, "importance": "high", "sourceAnchors": [{"url": null, "note": null, "quote": "At least 60–70% of beneficiaries must belong to SC communities.", "fieldKey": null, "confidence": null, "sourceType": "raw_text"}]}, {"key": "intervention_limit", "text": "Each Hub should focus on not more than 4–5 interventions.", "rationale": "This rule encourages focus and depth over breadth, preventing projects from becoming unfocused.", "confidence": 1, "importance": "high", "sourceAnchors": [{"url": null, "note": null, "quote": "Each Hub should focus on not more than 4–5 interventions.", "fieldKey": null, "confidence": null, "sourceType": "raw_text"}]}], "durationRules": [{"key": "project_duration", "text": "The project duration is 3 years.", "rationale": "This is a fixed duration for the project.", "confidence": 1, "importance": "high", "sourceAnchors": [{"url": null, "note": null, "quote": "Project Duration: 3 years", "fieldKey": null, "confidence": null, "sourceType": "raw_text"}]}], "sourceAnchors": [{"url": null, "note": "The content for this JSON was extracted from the provided text titled 'CALL FOR PROPOSALS (APRIL 2026) – STI HUBS' by the Department of Science and Technology, Government of India.", "quote": null, "fieldKey": null, "confidence": 1, "sourceType": "raw_text"}], "reviewerSignals": [{"key": "collaboration_encouraged", "text": "Collaborative proposals from two or three different types of institutes are encouraged.", "rationale": "The funder explicitly states a preference for collaborative projects, signaling that such proposals will be viewed more favorably.", "confidence": 1, "importance": "high", "sourceAnchors": [{"url": null, "note": null, "quote": "Type of the Lead Institute (collaborative proposal from two/three different types of Institutes will be encouraged): -", "fieldKey": null, "confidence": null, "sourceType": "raw_text"}]}, {"key": "academic_ngo_partnership", "text": "A strong proposal will demonstrate collaboration: academic institutions must engage with local NGOs, and voluntary organizations should partner with S&T institutions.", "rationale": "This specific partnership model is presented as a requirement for effective implementation, making it a key signal of a well-structured project.", "confidence": 1, "importance": "high", "sourceAnchors": [{"url": null, "note": null, "quote": "Collaboration: Academic institutions must engage with local NGOs for sustainable rural livelihoods planning... voluntary organizations should partner with S&T institutions and R&D labs to develop location-specific, need-based technologies.", "fieldKey": null, "confidence": null, "sourceType": "raw_text"}]}, {"key": "beyond_state_of_art", "text": "Proposals are expected to demonstrate how the project will progress beyond the 'state-of-the-art' or the best initiatives tried by others.", "rationale": "This signals that reviewers are looking for innovation and advancement, not just replication of existing models.", "confidence": 0.98, "importance": "medium", "sourceAnchors": [{"url": null, "note": null, "quote": "demonstrate how the project will progress beyond the “state-of-art” or the best initiative tried by others in providing new innovative technological solution", "fieldKey": null, "confidence": null, "sourceType": "raw_text"}]}, {"key": "scientific_linkages", "text": "Strong proposals will show backward connections with higher educational and scientific institutions (like Agricultural Universities, IITs, NITs, KVKs) to access frontier technologies.", "rationale": "This indicates that reviewers value projects that are scientifically grounded and connected to advanced research.", "confidence": 0.98, "importance": "medium", "sourceAnchors": [{"url": null, "note": null, "quote": "Linkages: Backward connections with higher educational and scientific institutions (Agricultural Universities, IITs, NITs, KVKs, central departments etc.) will enable access to frontier technologies.", "fieldKey": null, "confidence": null, "sourceType": "raw_text"}]}, {"key": "community_group_involvement", "text": "Proposals that involve community groups like Self-Help Groups (SHGs), Farmer Producer Organisations (FPOs), and Farmer Producer Companies (FPCs) signal strong community engagement and potential for adoption.", "rationale": "This demonstrates a bottom-up approach and a mechanism for ensuring community buy-in and sustainability.", "confidence": 0.98, "importance": "medium", "sourceAnchors": [{"url": null, "note": null, "quote": "Community Engagement: SHGs, FPOs, and FPCs should be involved to ensure reaching the community for the adaptation of the new and improved systematic approach developed and recommended for a sustainable future.", "fieldKey": null, "confidence": null, "sourceType": "raw_text"}]}], "submissionRules": [{"key": "submission_deadline", "text": "The last date for submission of online proposals is 16/05/2026.", "rationale": "This is a hard, non-negotiable deadline for application submission.", "confidence": 1, "importance": "high", "sourceAnchors": [{"url": null, "note": null, "quote": "(LAST DATE FOR SUBMISSION OF PROPOSALS: 16/05/2026)", "fieldKey": null, "confidence": null, "sourceType": "raw_text"}]}, {"key": "online_submission_only", "text": "The project proposal must be submitted online only through DST's Electronic Project Management System (e-PMS) portal at www.onlinedst.gov.in.", "rationale": "Specifies the mandatory and sole method for proposal submission.", "confidence": 1, "importance": "high", "sourceAnchors": [{"url": null, "note": null, "quote": "The Principal Investigator should submit the project proposal online only through DST's Electronic Project Management System (e-PMS) on portal www.onlinedst.gov.in the given format along with necessary documents.", "fieldKey": null, "confidence": null, "sourceType": "raw_text"}]}, {"key": "no_other_submission_means", "text": "Proposals submitted by any other means will be summarily rejected.", "rationale": "Reinforces the exclusivity of the online portal submission method.", "confidence": 1, "importance": "high", "sourceAnchors": [{"url": null, "note": null, "quote": "Proposal submitted by any other means will be summarily rejected.", "fieldKey": null, "confidence": null, "sourceType": "raw_text"}]}, {"key": "ngo_document_submission", "text": "S&T based voluntary organizations must submit: a copy of their valid registration certificate/Trust Deed, Memorandum of Association, and byelaws; audited statements of accounts and annual reports for the last 3 financial years; and their organization's Unique ID in the NGO Darpan Portal.", "rationale": "These are mandatory document submissions for a specific applicant type to prove eligibility and good standing.", "confidence": 1, "importance": "high", "sourceAnchors": [{"url": null, "note": null, "quote": "In addition, the S&T based voluntary organizations are also required to submit the following documents while submission of proposal online on the DST e-PMS portal. Copy of valid registration certificate/Trust Deed, Memorandum of Association, Rules and Byelaws of the society. Audited Statement of Accounts and Annual Activity Reports of the organization for the last 3 financial years. Organization's Unique ID in NGO Darpan Portal", "fieldKey": null, "confidence": null, "sourceType": "raw_text"}]}, {"key": "signed_annexures", "text": "The enclosed annexures (Annexure I – Annexure V) should also be signed and submitted.", "rationale": "A specific procedural requirement for the application package.", "confidence": 1, "importance": "high", "sourceAnchors": [{"url": null, "note": null, "quote": "The enclosed annexures (Annexure I – Annexure V) should also be signed and submitted.", "fieldKey": null, "confidence": null, "sourceType": "raw_text"}]}, {"key": "multi_institution_agreement", "text": "For multi-institutional projects, the PI must furnish a formal agreement from the collaborating institutions/scientists.", "rationale": "This ensures that all partners are formally committed to the project.", "confidence": 1, "importance": "high", "sourceAnchors": [{"url": null, "note": null, "quote": "In case of multi-institutional project, the Principal Investigator (PI) must furnish formal agreement from the collaborating institutions/scientists...", "fieldKey": null, "confidence": null, "sourceType": "raw_text"}]}], "deliverableRules": [{"key": "socioeconomic_empowerment", "text": "A key outcome is the socioeconomic empowerment of SC communities through improved livelihood systems, new viable options, equitable growth, productivity enhancement, and social enterprise development.", "rationale": "This defines the primary expected impact and deliverables of the project.", "confidence": 1, "importance": "high", "sourceAnchors": [{"url": null, "note": null, "quote": "Outcomes: STI Hubs to facilitate socioeconomic empowerment of SC communities through improvement of the existing livelihood systems, besides creation of newer and viable options, equitable growth, productivity enhancement, social enterprise development, and equity with inclusion.", "fieldKey": null, "confidence": null, "sourceType": "raw_text"}]}, {"key": "capacity_building_deliverable", "text": "The project must build NGO capacity, expand institutional outreach, and promote sustainable knowledge for community development.", "rationale": "Specifies expected outcomes related to institutional and community capacity building.", "confidence": 0.98, "importance": "medium", "sourceAnchors": [{"url": null, "note": null, "quote": "By strengthening delivery mechanisms and applying S&T interventions, it must build NGO capacity, expand institutional outreach, and promote sustainable knowledge for community development.", "fieldKey": null, "confidence": null, "sourceType": "raw_text"}]}, {"key": "define_quantitative_deliverables", "text": "The work plan must detail expected deliverables, including anticipated quantitative output, outcome, and socio-economic impact on target beneficiaries.", "rationale": "Requires applicants to specify measurable results.", "confidence": 1, "importance": "high", "sourceAnchors": [{"url": null, "note": null, "quote": "Work plan and expected deliverables of project ... Expected deliverables (anticipated quantitative output, outcome & socio-economic impact on target beneficiaries)", "fieldKey": null, "confidence": null, "sourceType": "raw_text"}]}], "evaluationCriteria": [{"key": "resource_and_skill_utilization", "text": "Interventions will be evaluated on whether they utilize available local resources and build on existing community skills.", "rationale": "This criterion favors projects that are contextually appropriate and build on existing assets.", "confidence": 1, "importance": "high", "sourceAnchors": [{"url": null, "note": null, "quote": "Ensure interventions suggested utilize available resources and build on community skills.", "fieldKey": null, "confidence": null, "sourceType": "raw_text"}]}, {"key": "drudgery_reduction", "text": "Proposals will be assessed on their ability to introduce technologies that reduce manual effort and improve working conditions.", "rationale": "This focuses on the quality-of-life improvements provided by the technology.", "confidence": 1, "importance": "medium", "sourceAnchors": [{"url": null, "note": null, "quote": "Introduce technologies that ease manual effort and improve working conditions.", "fieldKey": null, "confidence": null, "sourceType": "raw_text"}]}, {"key": "efficiency_enhancement", "text": "The proposed interventions should strengthen productivity and streamline livelihood processes.", "rationale": "This is a core measure of the economic impact of the technological intervention.", "confidence": 1, "importance": "high", "sourceAnchors": [{"url": null, "note": null, "quote": "Strengthen productivity and streamline livelihood processes.", "fieldKey": null, "confidence": null, "sourceType": "raw_text"}]}, {"key": "market_integration", "text": "The project's ability to enable communities to move up the value chain and access higher market opportunities will be a key criterion.", "rationale": "This criterion assesses the project's potential for significant economic uplift and market access.", "confidence": 1, "importance": "high", "sourceAnchors": [{"url": null, "note": null, "quote": "Enable communities to move up the value chain and access higher market opportunities.", "fieldKey": null, "confidence": null, "sourceType": "raw_text"}]}, {"key": "adaptability_affordability", "text": "Interventions must be cost-effective, scalable, and culturally adaptable.", "rationale": "These factors are critical for the long-term adoption and sustainability of the proposed solutions.", "confidence": 1, "importance": "high", "sourceAnchors": [{"url": null, "note": null, "quote": "Ensure interventions are cost-effective, scalable, and culturally adaptable.", "fieldKey": null, "confidence": null, "sourceType": "raw_text"}]}, {"key": "environmental_safeguards", "text": "The project must avoid environmental degradation, reduce its carbon footprint, be sensitive to ecological balance, and meet or promote connected SDG objectives.", "rationale": "Ensures that projects are environmentally responsible and sustainable.", "confidence": 1, "importance": "medium", "sourceAnchors": [{"url": null, "note": null, "quote": "Project avoids environmental degradation and reduces carbon footprint. Project is sensitive to any alterations in ecological balance. Must meet or promote connected SDG objectives.", "fieldKey": null, "confidence": null, "sourceType": "raw_text"}]}, {"key": "employment_orientation", "text": "Interventions are evaluated on their ability to generate self-employment, create additional revenue, and strengthen local self-reliance without displacing existing jobs.", "rationale": "This focuses on positive, non-disruptive economic impact for the community.", "confidence": 1, "importance": "high", "sourceAnchors": [{"url": null, "note": null, "quote": "Generates self-employment opportunities. Creates additional revenue streams. Does not displace existing job structures. Strengthens local self-reliance through STI.", "fieldKey": null, "confidence": null, "sourceType": "raw_text"}]}, {"key": "capacity_building", "text": "The project will be judged on its ability to build S&T absorption capacity and improve knowledge and innovation capabilities among beneficiaries.", "rationale": "This criterion assesses the project's contribution to human capital development within the community.", "confidence": 1, "importance": "medium", "sourceAnchors": [{"url": null, "note": null, "quote": "Builds S&T absorption capacity. Improves knowledge and innovation capabilities among beneficiaries.", "fieldKey": null, "confidence": null, "sourceType": "raw_text"}]}]}	{"avoid": [{"key": "no_verbatim_objectives", "text": "Investigators should avoid copying the objectives from the call for proposals verbatim in their proposal.", "appliesTo": ["all"], "rationale": "Copying objectives suggests a lack of original thought and tailoring of the project to specific local needs.", "ruleClass": "avoid", "confidence": 1, "importance": "high", "sourceBlock": "avoid", "detectorHints": [], "draftingStage": [], "sourceAnchors": [{"url": null, "note": null, "quote": "The investigators may give specific objectives related to the above in the proposal for STI Hub and should avoid copying above objectives verbatim.", "fieldKey": null, "confidence": null, "sourceType": "raw_text"}], "enforcementLevel": "soft", "draftingVsSubmission": "drafting"}, {"key": "no_direct_welfare", "text": "Proposals must avoid direct welfare activities.", "appliesTo": ["all"], "rationale": "The program is focused on S&T-based empowerment and livelihood creation, not direct aid or welfare.", "ruleClass": "avoid", "confidence": 1, "importance": "high", "sourceBlock": "avoid", "detectorHints": [], "draftingStage": [], "sourceAnchors": [{"url": null, "note": null, "quote": "Exclusions (must avoid): Direct welfare activities.", "fieldKey": null, "confidence": null, "sourceType": "raw_text"}], "enforcementLevel": "hard", "draftingVsSubmission": "drafting"}, {"key": "no_routine_technologies", "text": "Avoid routine proposals on standardized technologies such as vermicompost, mushroom cultivation, or food processing.", "appliesTo": ["all"], "rationale": "The funder seeks innovative and impactful S&T solutions, not replication of common, well-established activities.", "ruleClass": "avoid", "confidence": 1, "importance": "high", "sourceBlock": "avoid", "detectorHints": [], "draftingStage": [], "sourceAnchors": [{"url": null, "note": null, "quote": "Routine proposals on standardized technologies (e.g., vermicompost, mushroom cultivation, food processing).", "fieldKey": null, "confidence": null, "sourceType": "raw_text"}], "enforcementLevel": "soft", "draftingVsSubmission": "drafting"}, {"key": "no_overlapping_activities", "text": "Avoid activities that overlap with the work of line ministries, KVK extensions, or NRLM/SRLM programmes.", "appliesTo": ["all"], "rationale": "This prevents duplication of effort and ensures the project fills a unique gap.", "ruleClass": "avoid", "confidence": 1, "importance": "high", "sourceBlock": "avoid", "detectorHints": [], "draftingStage": [], "sourceAnchors": [{"url": null, "note": null, "quote": "Activities overlapping with line ministries, KVK extensions, NRLM/SRLM programmes.", "fieldKey": null, "confidence": null, "sourceType": "raw_text"}], "enforcementLevel": "soft", "draftingVsSubmission": "drafting"}, {"key": "inappropriate_milestones", "text": "Do not list baseline surveys, recruitment of project staff, or the purchase of capital equipment as project milestones or targets.", "appliesTo": ["problem_need"], "rationale": "Milestones should reflect project progress and deliverables, not administrative setup tasks.", "ruleClass": "budget", "confidence": 0.98, "importance": "medium", "sourceBlock": "avoid", "detectorHints": ["budget_limit"], "draftingStage": ["budget_strategy"], "sourceAnchors": [{"url": null, "note": null, "quote": "Work plan and expected deliverables of project (please don't give baseline survey, recruitment of project staff and purchase of Capital as milestone/ target.", "fieldKey": null, "confidence": null, "sourceType": "raw_text"}], "enforcementLevel": "hard", "draftingVsSubmission": "drafting"}], "priorities": [{"key": "sc_community_focus", "text": "The programme is exclusively for the development of SCHEDULED CASTE (SC) COMMUNITIES.", "appliesTo": ["all"], "rationale": "This is the primary target group and a non-negotiable focus of the funding call.", "ruleClass": "priority", "confidence": 1, "importance": "high", "sourceBlock": "priorities", "detectorHints": [], "draftingStage": ["thrust_alignment"], "sourceAnchors": [{"url": null, "note": null, "quote": "invites project proposals for financial support under the Science Technology and Innovation (STI) Hubs programme for SCHEDULED CASTE (SC) COMMUNITIES only.", "fieldKey": null, "confidence": null, "sourceType": "raw_text"}], "enforcementLevel": "soft", "draftingVsSubmission": "drafting"}, {"key": "livelihood_enhancement", "text": "Projects should leverage science and technology for community empowerment, livelihood enhancement, and sustainable development.", "appliesTo": ["all"], "rationale": "This describes the core strategic goal of the STI Hubs.", "ruleClass": "priority", "confidence": 1, "importance": "high", "sourceBlock": "priorities", "detectorHints": [], "draftingStage": ["beneficiaries"], "sourceAnchors": [{"url": null, "note": null, "quote": "This initiative aims to foster inclusive growth by leveraging science and technology for community empowerment, livelihood enhancement, and sustainable development.", "fieldKey": null, "confidence": null, "sourceType": "raw_text"}], "enforcementLevel": "soft", "draftingVsSubmission": "drafting"}, {"key": "indigenous_knowledge_systems", "text": "Proposals should aim to harness, document, research, validate, and conserve Indigenous Knowledge Systems (IKS) by integrating them with modern science and technology.", "appliesTo": ["objectives"], "rationale": "This is listed as a key objective, signaling a preference for culturally integrated and sustainable solutions.", "ruleClass": "priority", "confidence": 0.98, "importance": "medium", "sourceBlock": "priorities", "detectorHints": [], "draftingStage": ["thrust_alignment"], "sourceAnchors": [{"url": null, "note": null, "quote": "To harness, document, research, validate and conserve the Indigenous Knowledge Systems (IKS), skills and practices of different communities through inputs of Science and Technology to integrate IKS into appropriate technology, innovation and development for sustainable and economically viable development model of practices in livelihood systems.", "fieldKey": null, "confidence": null, "sourceType": "raw_text"}], "enforcementLevel": "soft", "draftingVsSubmission": "drafting"}, {"key": "social_enterprise_creation", "text": "Projects should identify and create social enterprises based on the strengths in local livelihood systems.", "appliesTo": ["all"], "rationale": "This objective points towards a focus on creating self-sustaining economic models rather than one-off interventions.", "ruleClass": "priority", "confidence": 0.98, "importance": "medium", "sourceBlock": "priorities", "detectorHints": [], "draftingStage": ["thrust_alignment"], "sourceAnchors": [{"url": null, "note": null, "quote": "To identify and create social enterprises based on the strengths in livelihood systems.", "fieldKey": null, "confidence": null, "sourceType": "raw_text"}], "enforcementLevel": "soft", "draftingVsSubmission": "drafting"}], "budgetRules": [{"key": "no_international_travel", "text": "International travel is not a permissible expense under the project budget.", "appliesTo": ["workplan"], "rationale": "This is a strict exclusion to ensure funds are used for domestic project activities.", "ruleClass": "budget", "confidence": 1, "importance": "high", "sourceBlock": "budgetRules", "detectorHints": ["budget_limit"], "draftingStage": ["budget_strategy"], "sourceAnchors": [{"url": null, "note": null, "quote": "International travel is not permissible under the projects.", "fieldKey": null, "confidence": null, "sourceType": "raw_text"}], "enforcementLevel": "hard", "draftingVsSubmission": "both"}, {"key": "staff_payment_norms", "text": "Staff recruited for the project must be paid as per the norms and guidelines of the Department of Science and Technology (DST).", "appliesTo": ["workplan"], "rationale": "Ensures compliance with funder's salary regulations.", "ruleClass": "budget", "confidence": 1, "importance": "high", "sourceBlock": "budgetRules", "detectorHints": ["budget_limit"], "draftingStage": ["budget_strategy"], "sourceAnchors": [{"url": null, "note": null, "quote": "Staff recruited for a project should be paid as per the norms and guidelines of the DST.", "fieldKey": null, "confidence": null, "sourceType": "raw_text"}], "enforcementLevel": "hard", "draftingVsSubmission": "both"}, {"key": "construction_cost_limits", "text": "Budget under construction cost is only for low-cost structures like a Common Facility Centre (CFC) and/or renovation or refurbishing of existing space, not for construction of new buildings or structures.", "appliesTo": ["workplan"], "rationale": "This rule restricts large-scale construction, focusing funds on programmatic activities.", "ruleClass": "budget", "confidence": 1, "importance": "high", "sourceBlock": "budgetRules", "detectorHints": ["budget_limit"], "draftingStage": ["budget_strategy"], "sourceAnchors": [{"url": null, "note": null, "quote": "The budget under construction cost is only for low-cost structures like Common Facility Centre (CFC) and/or renovation or refurbishing of existing space and not for construction of new buildings or structures.", "fieldKey": null, "confidence": null, "sourceType": "raw_text"}], "enforcementLevel": "hard", "draftingVsSubmission": "both"}, {"key": "multi_institution_budget", "text": "In a multi-institutional project, the Principal Investigator must furnish a separate budget for each implementing institution.", "appliesTo": ["workplan"], "rationale": "Ensures financial clarity and accountability for each partner in a collaborative project.", "ruleClass": "budget", "confidence": 1, "importance": "high", "sourceBlock": "budgetRules", "detectorHints": ["budget_limit"], "draftingStage": ["beneficiaries", "budget_strategy"], "sourceAnchors": [{"url": null, "note": null, "quote": "In case of multi-institutional project, the Principal Investigator (PI) must furnish formal agreement from the collaborating institutions/scientists along with separate budget for each of the implementing institutions.", "fieldKey": null, "confidence": null, "sourceType": "raw_text"}], "enforcementLevel": "hard", "draftingVsSubmission": "both"}, {"key": "equipment_quotations", "text": "If the project is approved for funding, budgetary quotations (minimum 3) will be required in support of estimates for equipment.", "appliesTo": ["workplan"], "rationale": "This is a post-approval compliance step to ensure competitive and transparent procurement.", "ruleClass": "budget", "confidence": 1, "importance": "medium", "sourceBlock": "budgetRules", "detectorHints": ["budget_limit"], "draftingStage": ["budget_strategy"], "sourceAnchors": [{"url": null, "note": null, "quote": "Budgetary quotations (min. 3 no.) will be required in support of estimates for equipment, if project is approved for financial support.", "fieldKey": null, "confidence": null, "sourceType": "raw_text"}], "enforcementLevel": "hard", "draftingVsSubmission": "both"}, {"key": "financial_responsibility", "text": "The institution or organization receiving funds assumes all financial and administrative responsibility for the project.", "appliesTo": ["workplan"], "rationale": "Clarifies accountability for grant management.", "ruleClass": "budget", "confidence": 1, "importance": "high", "sourceBlock": "budgetRules", "detectorHints": ["budget_limit"], "draftingStage": ["beneficiaries"], "sourceAnchors": [{"url": null, "note": null, "quote": "Institutions/Organization receiving funds would assume financial and other administrative responsibility of the project.", "fieldKey": null, "confidence": null, "sourceType": "raw_text"}], "enforcementLevel": "hard", "draftingVsSubmission": "both"}], "formatRules": [{"key": "project_summary_limit", "text": "The project summary must be 250 words only.", "appliesTo": ["summary"], "rationale": "Strict character limit for a key proposal section.", "ruleClass": "format", "confidence": 1, "importance": "high", "sourceBlock": "formatRules", "detectorHints": ["word_limit", "character_limit", "format_rule"], "draftingStage": ["final_pitch"], "sourceAnchors": [{"url": null, "note": null, "quote": "Project Summary (in 250 words only...)", "fieldKey": null, "confidence": null, "sourceType": "raw_text"}], "enforcementLevel": "hard", "draftingVsSubmission": "both"}, {"key": "pi_work_summary_limit", "text": "The summary of work accomplished by the PI/Lead Institute in the proposed area during the last 5 years is limited to 100 words.", "appliesTo": ["summary"], "rationale": "Strict character limit for PI's background section.", "ruleClass": "format", "confidence": 1, "importance": "high", "sourceBlock": "formatRules", "detectorHints": ["word_limit", "character_limit", "format_rule", "duration_limit"], "draftingStage": ["final_pitch"], "sourceAnchors": [{"url": null, "note": null, "quote": "Summary of work accomplished by PI/ Lead Institute in the proposed area during last 5 years (100 words):", "fieldKey": null, "confidence": null, "sourceType": "raw_text"}], "enforcementLevel": "hard", "draftingVsSubmission": "both"}, {"key": "problem_statement_limit", "text": "The statement of the problem and socio-economic status of the target population must be 200 words only.", "appliesTo": ["problem_need", "objectives"], "rationale": "Strict character limit for the problem statement.", "ruleClass": "format", "confidence": 1, "importance": "high", "sourceBlock": "formatRules", "detectorHints": ["word_limit", "character_limit", "format_rule"], "draftingStage": ["problem_definition", "beneficiaries"], "sourceAnchors": [{"url": null, "note": null, "quote": "State the target population related problem you seek to address and brief of their Socio-Economic status, in 200 words only", "fieldKey": null, "confidence": null, "sourceType": "raw_text"}], "enforcementLevel": "hard", "draftingVsSubmission": "both"}, {"key": "sustainability_plan_limit", "text": "The self-sustainability/revenue generation plan is limited to 100 words only.", "appliesTo": ["all"], "rationale": "Strict character limit for the sustainability plan.", "ruleClass": "format", "confidence": 1, "importance": "high", "sourceBlock": "formatRules", "detectorHints": ["word_limit", "character_limit", "format_rule"], "draftingStage": [], "sourceAnchors": [{"url": null, "note": null, "quote": "Self-sustainability/revenue generation plan of the project work, in 100 words only", "fieldKey": null, "confidence": null, "sourceType": "raw_text"}], "enforcementLevel": "hard", "draftingVsSubmission": "both"}, {"key": "project_title_content", "text": "The project title should include the problem, proposed solution/technology, target community/beneficiaries, and the name of implementing Districts and State.", "appliesTo": ["problem_need", "objectives"], "rationale": "Provides specific guidance on how to construct an informative project title.", "ruleClass": "format", "confidence": 0.98, "importance": "medium", "sourceBlock": "formatRules", "detectorHints": ["word_limit", "character_limit", "format_rule"], "draftingStage": ["problem_definition", "beneficiaries"], "sourceAnchors": [{"url": null, "note": null, "quote": "Project Title (should include problem, proposed solution/technology, target community/beneficiaries and name of implementing Districts and State for establishment of STI hub/ WTP/SUNIL etc.):", "fieldKey": null, "confidence": null, "sourceType": "raw_text"}], "enforcementLevel": "hard", "draftingVsSubmission": "both"}], "mustAddress": [{"key": "sustainability_plan", "text": "The proposal must clearly enumerate the key points and processes for the long-term sustainability of the project after the funding period ends.", "appliesTo": ["all"], "rationale": "Ensures the project's impact continues beyond the grant duration.", "ruleClass": "must_address", "confidence": 1, "importance": "high", "sourceBlock": "mustAddress", "detectorHints": [], "draftingStage": [], "sourceAnchors": [{"url": null, "note": null, "quote": "To create a robust system in place for long term sustainability of the project undertaken, key points of sustainability and process must be clearly enumerated.", "fieldKey": null, "confidence": null, "sourceType": "raw_text"}, {"url": null, "note": null, "quote": "The project must show and enable the community the pathway to achieve sustainability after the project period is over.", "fieldKey": null, "confidence": null, "sourceType": "raw_text"}], "enforcementLevel": "hard", "draftingVsSubmission": "drafting"}, {"key": "pra_swot_analysis", "text": "The relevance of the project objectives must be clearly specified and strictly based on a PRA (Participatory Rural Appraisal) and SWOT analysis conducted in the targeted project area.", "appliesTo": ["alignment"], "rationale": "This requirement ensures that the project is grounded in local needs and realities, not just assumptions.", "ruleClass": "must_address", "confidence": 1, "importance": "high", "sourceBlock": "mustAddress", "detectorHints": [], "draftingStage": ["fit_and_scope"], "sourceAnchors": [{"url": null, "note": null, "quote": "The investigators may clearly specify the relevance of objectives strictly based on PRA and SWOT analysis done in the targeted project area.", "fieldKey": null, "confidence": null, "sourceType": "raw_text"}], "enforcementLevel": "hard", "draftingVsSubmission": "drafting"}, {"key": "quantify_socioeconomic_enhancement", "text": "Investigators must clearly indicate the expected quantum increase in the socioeconomic enhancement of stakeholders resulting from the technological interventions.", "appliesTo": ["all"], "rationale": "This requires proposers to define and quantify the project's impact, making the proposal more concrete and measurable.", "ruleClass": "must_address", "confidence": 1, "importance": "high", "sourceBlock": "mustAddress", "detectorHints": [], "draftingStage": [], "sourceAnchors": [{"url": null, "note": null, "quote": "The investigators may clearly indicate the quantum increase in socioeconomic enhancement of stake holders after intervention of the location specific technologies.", "fieldKey": null, "confidence": null, "sourceType": "raw_text"}], "enforcementLevel": "hard", "draftingVsSubmission": "drafting"}, {"key": "justify_hub_establishment", "text": "The proposal must clearly establish the significance of establishing the STI Hub and its impact on the targeted areas.", "appliesTo": ["impact_outcomes"], "rationale": "This ensures the proposal justifies the need for the hub itself, not just the individual interventions.", "ruleClass": "must_address", "confidence": 1, "importance": "high", "sourceBlock": "mustAddress", "detectorHints": [], "draftingStage": ["outcomes"], "sourceAnchors": [{"url": null, "note": null, "quote": "The investigators may clearly establish the significance of establishment of STI Hub and its impact on the targeted areas.", "fieldKey": null, "confidence": null, "sourceType": "raw_text"}], "enforcementLevel": "hard", "draftingVsSubmission": "drafting"}, {"key": "define_partner_roles", "text": "The proposal must clearly define the significant role of any partner Institutions in the project.", "appliesTo": ["all"], "rationale": "Ensures that collaborations are meaningful and roles are well-defined.", "ruleClass": "must_address", "confidence": 1, "importance": "high", "sourceBlock": "mustAddress", "detectorHints": [], "draftingStage": ["team_and_partnerships"], "sourceAnchors": [{"url": null, "note": null, "quote": "The investigators may clearly define the significant role of partner Institutions in the project.", "fieldKey": null, "confidence": null, "sourceType": "raw_text"}], "enforcementLevel": "hard", "draftingVsSubmission": "drafting"}, {"key": "justify_technology_choice", "text": "Investigators must justify how the technologies to be implemented are essentially required for the livelihood enhancement of the SC community.", "appliesTo": ["all"], "rationale": "This links the technology directly to the core mission of the program.", "ruleClass": "must_address", "confidence": 1, "importance": "high", "sourceBlock": "mustAddress", "detectorHints": [], "draftingStage": ["beneficiaries"], "sourceAnchors": [{"url": null, "note": null, "quote": "The investigators may justify how the technologies to be intervened in the targeted areas is essentially required for livelihood enhancement of the SC community.", "fieldKey": null, "confidence": null, "sourceType": "raw_text"}], "enforcementLevel": "hard", "draftingVsSubmission": "drafting"}, {"key": "beneficiary_percentage", "text": "At least 60–70% of beneficiaries must belong to SC communities.", "appliesTo": ["all"], "rationale": "This is a mandatory quantitative target to ensure the project serves the intended primary demographic.", "ruleClass": "must_address", "confidence": 1, "importance": "high", "sourceBlock": "mustAddress", "detectorHints": [], "draftingStage": [], "sourceAnchors": [{"url": null, "note": null, "quote": "At least 60–70% of beneficiaries must belong to SC communities.", "fieldKey": null, "confidence": null, "sourceType": "raw_text"}], "enforcementLevel": "hard", "draftingVsSubmission": "drafting"}, {"key": "intervention_limit", "text": "Each Hub should focus on not more than 4–5 interventions.", "appliesTo": ["all"], "rationale": "This rule encourages focus and depth over breadth, preventing projects from becoming unfocused.", "ruleClass": "must_address", "confidence": 1, "importance": "high", "sourceBlock": "mustAddress", "detectorHints": [], "draftingStage": [], "sourceAnchors": [{"url": null, "note": null, "quote": "Each Hub should focus on not more than 4–5 interventions.", "fieldKey": null, "confidence": null, "sourceType": "raw_text"}], "enforcementLevel": "soft", "draftingVsSubmission": "drafting"}], "durationRules": [{"key": "project_duration", "text": "The project duration is 3 years.", "appliesTo": ["workplan"], "rationale": "This is a fixed duration for the project.", "ruleClass": "duration", "confidence": 1, "importance": "high", "sourceBlock": "durationRules", "detectorHints": ["duration_limit"], "draftingStage": ["workplan"], "sourceAnchors": [{"url": null, "note": null, "quote": "Project Duration: 3 years", "fieldKey": null, "confidence": null, "sourceType": "raw_text"}], "enforcementLevel": "hard", "draftingVsSubmission": "both"}], "sourceAnchors": [{"url": null, "note": "The content for this JSON was extracted from the provided text titled 'CALL FOR PROPOSALS (APRIL 2026) – STI HUBS' by the Department of Science and Technology, Government of India.", "quote": null, "fieldKey": null, "confidence": 1, "sourceType": "raw_text"}], "reviewerSignals": [{"key": "collaboration_encouraged", "text": "Collaborative proposals from two or three different types of institutes are encouraged.", "appliesTo": ["all"], "rationale": "The funder explicitly states a preference for collaborative projects, signaling that such proposals will be viewed more favorably.", "ruleClass": "reviewer_signal", "confidence": 1, "importance": "high", "sourceBlock": "reviewerSignals", "detectorHints": [], "draftingStage": ["thrust_alignment"], "sourceAnchors": [{"url": null, "note": null, "quote": "Type of the Lead Institute (collaborative proposal from two/three different types of Institutes will be encouraged): -", "fieldKey": null, "confidence": null, "sourceType": "raw_text"}], "enforcementLevel": "soft", "draftingVsSubmission": "drafting"}, {"key": "academic_ngo_partnership", "text": "A strong proposal will demonstrate collaboration: academic institutions must engage with local NGOs, and voluntary organizations should partner with S&T institutions.", "appliesTo": ["all"], "rationale": "This specific partnership model is presented as a requirement for effective implementation, making it a key signal of a well-structured project.", "ruleClass": "reviewer_signal", "confidence": 1, "importance": "high", "sourceBlock": "reviewerSignals", "detectorHints": [], "draftingStage": ["team_and_partnerships"], "sourceAnchors": [{"url": null, "note": null, "quote": "Collaboration: Academic institutions must engage with local NGOs for sustainable rural livelihoods planning... voluntary organizations should partner with S&T institutions and R&D labs to develop location-specific, need-based technologies.", "fieldKey": null, "confidence": null, "sourceType": "raw_text"}], "enforcementLevel": "hard", "draftingVsSubmission": "drafting"}, {"key": "beyond_state_of_art", "text": "Proposals are expected to demonstrate how the project will progress beyond the 'state-of-the-art' or the best initiatives tried by others.", "appliesTo": ["all"], "rationale": "This signals that reviewers are looking for innovation and advancement, not just replication of existing models.", "ruleClass": "reviewer_signal", "confidence": 0.98, "importance": "medium", "sourceBlock": "reviewerSignals", "detectorHints": [], "draftingStage": ["thrust_alignment"], "sourceAnchors": [{"url": null, "note": null, "quote": "demonstrate how the project will progress beyond the “state-of-art” or the best initiative tried by others in providing new innovative technological solution", "fieldKey": null, "confidence": null, "sourceType": "raw_text"}], "enforcementLevel": "soft", "draftingVsSubmission": "drafting"}, {"key": "scientific_linkages", "text": "Strong proposals will show backward connections with higher educational and scientific institutions (like Agricultural Universities, IITs, NITs, KVKs) to access frontier technologies.", "appliesTo": ["all"], "rationale": "This indicates that reviewers value projects that are scientifically grounded and connected to advanced research.", "ruleClass": "reviewer_signal", "confidence": 0.98, "importance": "medium", "sourceBlock": "reviewerSignals", "detectorHints": [], "draftingStage": ["thrust_alignment"], "sourceAnchors": [{"url": null, "note": null, "quote": "Linkages: Backward connections with higher educational and scientific institutions (Agricultural Universities, IITs, NITs, KVKs, central departments etc.) will enable access to frontier technologies.", "fieldKey": null, "confidence": null, "sourceType": "raw_text"}], "enforcementLevel": "soft", "draftingVsSubmission": "drafting"}, {"key": "community_group_involvement", "text": "Proposals that involve community groups like Self-Help Groups (SHGs), Farmer Producer Organisations (FPOs), and Farmer Producer Companies (FPCs) signal strong community engagement and potential for adoption.", "appliesTo": ["impact_outcomes"], "rationale": "This demonstrates a bottom-up approach and a mechanism for ensuring community buy-in and sustainability.", "ruleClass": "reviewer_signal", "confidence": 0.98, "importance": "medium", "sourceBlock": "reviewerSignals", "detectorHints": [], "draftingStage": ["beneficiaries", "outcomes"], "sourceAnchors": [{"url": null, "note": null, "quote": "Community Engagement: SHGs, FPOs, and FPCs should be involved to ensure reaching the community for the adaptation of the new and improved systematic approach developed and recommended for a sustainable future.", "fieldKey": null, "confidence": null, "sourceType": "raw_text"}], "enforcementLevel": "soft", "draftingVsSubmission": "drafting"}], "submissionRules": [{"key": "submission_deadline", "text": "The last date for submission of online proposals is 16/05/2026.", "appliesTo": ["all"], "rationale": "This is a hard, non-negotiable deadline for application submission.", "ruleClass": "submission", "confidence": 1, "importance": "high", "sourceBlock": "submissionRules", "detectorHints": ["submission_checklist"], "draftingStage": [], "sourceAnchors": [{"url": null, "note": null, "quote": "(LAST DATE FOR SUBMISSION OF PROPOSALS: 16/05/2026)", "fieldKey": null, "confidence": null, "sourceType": "raw_text"}], "enforcementLevel": "hard", "draftingVsSubmission": "submission"}, {"key": "online_submission_only", "text": "The project proposal must be submitted online only through DST's Electronic Project Management System (e-PMS) portal at www.onlinedst.gov.in.", "appliesTo": ["all"], "rationale": "Specifies the mandatory and sole method for proposal submission.", "ruleClass": "submission", "confidence": 1, "importance": "high", "sourceBlock": "submissionRules", "detectorHints": ["submission_checklist"], "draftingStage": [], "sourceAnchors": [{"url": null, "note": null, "quote": "The Principal Investigator should submit the project proposal online only through DST's Electronic Project Management System (e-PMS) on portal www.onlinedst.gov.in the given format along with necessary documents.", "fieldKey": null, "confidence": null, "sourceType": "raw_text"}], "enforcementLevel": "hard", "draftingVsSubmission": "submission"}, {"key": "no_other_submission_means", "text": "Proposals submitted by any other means will be summarily rejected.", "appliesTo": ["all"], "rationale": "Reinforces the exclusivity of the online portal submission method.", "ruleClass": "submission", "confidence": 1, "importance": "high", "sourceBlock": "submissionRules", "detectorHints": ["submission_checklist"], "draftingStage": [], "sourceAnchors": [{"url": null, "note": null, "quote": "Proposal submitted by any other means will be summarily rejected.", "fieldKey": null, "confidence": null, "sourceType": "raw_text"}], "enforcementLevel": "hard", "draftingVsSubmission": "submission"}, {"key": "ngo_document_submission", "text": "S&T based voluntary organizations must submit: a copy of their valid registration certificate/Trust Deed, Memorandum of Association, and byelaws; audited statements of accounts and annual reports for the last 3 financial years; and their organization's Unique ID in the NGO Darpan Portal.", "appliesTo": ["innovation"], "rationale": "These are mandatory document submissions for a specific applicant type to prove eligibility and good standing.", "ruleClass": "submission", "confidence": 1, "importance": "high", "sourceBlock": "submissionRules", "detectorHints": ["duration_limit", "submission_checklist"], "draftingStage": ["innovation"], "sourceAnchors": [{"url": null, "note": null, "quote": "In addition, the S&T based voluntary organizations are also required to submit the following documents while submission of proposal online on the DST e-PMS portal. Copy of valid registration certificate/Trust Deed, Memorandum of Association, Rules and Byelaws of the society. Audited Statement of Accounts and Annual Activity Reports of the organization for the last 3 financial years. Organization's Unique ID in NGO Darpan Portal", "fieldKey": null, "confidence": null, "sourceType": "raw_text"}], "enforcementLevel": "hard", "draftingVsSubmission": "submission"}, {"key": "signed_annexures", "text": "The enclosed annexures (Annexure I – Annexure V) should also be signed and submitted.", "appliesTo": ["all"], "rationale": "A specific procedural requirement for the application package.", "ruleClass": "submission", "confidence": 1, "importance": "high", "sourceBlock": "submissionRules", "detectorHints": ["submission_checklist"], "draftingStage": [], "sourceAnchors": [{"url": null, "note": null, "quote": "The enclosed annexures (Annexure I – Annexure V) should also be signed and submitted.", "fieldKey": null, "confidence": null, "sourceType": "raw_text"}], "enforcementLevel": "hard", "draftingVsSubmission": "submission"}, {"key": "multi_institution_agreement", "text": "For multi-institutional projects, the PI must furnish a formal agreement from the collaborating institutions/scientists.", "appliesTo": ["all"], "rationale": "This ensures that all partners are formally committed to the project.", "ruleClass": "submission", "confidence": 1, "importance": "high", "sourceBlock": "submissionRules", "detectorHints": ["submission_checklist"], "draftingStage": [], "sourceAnchors": [{"url": null, "note": null, "quote": "In case of multi-institutional project, the Principal Investigator (PI) must furnish formal agreement from the collaborating institutions/scientists...", "fieldKey": null, "confidence": null, "sourceType": "raw_text"}], "enforcementLevel": "hard", "draftingVsSubmission": "submission"}], "deliverableRules": [{"key": "socioeconomic_empowerment", "text": "A key outcome is the socioeconomic empowerment of SC communities through improved livelihood systems, new viable options, equitable growth, productivity enhancement, and social enterprise development.", "appliesTo": ["impact_outcomes"], "rationale": "This defines the primary expected impact and deliverables of the project.", "ruleClass": "deliverable", "confidence": 1, "importance": "high", "sourceBlock": "deliverableRules", "detectorHints": [], "draftingStage": ["outcomes"], "sourceAnchors": [{"url": null, "note": null, "quote": "Outcomes: STI Hubs to facilitate socioeconomic empowerment of SC communities through improvement of the existing livelihood systems, besides creation of newer and viable options, equitable growth, productivity enhancement, social enterprise development, and equity with inclusion.", "fieldKey": null, "confidence": null, "sourceType": "raw_text"}], "enforcementLevel": "soft", "draftingVsSubmission": "drafting"}, {"key": "capacity_building_deliverable", "text": "The project must build NGO capacity, expand institutional outreach, and promote sustainable knowledge for community development.", "appliesTo": ["workplan"], "rationale": "Specifies expected outcomes related to institutional and community capacity building.", "ruleClass": "deliverable", "confidence": 0.98, "importance": "medium", "sourceBlock": "deliverableRules", "detectorHints": [], "draftingStage": ["beneficiaries", "team_and_partnerships"], "sourceAnchors": [{"url": null, "note": null, "quote": "By strengthening delivery mechanisms and applying S&T interventions, it must build NGO capacity, expand institutional outreach, and promote sustainable knowledge for community development.", "fieldKey": null, "confidence": null, "sourceType": "raw_text"}], "enforcementLevel": "hard", "draftingVsSubmission": "drafting"}, {"key": "define_quantitative_deliverables", "text": "The work plan must detail expected deliverables, including anticipated quantitative output, outcome, and socio-economic impact on target beneficiaries.", "appliesTo": ["objectives", "workplan", "impact_outcomes"], "rationale": "Requires applicants to specify measurable results.", "ruleClass": "deliverable", "confidence": 1, "importance": "high", "sourceBlock": "deliverableRules", "detectorHints": [], "draftingStage": ["workplan", "outcomes"], "sourceAnchors": [{"url": null, "note": null, "quote": "Work plan and expected deliverables of project ... Expected deliverables (anticipated quantitative output, outcome & socio-economic impact on target beneficiaries)", "fieldKey": null, "confidence": null, "sourceType": "raw_text"}], "enforcementLevel": "hard", "draftingVsSubmission": "drafting"}], "evaluationCriteria": [{"key": "resource_and_skill_utilization", "text": "Interventions will be evaluated on whether they utilize available local resources and build on existing community skills.", "appliesTo": ["all"], "rationale": "This criterion favors projects that are contextually appropriate and build on existing assets.", "ruleClass": "evaluation", "confidence": 1, "importance": "high", "sourceBlock": "evaluationCriteria", "detectorHints": [], "draftingStage": ["beneficiaries"], "sourceAnchors": [{"url": null, "note": null, "quote": "Ensure interventions suggested utilize available resources and build on community skills.", "fieldKey": null, "confidence": null, "sourceType": "raw_text"}], "enforcementLevel": "soft", "draftingVsSubmission": "drafting"}, {"key": "drudgery_reduction", "text": "Proposals will be assessed on their ability to introduce technologies that reduce manual effort and improve working conditions.", "appliesTo": ["all"], "rationale": "This focuses on the quality-of-life improvements provided by the technology.", "ruleClass": "evaluation", "confidence": 1, "importance": "medium", "sourceBlock": "evaluationCriteria", "detectorHints": [], "draftingStage": ["evaluation"], "sourceAnchors": [{"url": null, "note": null, "quote": "Introduce technologies that ease manual effort and improve working conditions.", "fieldKey": null, "confidence": null, "sourceType": "raw_text"}], "enforcementLevel": "soft", "draftingVsSubmission": "drafting"}, {"key": "efficiency_enhancement", "text": "The proposed interventions should strengthen productivity and streamline livelihood processes.", "appliesTo": ["all"], "rationale": "This is a core measure of the economic impact of the technological intervention.", "ruleClass": "evaluation", "confidence": 1, "importance": "high", "sourceBlock": "evaluationCriteria", "detectorHints": [], "draftingStage": ["evaluation"], "sourceAnchors": [{"url": null, "note": null, "quote": "Strengthen productivity and streamline livelihood processes.", "fieldKey": null, "confidence": null, "sourceType": "raw_text"}], "enforcementLevel": "soft", "draftingVsSubmission": "drafting"}, {"key": "market_integration", "text": "The project's ability to enable communities to move up the value chain and access higher market opportunities will be a key criterion.", "appliesTo": ["all"], "rationale": "This criterion assesses the project's potential for significant economic uplift and market access.", "ruleClass": "evaluation", "confidence": 1, "importance": "high", "sourceBlock": "evaluationCriteria", "detectorHints": [], "draftingStage": ["evaluation"], "sourceAnchors": [{"url": null, "note": null, "quote": "Enable communities to move up the value chain and access higher market opportunities.", "fieldKey": null, "confidence": null, "sourceType": "raw_text"}], "enforcementLevel": "soft", "draftingVsSubmission": "drafting"}, {"key": "adaptability_affordability", "text": "Interventions must be cost-effective, scalable, and culturally adaptable.", "appliesTo": ["all"], "rationale": "These factors are critical for the long-term adoption and sustainability of the proposed solutions.", "ruleClass": "budget", "confidence": 1, "importance": "high", "sourceBlock": "evaluationCriteria", "detectorHints": ["budget_limit"], "draftingStage": ["budget_strategy"], "sourceAnchors": [{"url": null, "note": null, "quote": "Ensure interventions are cost-effective, scalable, and culturally adaptable.", "fieldKey": null, "confidence": null, "sourceType": "raw_text"}], "enforcementLevel": "hard", "draftingVsSubmission": "drafting"}, {"key": "environmental_safeguards", "text": "The project must avoid environmental degradation, reduce its carbon footprint, be sensitive to ecological balance, and meet or promote connected SDG objectives.", "appliesTo": ["all"], "rationale": "Ensures that projects are environmentally responsible and sustainable.", "ruleClass": "evaluation", "confidence": 1, "importance": "medium", "sourceBlock": "evaluationCriteria", "detectorHints": [], "draftingStage": ["evaluation"], "sourceAnchors": [{"url": null, "note": null, "quote": "Project avoids environmental degradation and reduces carbon footprint. Project is sensitive to any alterations in ecological balance. Must meet or promote connected SDG objectives.", "fieldKey": null, "confidence": null, "sourceType": "raw_text"}], "enforcementLevel": "hard", "draftingVsSubmission": "drafting"}, {"key": "employment_orientation", "text": "Interventions are evaluated on their ability to generate self-employment, create additional revenue, and strengthen local self-reliance without displacing existing jobs.", "appliesTo": ["all"], "rationale": "This focuses on positive, non-disruptive economic impact for the community.", "ruleClass": "evaluation", "confidence": 1, "importance": "high", "sourceBlock": "evaluationCriteria", "detectorHints": [], "draftingStage": ["evaluation"], "sourceAnchors": [{"url": null, "note": null, "quote": "Generates self-employment opportunities. Creates additional revenue streams. Does not displace existing job structures. Strengthens local self-reliance through STI.", "fieldKey": null, "confidence": null, "sourceType": "raw_text"}], "enforcementLevel": "soft", "draftingVsSubmission": "drafting"}, {"key": "capacity_building", "text": "The project will be judged on its ability to build S&T absorption capacity and improve knowledge and innovation capabilities among beneficiaries.", "appliesTo": ["innovation"], "rationale": "This criterion assesses the project's contribution to human capital development within the community.", "ruleClass": "evaluation", "confidence": 1, "importance": "medium", "sourceBlock": "evaluationCriteria", "detectorHints": [], "draftingStage": ["team_and_partnerships", "innovation"], "sourceAnchors": [{"url": null, "note": null, "quote": "Builds S&T absorption capacity. Improves knowledge and innovation capabilities among beneficiaries.", "fieldKey": null, "confidence": null, "sourceType": "raw_text"}], "enforcementLevel": "soft", "draftingVsSubmission": "drafting"}]}	null	\N	\N	2026-04-24 11:07:20.699	2026-04-24 11:08:44.885
cmoct3v8k000olyhx8rjowknf	cmoct35i7000dlyhxg0nquf1s	cmoct38x8000ilyhxdgdblrez	needs_review	gemini-2.5-pro	funding-guideline-v2	{"avoid": [{"key": "verbatim_objectives", "text": "Investigators should avoid copying the objectives listed in the call for proposals verbatim.", "rationale": "Objectives must be specific to the proposed project, not generic restatements of the funder's goals.", "confidence": 1, "importance": "high", "sourceAnchors": [{"url": null, "note": null, "quote": "The investigators may give specific objectives related to the above in the proposal for STI Hub and should avoid copying above objectives verbatim.", "fieldKey": null, "confidence": null, "sourceType": "raw_text"}]}, {"key": "direct_welfare_activities", "text": "Projects must avoid direct welfare activities.", "rationale": "The focus is on S&T-led empowerment and livelihood creation, not direct aid or charity.", "confidence": 1, "importance": "high", "sourceAnchors": [{"url": null, "note": null, "quote": "Exclusions (must avoid): Ο Direct welfare activities.", "fieldKey": null, "confidence": null, "sourceType": "raw_text"}]}, {"key": "routine_technologies", "text": "Avoid routine proposals on standardized technologies such as vermicompost, mushroom cultivation, or food processing.", "rationale": "The funder seeks innovative or novel applications of technology, not replication of common, well-established interventions.", "confidence": 1, "importance": "high", "sourceAnchors": [{"url": null, "note": null, "quote": "Exclusions (must avoid): Ο Routine proposals on standardized technologies (e.g., vermicompost, mushroom cultivation, food processing).", "fieldKey": null, "confidence": null, "sourceType": "raw_text"}]}, {"key": "overlapping_activities", "text": "Activities that overlap with those of line ministries, KVK extensions, or NRLM/SRLM programmes must be avoided.", "rationale": "The project should address a unique gap and not duplicate the work of other existing government programs.", "confidence": 1, "importance": "high", "sourceAnchors": [{"url": null, "note": null, "quote": "Exclusions (must avoid): Ο Activities overlapping with line ministries, KVK extensions, NRLM/SRLM programmes.", "fieldKey": null, "confidence": null, "sourceType": "raw_text"}]}, {"key": "improper_milestones", "text": "Do not list baseline surveys, recruitment of project staff, or the purchase of capital equipment as project milestones or targets in the work plan.", "rationale": "Milestones should represent substantive project achievements and deliverables, not administrative or preparatory tasks.", "confidence": 1, "importance": "high", "sourceAnchors": [{"url": null, "note": null, "quote": "please don't give baseline survey, recruitment of project staff and purchase of Capital as milestone/ target.", "fieldKey": null, "confidence": null, "sourceType": "raw_text"}]}, {"key": "job_displacement", "text": "Technological interventions should not displace existing job structures.", "rationale": "The project's goal is to create and enhance employment, not to cause job losses through automation or other changes.", "confidence": 1, "importance": "medium", "sourceAnchors": [{"url": null, "note": null, "quote": "Does not displace existing job structures.", "fieldKey": null, "confidence": null, "sourceType": "raw_text"}]}, {"key": "irrelevant_proposals", "text": "Only proposals for STI Hubs should be submitted against this call; other types of proposals will be summarily rejected.", "rationale": "This is a specific call for a specific type of project, and off-topic submissions will not be considered.", "confidence": 1, "importance": "high", "sourceAnchors": [{"url": null, "note": null, "quote": "Only the proposals for STI Hubs should be submitted against this call. Proposals other than STI Hubs submitted against this call will be summarily rejected.", "fieldKey": null, "confidence": null, "sourceType": "raw_text"}]}], "priorities": [{"key": "sc_community_focus", "text": "The program provides financial support for Science Technology and Innovation (STI) Hubs for SCHEDULED CASTE (SC) COMMUNITIES only.", "rationale": "This is the primary and exclusive beneficiary group for the funding call.", "confidence": 1, "importance": "high", "sourceAnchors": [{"url": null, "note": null, "quote": "invites project proposals for financial support under the Science Technology and Innovation (STI) Hubs programme for SCHEDULED CASTE (SC) COMMUNITIES only.", "fieldKey": null, "confidence": null, "sourceType": "raw_text"}]}, {"key": "s&t_for_empowerment", "text": "The initiative aims to foster inclusive growth by leveraging science and technology for community empowerment, livelihood enhancement, and sustainable development.", "rationale": "This defines the core strategic goal of the program: using S&T for socio-economic impact.", "confidence": 1, "importance": "high", "sourceAnchors": [{"url": null, "note": null, "quote": "This initiative aims to foster inclusive growth by leveraging science and technology for community empowerment, livelihood enhancement, and sustainable development.", "fieldKey": null, "confidence": null, "sourceType": "raw_text"}]}, {"key": "address_livelihood_gaps", "text": "A primary objective is to address the weakest linkages in the predominant livelihood systems of the SC community through Science, Technology and Innovation (STI) interventions.", "rationale": "Proposals should focus on identifying and solving specific, critical problems within existing livelihood structures.", "confidence": 1, "importance": "high", "sourceAnchors": [{"url": null, "note": null, "quote": "(1) To address the weakest linkages in the predominant livelihood systems of the SC community through Science, Technology and Innovation (STI) interventions.", "fieldKey": null, "confidence": null, "sourceType": "raw_text"}]}, {"key": "social_enterprise_creation", "text": "Proposals should aim to identify and create social enterprises based on the strengths in livelihood systems.", "rationale": "The funder prioritizes creating sustainable, community-owned business structures.", "confidence": 1, "importance": "high", "sourceAnchors": [{"url": null, "note": null, "quote": "(2) To identify and create social enterprises based on the strengths in livelihood systems.", "fieldKey": null, "confidence": null, "sourceType": "raw_text"}]}, {"key": "indigenous_knowledge_systems", "text": "A key objective is to harness, document, research, validate, and conserve Indigenous Knowledge Systems (IKS) and integrate them with S&T for sustainable development.", "rationale": "This highlights the value placed on local knowledge and its integration with modern technology, rather than replacement.", "confidence": 1, "importance": "medium", "sourceAnchors": [{"url": null, "note": null, "quote": "(3) To harness, document, research, validate and conserve the Indigenous Knowledge Systems (IKS), skills and practices of different communities through inputs of Science and Technology to integrate IKS into appropriate technology, innovation and development for sustainable and economically viable development model of practices in livelihood systems.", "fieldKey": null, "confidence": null, "sourceType": "raw_text"}]}], "budgetRules": [{"key": "no_international_travel", "text": "International travel is not permissible under the projects.", "rationale": "This is a strict prohibition on a specific type of cost.", "confidence": 1, "importance": "high", "sourceAnchors": [{"url": null, "note": null, "quote": "International travel is not permissible under the projects.", "fieldKey": null, "confidence": null, "sourceType": "raw_text"}]}, {"key": "staff_payment_norms", "text": "Staff recruited for a project should be paid as per the norms and guidelines of the DST.", "rationale": "Personnel costs must adhere to the funder's established pay scales.", "confidence": 1, "importance": "high", "sourceAnchors": [{"url": null, "note": null, "quote": "Staff recruited for a project should be paid as per the norms and guidelines of the DST.", "fieldKey": null, "confidence": null, "sourceType": "raw_text"}]}, {"key": "multi_institution_budget", "text": "For multi-institutional projects, the Principal Investigator must furnish a separate budget for each of the implementing institutions.", "rationale": "Financial accountability must be clearly delineated for each partner organization.", "confidence": 1, "importance": "high", "sourceAnchors": [{"url": null, "note": null, "quote": "In case of multi-institutional project, the Principal Investigator (PI) must furnish formal agreement from the collaborating institutions/scientists along with separate budget for each of the implementing institutions.", "fieldKey": null, "confidence": null, "sourceType": "raw_text"}]}, {"key": "construction_cost_limits", "text": "The budget under construction cost is only for low-cost structures like a Common Facility Centre (CFC) and/or renovation or refurbishing of existing space, not for construction of new buildings or structures.", "rationale": "This rule strictly limits capital expenditure on construction to prevent large-scale building projects.", "confidence": 1, "importance": "high", "sourceAnchors": [{"url": null, "note": null, "quote": "The budget under construction cost is only for low-cost structures like Common Facility Centre (CFC) and/or renovation or refurbishing of existing space and not for construction of new buildings or structures.", "fieldKey": null, "confidence": null, "sourceType": "raw_text"}]}, {"key": "equipment_quotations", "text": "If the project is approved, a minimum of 3 budgetary quotations will be required to support estimates for equipment.", "rationale": "This is a post-approval requirement but informs the need for realistic and justifiable equipment costs in the proposal.", "confidence": 1, "importance": "medium", "sourceAnchors": [{"url": null, "note": null, "quote": "Budgetary quotations (min. 3 no.) will be required in support of estimates for equipment, if project is approved for financial support.", "fieldKey": null, "confidence": null, "sourceType": "raw_text"}]}, {"key": "review_meeting_budget", "text": "A tentative budget should be proposed for two DST field visits/annual review meetings per year.", "rationale": "Applicants must proactively budget for funder-mandated oversight activities.", "confidence": 1, "importance": "medium", "sourceAnchors": [{"url": null, "note": null, "quote": "DST's Field visits/annual review meetings etc. (Tentative budget to be proposed for two meetings per year and should cover the travel cost, accommodation and local field visits of 4-6 experts)", "fieldKey": null, "confidence": null, "sourceType": "raw_text"}]}], "formatRules": [{"key": "project_summary_limit", "text": "The Project Summary must be 250 words only.", "rationale": "A strict word limit for a key proposal section.", "confidence": 1, "importance": "high", "sourceAnchors": [{"url": null, "note": null, "quote": "Project Summary (in 250 words only...)", "fieldKey": null, "confidence": null, "sourceType": "raw_text"}]}, {"key": "project_title_content", "text": "The Project Title should include the problem, proposed solution/technology, target community/beneficiaries, and the name of implementing Districts and State.", "rationale": "Specifies the required components of the project title for clarity and searchability.", "confidence": 1, "importance": "medium", "sourceAnchors": [{"url": null, "note": null, "quote": "Project Title (should include problem, proposed solution/technology, target community/beneficiaries and name of implementing Districts and State for establishment of STI hub/ WTP/SUNIL etc.)", "fieldKey": null, "confidence": null, "sourceType": "raw_text"}]}, {"key": "objectives_limit", "text": "The proposal should contain only 4-5 objectives.", "rationale": "A numerical limit on the number of project objectives to ensure focus.", "confidence": 1, "importance": "medium", "sourceAnchors": [{"url": null, "note": null, "quote": "Proposed Objectives (aligned with title of project and 4-5 only)", "fieldKey": null, "confidence": null, "sourceType": "raw_text"}]}, {"key": "problem_statement_limit", "text": "The problem statement section is limited to 200 words only.", "rationale": "Strict word limit for the problem description.", "confidence": 1, "importance": "medium", "sourceAnchors": [{"url": null, "note": null, "quote": "State the target population related problem you seek to address and brief of their Socio-Economic status, in 200 words only", "fieldKey": null, "confidence": null, "sourceType": "raw_text"}]}, {"key": "pi_work_summary_limit", "text": "Summary of work accomplished by the PI/Lead Institute in the proposed area during the last 5 years is limited to 100 words.", "rationale": "Strict word limit for demonstrating prior experience.", "confidence": 1, "importance": "medium", "sourceAnchors": [{"url": null, "note": null, "quote": "Summary of work accomplished by PI/ Lead Institute in the proposed area during last 5 years (100 words):", "fieldKey": null, "confidence": null, "sourceType": "raw_text"}]}, {"key": "various_word_limits", "text": "Multiple sections have strict word limits: Industrial Scenario (100 words), Existing solutions (200 words), Government Initiatives (100 words), Community participation (100 words), Equipment plan (50 words), Dissemination plan (50 words), Sustainability plan (100 words), Relevance to SMEs (50 words), Replication plan (50 words), and PI Experience (50 words).", "rationale": "This summarizes numerous specific word count constraints throughout the application form that must be adhered to.", "confidence": 1, "importance": "medium", "sourceAnchors": [{"url": null, "note": null, "quote": "Brief Industrial Scenario of the target area, in 100 words only... Existing regional/ National/ International solutions for the proposed problem, (in 200 words only)... Any other Government National Initiatives related to proposed activities to solve this problem (mention outcomes of the initiatives, in 100 words only)... Details/Mechanism for ensuring the involvement and participation of target population in the project area, (in 100 words only)... Plan of the institution about the usage, maintenance and retention of capital equipment to be procured under project (in 50 words only)... PUBLICITY, PROMOTION & DISSEMINATION PLAN... (in 50 words only)... Self-sustainability/revenue generation plan of the project work, in 100 words only... Relevance of the proposed interventions to the existing Micro & Small Enterprises... (in 50 words only)... Possibility of replication of project in similar areas... (in 50 words only)... Field of Experience relevant to current proposal area (in 50 words only)", "fieldKey": null, "confidence": null, "sourceType": "raw_text"}]}, {"key": "publications_limit", "text": "Applicants can list a maximum of 10 significant publications and a maximum of 10 publications from the last five years related to the proposed area.", "rationale": "A numerical limit on the number of publications to be listed.", "confidence": 1, "importance": "low", "sourceAnchors": [{"url": null, "note": null, "quote": "Significant publications (Maximum 10) ... List of proposed area related publications from last five years (Maximum 10)", "fieldKey": null, "confidence": null, "sourceType": "raw_text"}]}], "mustAddress": [{"key": "pra_swot_analysis", "text": "Investigators must clearly specify the relevance of objectives based strictly on PRA (Participatory Rural Appraisal) and SWOT analysis conducted in the targeted project area.", "rationale": "This requires that project objectives are evidence-based and grounded in a thorough analysis of the local context.", "confidence": 1, "importance": "high", "sourceAnchors": [{"url": null, "note": null, "quote": "The investigators may clearly specify the relevance of objectives strictly based on PRA and SWOT analysis done in the targeted project area.", "fieldKey": null, "confidence": null, "sourceType": "raw_text"}]}, {"key": "quantify_socioeconomic_enhancement", "text": "The proposal must clearly indicate the quantum increase in socioeconomic enhancement for stakeholders resulting from the technological interventions.", "rationale": "Reviewers expect specific, measurable projections of the project's impact on the community's economic status.", "confidence": 1, "importance": "high", "sourceAnchors": [{"url": null, "note": null, "quote": "The investigators may clearly indicate the quantum increase in socioeconomic enhancement of stake holders after intervention of the location specific technologies.", "fieldKey": null, "confidence": null, "sourceType": "raw_text"}]}, {"key": "justify_hub_establishment", "text": "The proposal must clearly establish the significance of establishing the STI Hub and its impact on the targeted areas.", "rationale": "The proposal needs a strong justification for why a Hub is the right solution for the identified problems.", "confidence": 1, "importance": "medium", "sourceAnchors": [{"url": null, "note": null, "quote": "The investigators may clearly establish the significance of establishment of STI Hub and its impact on the targeted areas.", "fieldKey": null, "confidence": null, "sourceType": "raw_text"}]}, {"key": "define_partner_roles", "text": "The proposal must clearly define the significant role of partner Institutions in the project.", "rationale": "Partnerships should be meaningful and well-defined, not just nominal.", "confidence": 1, "importance": "medium", "sourceAnchors": [{"url": null, "note": null, "quote": "The investigators may clearly define the significant role of partner Institutions in the project.", "fieldKey": null, "confidence": null, "sourceType": "raw_text"}]}, {"key": "justify_technology_choice", "text": "Investigators must justify how the proposed technologies are essentially required for the livelihood enhancement of the SC community.", "rationale": "There must be a clear, direct link between the chosen technology and the specific livelihood needs of the community.", "confidence": 1, "importance": "high", "sourceAnchors": [{"url": null, "note": null, "quote": "The investigators may justify how the technologies to be intervened in the targeted areas is essentially required for livelihood enhancement of the SC community.", "fieldKey": null, "confidence": null, "sourceType": "raw_text"}]}, {"key": "academic_ngo_collaboration", "text": "Academic institutions must engage with local NGOs for sustainable rural livelihoods planning and knowledge dissemination.", "rationale": "This collaboration is mandatory for academic applicants to ensure field-level implementation and community reach.", "confidence": 1, "importance": "high", "sourceAnchors": [{"url": null, "note": null, "quote": "Academic institutions must engage with local NGOs for sustainable rural livelihoods planning, and dissemination of the knowledge and technological know-how gained through the project to the target populations;", "fieldKey": null, "confidence": null, "sourceType": "raw_text"}]}, {"key": "ngo_s&t_collaboration", "text": "Voluntary organizations should partner with S&T institutions and R&D labs to develop location-specific, need-based technologies.", "rationale": "This collaboration is a strong expectation for NGO applicants to ensure technological rigor.", "confidence": 1, "importance": "high", "sourceAnchors": [{"url": null, "note": null, "quote": "voluntary organizations should partner with S&T institutions and R&D labs to develop location-specific, need-based technologies.", "fieldKey": null, "confidence": null, "sourceType": "raw_text"}]}, {"key": "location_criteria", "text": "STI Hubs should be established in areas with a predominant SC population.", "rationale": "The project's geographical location must align with the target demographic.", "confidence": 1, "importance": "high", "sourceAnchors": [{"url": null, "note": null, "quote": "STI Hubs should be established in areas with a predominant SC population.", "fieldKey": null, "confidence": null, "sourceType": "raw_text"}]}, {"key": "beneficiary_percentage", "text": "At least 60–70% of beneficiaries must belong to SC communities.", "rationale": "This is a strict, quantitative requirement for beneficiary composition.", "confidence": 1, "importance": "high", "sourceAnchors": [{"url": null, "note": null, "quote": "At least 60–70% of beneficiaries must belong to SC communities.", "fieldKey": null, "confidence": null, "sourceType": "raw_text"}]}, {"key": "intervention_limit", "text": "Each Hub should focus on not more than 4–5 interventions.", "rationale": "This rule promotes depth and focus over breadth, preventing projects from becoming too diffuse.", "confidence": 1, "importance": "medium", "sourceAnchors": [{"url": null, "note": null, "quote": "Each Hub should focus on not more than 4–5 interventions.", "fieldKey": null, "confidence": null, "sourceType": "raw_text"}]}, {"key": "sustainability_pathway", "text": "The project must show and enable the community the pathway to achieve sustainability after the project period is over.", "rationale": "A clear, credible plan for long-term viability beyond the grant period is a mandatory proposal component.", "confidence": 1, "importance": "high", "sourceAnchors": [{"url": null, "note": null, "quote": "The project must show and enable the community the pathway to achieve sustainability after the project period is over.", "fieldKey": null, "confidence": null, "sourceType": "raw_text"}]}, {"key": "sdg_alignment", "text": "The project must meet or promote connected SDG objectives.", "rationale": "Proposals need to explicitly connect their activities and outcomes to the Sustainable Development Goals.", "confidence": 1, "importance": "medium", "sourceAnchors": [{"url": null, "note": null, "quote": "Must meet or promote connected SDG objectives.", "fieldKey": null, "confidence": null, "sourceType": "raw_text"}]}, {"key": "long_term_sustainability_system", "text": "The project must create a robust system for long-term sustainability, and the key points and process of this system must be clearly enumerated in the proposal.", "rationale": "This is a core objective requiring a detailed plan for how the project's impact will continue after funding ends.", "confidence": 1, "importance": "high", "sourceAnchors": [{"url": null, "note": null, "quote": "To create a robust system in place for long term sustainability of the project undertaken, key points of sustainability and process must be clearly enumerated.", "fieldKey": null, "confidence": null, "sourceType": "raw_text"}]}], "durationRules": [{"key": "project_duration", "text": "The project duration is 3 years.", "rationale": "This is a fixed duration for all projects funded under this call.", "confidence": 1, "importance": "high", "sourceAnchors": [{"url": null, "note": null, "quote": "Project Duration: 3 years", "fieldKey": null, "confidence": null, "sourceType": "raw_text"}]}], "sourceAnchors": [], "reviewerSignals": [{"key": "collaborative_model", "text": "A strong proposal will follow a collaborative, networked, and partnership model to address last-mile challenges in technology delivery and management.", "rationale": "The funder explicitly values proposals that demonstrate a robust partnership approach.", "confidence": 0.95, "importance": "high", "sourceAnchors": [{"url": null, "note": null, "quote": "Framework: Setting up of STI Hubs to follow collaborative, networked, and partnership models to address last-mile challenges in technology induction, delivery, management, utilization, and extension.", "fieldKey": null, "confidence": null, "sourceType": "raw_text"}]}, {"key": "collaborative_proposal_encouraged", "text": "A collaborative proposal from two or three different types of institutes will be encouraged.", "rationale": "The application form explicitly signals that proposals involving multiple types of institutions (e.g., academic, NGO) are viewed favorably.", "confidence": 1, "importance": "medium", "sourceAnchors": [{"url": null, "note": null, "quote": "Type of the Lead Institute (collaborative proposal from two/three different types of Institutes will be encouraged)", "fieldKey": null, "confidence": null, "sourceType": "raw_text"}]}, {"key": "strong_linkages", "text": "Proposals demonstrating backward connections with higher educational and scientific institutions (e.g., Agricultural Universities, IITs, NITs) to access frontier technologies will be viewed favorably.", "rationale": "This indicates that leveraging high-level scientific expertise is a mark of a strong project.", "confidence": 0.95, "importance": "medium", "sourceAnchors": [{"url": null, "note": null, "quote": "Linkages: Backward connections with higher educational and scientific institutions (Agricultural Universities, IITs, NITs, KVKs, central departments etc.) will enable access to frontier technologies.", "fieldKey": null, "confidence": null, "sourceType": "raw_text"}]}, {"key": "deep_community_engagement", "text": "A strong proposal will involve community organizations like Self-Help Groups (SHGs), Farmer Producer Organisations (FPOs), and Farmer Producer Companies (FPCs) to ensure community adoption.", "rationale": "Demonstrating genuine, structured community involvement is a positive signal.", "confidence": 0.95, "importance": "medium", "sourceAnchors": [{"url": null, "note": null, "quote": "Community Engagement: SHGs, FPOs, and FPCs should be involved to ensure reaching the community for the adaptation of the new and improved systematic approach developed and recommended for a sustainable future.", "fieldKey": null, "confidence": null, "sourceType": "raw_text"}]}, {"key": "novel_technologies", "text": "Proposals that develop and deliver novel or innovative technologies are likely to be viewed more favorably than those using standard ones.", "rationale": "The exclusion of routine technologies implies a preference for innovation.", "confidence": 0.9, "importance": "high", "sourceAnchors": [{"url": null, "note": null, "quote": "Focus Areas Ο ...Develops and delivers novel/innovative technologies.", "fieldKey": null, "confidence": null, "sourceType": "raw_text"}]}], "submissionRules": [{"key": "online_submission_only", "text": "The project proposal must be submitted online only through DST's Electronic Project Management System (e-PMS) at www.onlinedst.gov.in.", "rationale": "This is the only accepted method for proposal submission.", "confidence": 1, "importance": "high", "sourceAnchors": [{"url": null, "note": null, "quote": "The Principal Investigator should submit the project proposal online only through DST's Electronic Project Management System (e-PMS) on portal www.onlinedst.gov.in the given format along with necessary documents.", "fieldKey": null, "confidence": null, "sourceType": "raw_text"}]}, {"key": "no_alternate_submission", "text": "Proposals submitted by any other means will be summarily rejected.", "rationale": "Reinforces the mandatory nature of the online portal submission.", "confidence": 1, "importance": "high", "sourceAnchors": [{"url": null, "note": null, "quote": "Proposal submitted by any other means will be summarily rejected.", "fieldKey": null, "confidence": null, "sourceType": "raw_text"}]}, {"key": "submission_deadline", "text": "The Last Date for Submission of Online Proposals is 16/05/2026.", "rationale": "This is the final, non-negotiable deadline for proposal submission.", "confidence": 1, "importance": "high", "sourceAnchors": [{"url": null, "note": null, "quote": "The Last Date for Submission of Online Proposals is 16/05/2026 after which the web-link will be automatically disabled for any usage.", "fieldKey": null, "confidence": null, "sourceType": "raw_text"}]}, {"key": "annexure_submission", "text": "The enclosed annexures (Annexure I – Annexure V) must also be signed and submitted.", "rationale": "A procedural requirement for submitting signed supporting documents.", "confidence": 1, "importance": "high", "sourceAnchors": [{"url": null, "note": null, "quote": "The enclosed annexures (Annexure I – Annexure V) should also be signed and submitted.", "fieldKey": null, "confidence": null, "sourceType": "raw_text"}]}, {"key": "multi_institution_agreement", "text": "For multi-institutional projects, the PI must furnish a formal agreement from the collaborating institutions/scientists.", "rationale": "A formal agreement is a required submission document for collaborative proposals.", "confidence": 1, "importance": "high", "sourceAnchors": [{"url": null, "note": null, "quote": "In case of multi-institutional project, the Principal Investigator (PI) must furnish formal agreement from the collaborating institutions/scientists...", "fieldKey": null, "confidence": null, "sourceType": "raw_text"}]}], "deliverableRules": [{"key": "socioeconomic_empowerment", "text": "A key outcome is the socioeconomic empowerment of SC communities through improved livelihood systems, creation of new options, and equitable growth.", "rationale": "This defines the ultimate impact and deliverable of the project.", "confidence": 1, "importance": "high", "sourceAnchors": [{"url": null, "note": null, "quote": "Outcomes: STI Hubs to facilitate socioeconomic empowerment of SC communities through improvement of the existing livelihood systems, besides creation of newer and viable options, equitable growth, productivity enhancement, social enterprise development, and equity with inclusion.", "fieldKey": null, "confidence": null, "sourceType": "raw_text"}]}, {"key": "ngo_capacity_building", "text": "Projects must build NGO capacity, expand institutional outreach, and promote sustainable knowledge for community development.", "rationale": "Deliverables include strengthening the local ecosystem, not just direct intervention.", "confidence": 1, "importance": "medium", "sourceAnchors": [{"url": null, "note": null, "quote": "By strengthening delivery mechanisms and applying S&T interventions, it must build NGO capacity, expand institutional outreach, and promote sustainable knowledge for community development.", "fieldKey": null, "confidence": null, "sourceType": "raw_text"}]}, {"key": "quantitative_outputs", "text": "The work plan should define expected deliverables in terms of anticipated quantitative output, outcome, and socio-economic impact on target beneficiaries.", "rationale": "Reviewers expect specific, measurable deliverables to be listed in the proposal.", "confidence": 1, "importance": "high", "sourceAnchors": [{"url": null, "note": null, "quote": "Expected deliverables (anticipated quantitative output, outcome & socio-economic impact on target beneficiaries)", "fieldKey": null, "confidence": null, "sourceType": "raw_text"}]}, {"key": "ipr_generation", "text": "Expected outputs include Intellectual Property Rights (IPR) such as Geographical Indication (GI) tags, copyrights, patents, and trademarks.", "rationale": "The funder encourages the formalization of intellectual property as a project deliverable.", "confidence": 1, "importance": "low", "sourceAnchors": [{"url": null, "note": null, "quote": "IPR on technology projects process design | • Geographical Indication (GI) tags | (details of applied/ granted) | • Copyright • Trademarks/ Trade secrets • Patents", "fieldKey": null, "confidence": null, "sourceType": "raw_text"}]}, {"key": "contribution_to_sdgs", "text": "A required deliverable is the project's contribution towards Sustainable Development Goals (SDGs) and National Missions (NMs), which must be explicitly mapped.", "rationale": "Projects must demonstrate alignment with and contribution to broader national and international development goals.", "confidence": 1, "importance": "medium", "sourceAnchors": [{"url": null, "note": null, "quote": "Contribution towards Sustainable Development Goals (SDGs) and National Missions (NMs)- provide name of indicator of project mapped with SDGs and NMs", "fieldKey": null, "confidence": null, "sourceType": "raw_text"}]}], "evaluationCriteria": [{"key": "resource_utilization", "text": "Interventions will be evaluated on whether they utilize available local resources and build on community skills.", "rationale": "Projects should be contextually appropriate, leveraging existing assets and knowledge.", "confidence": 1, "importance": "medium", "sourceAnchors": [{"url": null, "note": null, "quote": "Ensure interventions suggested utilize available resources and build on community skills.", "fieldKey": null, "confidence": null, "sourceType": "raw_text"}]}, {"key": "drudgery_reduction", "text": "Technologies will be assessed on their ability to ease manual effort and improve working conditions.", "rationale": "Improving the quality of life and work for beneficiaries is a key evaluation criterion.", "confidence": 1, "importance": "medium", "sourceAnchors": [{"url": null, "note": null, "quote": "Introduce technologies that ease manual effort and improve working conditions.", "fieldKey": null, "confidence": null, "sourceType": "raw_text"}]}, {"key": "efficiency_enhancement", "text": "The project will be judged on its capacity to strengthen productivity and streamline livelihood processes.", "rationale": "Demonstrating clear gains in efficiency is a measure of a successful intervention.", "confidence": 1, "importance": "medium", "sourceAnchors": [{"url": null, "note": null, "quote": "Strengthen productivity and streamline livelihood processes.", "fieldKey": null, "confidence": null, "sourceType": "raw_text"}]}, {"key": "market_integration", "text": "A criterion for selection is whether the project enables communities to move up the value chain and access higher market opportunities.", "rationale": "Projects should connect beneficiaries to larger economic systems, not just improve subsistence.", "confidence": 1, "importance": "high", "sourceAnchors": [{"url": null, "note": null, "quote": "Enable communities to move up the value chain and access higher market opportunities.", "fieldKey": null, "confidence": null, "sourceType": "raw_text"}]}, {"key": "adaptability_affordability", "text": "Interventions are evaluated on being cost-effective, scalable, and culturally adaptable.", "rationale": "Proposed solutions must be practical and sustainable for the target community to adopt and maintain.", "confidence": 1, "importance": "high", "sourceAnchors": [{"url": null, "note": null, "quote": "Ensure interventions are cost-effective, scalable, and culturally adaptable.", "fieldKey": null, "confidence": null, "sourceType": "raw_text"}]}, {"key": "sustainability_linkages", "text": "The proposal will be evaluated on the strength of its linkages to knowledge institutes, field-level organizations, and national/state-level programmes to ensure sustainability.", "rationale": "Strong partnerships are seen as crucial for long-term success and technological relevance.", "confidence": 1, "importance": "high", "sourceAnchors": [{"url": null, "note": null, "quote": "Links to knowledge institute(s) to ensure technology updates and capacity enhancement Ο Links to field level organization to ensure last mile connectivity Ο Links interventions to national/state-level programmes.", "fieldKey": null, "confidence": null, "sourceType": "raw_text"}]}, {"key": "environmental_safeguards", "text": "The project's design will be assessed on whether it avoids environmental degradation, reduces carbon footprint, and is sensitive to ecological balance.", "rationale": "Environmental sustainability is a key consideration for all proposed interventions.", "confidence": 1, "importance": "medium", "sourceAnchors": [{"url": null, "note": null, "quote": "Project avoids environmental degradation and reduces carbon footprint. Ο Project is sensitive to any alterations in ecological balance.", "fieldKey": null, "confidence": null, "sourceType": "raw_text"}]}, {"key": "employment_orientation", "text": "Projects will be evaluated on their ability to generate self-employment opportunities and create additional revenue streams.", "rationale": "The ultimate goal is economic self-reliance, which is measured by job and income creation.", "confidence": 1, "importance": "high", "sourceAnchors": [{"url": null, "note": null, "quote": "Generates self-employment opportunities. Ο Creates additional revenue streams.", "fieldKey": null, "confidence": null, "sourceType": "raw_text"}]}, {"key": "simplicity_of_skills", "text": "The skills needed by beneficiaries for the project must be simple and easy to grasp.", "rationale": "This ensures a low barrier to entry for community members and increases the likelihood of successful adoption.", "confidence": 1, "importance": "medium", "sourceAnchors": [{"url": null, "note": null, "quote": "Skills needed and associated for the beneficiaries of the project must be simple and easy to grasp.", "fieldKey": null, "confidence": null, "sourceType": "raw_text"}]}, {"key": "capacity_building", "text": "The project will be assessed on its ability to build S&T absorption capacity and improve knowledge and innovation capabilities among beneficiaries.", "rationale": "Beyond direct economic benefits, the project should leave the community with enhanced skills and knowledge.", "confidence": 1, "importance": "medium", "sourceAnchors": [{"url": null, "note": null, "quote": "Builds S&T absorption capacity. Ο Improves knowledge and innovation capabilities among beneficiaries.", "fieldKey": null, "confidence": null, "sourceType": "raw_text"}]}]}	{"avoid": [{"key": "verbatim_objectives", "text": "Investigators should avoid copying the objectives listed in the call for proposals verbatim.", "appliesTo": ["all"], "rationale": "Objectives must be specific to the proposed project, not generic restatements of the funder's goals.", "ruleClass": "avoid", "confidence": 1, "importance": "high", "sourceBlock": "avoid", "detectorHints": [], "draftingStage": [], "sourceAnchors": [{"url": null, "note": null, "quote": "The investigators may give specific objectives related to the above in the proposal for STI Hub and should avoid copying above objectives verbatim.", "fieldKey": null, "confidence": null, "sourceType": "raw_text"}], "enforcementLevel": "soft", "draftingVsSubmission": "drafting"}, {"key": "direct_welfare_activities", "text": "Projects must avoid direct welfare activities.", "appliesTo": ["all"], "rationale": "The focus is on S&T-led empowerment and livelihood creation, not direct aid or charity.", "ruleClass": "avoid", "confidence": 1, "importance": "high", "sourceBlock": "avoid", "detectorHints": [], "draftingStage": [], "sourceAnchors": [{"url": null, "note": null, "quote": "Exclusions (must avoid): Ο Direct welfare activities.", "fieldKey": null, "confidence": null, "sourceType": "raw_text"}], "enforcementLevel": "hard", "draftingVsSubmission": "drafting"}, {"key": "routine_technologies", "text": "Avoid routine proposals on standardized technologies such as vermicompost, mushroom cultivation, or food processing.", "appliesTo": ["all"], "rationale": "The funder seeks innovative or novel applications of technology, not replication of common, well-established interventions.", "ruleClass": "avoid", "confidence": 1, "importance": "high", "sourceBlock": "avoid", "detectorHints": [], "draftingStage": [], "sourceAnchors": [{"url": null, "note": null, "quote": "Exclusions (must avoid): Ο Routine proposals on standardized technologies (e.g., vermicompost, mushroom cultivation, food processing).", "fieldKey": null, "confidence": null, "sourceType": "raw_text"}], "enforcementLevel": "soft", "draftingVsSubmission": "drafting"}, {"key": "overlapping_activities", "text": "Activities that overlap with those of line ministries, KVK extensions, or NRLM/SRLM programmes must be avoided.", "appliesTo": ["all"], "rationale": "The project should address a unique gap and not duplicate the work of other existing government programs.", "ruleClass": "avoid", "confidence": 1, "importance": "high", "sourceBlock": "avoid", "detectorHints": [], "draftingStage": [], "sourceAnchors": [{"url": null, "note": null, "quote": "Exclusions (must avoid): Ο Activities overlapping with line ministries, KVK extensions, NRLM/SRLM programmes.", "fieldKey": null, "confidence": null, "sourceType": "raw_text"}], "enforcementLevel": "hard", "draftingVsSubmission": "drafting"}, {"key": "improper_milestones", "text": "Do not list baseline surveys, recruitment of project staff, or the purchase of capital equipment as project milestones or targets in the work plan.", "appliesTo": ["problem_need", "workplan"], "rationale": "Milestones should represent substantive project achievements and deliverables, not administrative or preparatory tasks.", "ruleClass": "budget", "confidence": 1, "importance": "high", "sourceBlock": "avoid", "detectorHints": ["budget_limit"], "draftingStage": ["workplan", "budget_strategy"], "sourceAnchors": [{"url": null, "note": null, "quote": "please don't give baseline survey, recruitment of project staff and purchase of Capital as milestone/ target.", "fieldKey": null, "confidence": null, "sourceType": "raw_text"}], "enforcementLevel": "hard", "draftingVsSubmission": "drafting"}, {"key": "job_displacement", "text": "Technological interventions should not displace existing job structures.", "appliesTo": ["all"], "rationale": "The project's goal is to create and enhance employment, not to cause job losses through automation or other changes.", "ruleClass": "avoid", "confidence": 1, "importance": "medium", "sourceBlock": "avoid", "detectorHints": [], "draftingStage": [], "sourceAnchors": [{"url": null, "note": null, "quote": "Does not displace existing job structures.", "fieldKey": null, "confidence": null, "sourceType": "raw_text"}], "enforcementLevel": "hard", "draftingVsSubmission": "drafting"}, {"key": "irrelevant_proposals", "text": "Only proposals for STI Hubs should be submitted against this call; other types of proposals will be summarily rejected.", "appliesTo": ["all"], "rationale": "This is a specific call for a specific type of project, and off-topic submissions will not be considered.", "ruleClass": "avoid", "confidence": 1, "importance": "high", "sourceBlock": "avoid", "detectorHints": [], "draftingStage": [], "sourceAnchors": [{"url": null, "note": null, "quote": "Only the proposals for STI Hubs should be submitted against this call. Proposals other than STI Hubs submitted against this call will be summarily rejected.", "fieldKey": null, "confidence": null, "sourceType": "raw_text"}], "enforcementLevel": "soft", "draftingVsSubmission": "drafting"}], "priorities": [{"key": "sc_community_focus", "text": "The program provides financial support for Science Technology and Innovation (STI) Hubs for SCHEDULED CASTE (SC) COMMUNITIES only.", "appliesTo": ["innovation"], "rationale": "This is the primary and exclusive beneficiary group for the funding call.", "ruleClass": "priority", "confidence": 1, "importance": "high", "sourceBlock": "priorities", "detectorHints": [], "draftingStage": ["innovation"], "sourceAnchors": [{"url": null, "note": null, "quote": "invites project proposals for financial support under the Science Technology and Innovation (STI) Hubs programme for SCHEDULED CASTE (SC) COMMUNITIES only.", "fieldKey": null, "confidence": null, "sourceType": "raw_text"}], "enforcementLevel": "soft", "draftingVsSubmission": "drafting"}, {"key": "s&t_for_empowerment", "text": "The initiative aims to foster inclusive growth by leveraging science and technology for community empowerment, livelihood enhancement, and sustainable development.", "appliesTo": ["all"], "rationale": "This defines the core strategic goal of the program: using S&T for socio-economic impact.", "ruleClass": "priority", "confidence": 1, "importance": "high", "sourceBlock": "priorities", "detectorHints": [], "draftingStage": ["beneficiaries"], "sourceAnchors": [{"url": null, "note": null, "quote": "This initiative aims to foster inclusive growth by leveraging science and technology for community empowerment, livelihood enhancement, and sustainable development.", "fieldKey": null, "confidence": null, "sourceType": "raw_text"}], "enforcementLevel": "soft", "draftingVsSubmission": "drafting"}, {"key": "address_livelihood_gaps", "text": "A primary objective is to address the weakest linkages in the predominant livelihood systems of the SC community through Science, Technology and Innovation (STI) interventions.", "appliesTo": ["objectives", "innovation"], "rationale": "Proposals should focus on identifying and solving specific, critical problems within existing livelihood structures.", "ruleClass": "priority", "confidence": 1, "importance": "high", "sourceBlock": "priorities", "detectorHints": [], "draftingStage": ["beneficiaries", "innovation"], "sourceAnchors": [{"url": null, "note": null, "quote": "(1) To address the weakest linkages in the predominant livelihood systems of the SC community through Science, Technology and Innovation (STI) interventions.", "fieldKey": null, "confidence": null, "sourceType": "raw_text"}], "enforcementLevel": "soft", "draftingVsSubmission": "drafting"}, {"key": "social_enterprise_creation", "text": "Proposals should aim to identify and create social enterprises based on the strengths in livelihood systems.", "appliesTo": ["objectives"], "rationale": "The funder prioritizes creating sustainable, community-owned business structures.", "ruleClass": "priority", "confidence": 1, "importance": "high", "sourceBlock": "priorities", "detectorHints": [], "draftingStage": ["thrust_alignment"], "sourceAnchors": [{"url": null, "note": null, "quote": "(2) To identify and create social enterprises based on the strengths in livelihood systems.", "fieldKey": null, "confidence": null, "sourceType": "raw_text"}], "enforcementLevel": "soft", "draftingVsSubmission": "drafting"}, {"key": "indigenous_knowledge_systems", "text": "A key objective is to harness, document, research, validate, and conserve Indigenous Knowledge Systems (IKS) and integrate them with S&T for sustainable development.", "appliesTo": ["objectives"], "rationale": "This highlights the value placed on local knowledge and its integration with modern technology, rather than replacement.", "ruleClass": "priority", "confidence": 1, "importance": "medium", "sourceBlock": "priorities", "detectorHints": [], "draftingStage": ["thrust_alignment"], "sourceAnchors": [{"url": null, "note": null, "quote": "(3) To harness, document, research, validate and conserve the Indigenous Knowledge Systems (IKS), skills and practices of different communities through inputs of Science and Technology to integrate IKS into appropriate technology, innovation and development for sustainable and economically viable development model of practices in livelihood systems.", "fieldKey": null, "confidence": null, "sourceType": "raw_text"}], "enforcementLevel": "soft", "draftingVsSubmission": "drafting"}], "budgetRules": [{"key": "no_international_travel", "text": "International travel is not permissible under the projects.", "appliesTo": ["workplan"], "rationale": "This is a strict prohibition on a specific type of cost.", "ruleClass": "budget", "confidence": 1, "importance": "high", "sourceBlock": "budgetRules", "detectorHints": ["budget_limit"], "draftingStage": ["budget_strategy"], "sourceAnchors": [{"url": null, "note": null, "quote": "International travel is not permissible under the projects.", "fieldKey": null, "confidence": null, "sourceType": "raw_text"}], "enforcementLevel": "hard", "draftingVsSubmission": "both"}, {"key": "staff_payment_norms", "text": "Staff recruited for a project should be paid as per the norms and guidelines of the DST.", "appliesTo": ["workplan"], "rationale": "Personnel costs must adhere to the funder's established pay scales.", "ruleClass": "budget", "confidence": 1, "importance": "high", "sourceBlock": "budgetRules", "detectorHints": ["budget_limit"], "draftingStage": ["budget_strategy"], "sourceAnchors": [{"url": null, "note": null, "quote": "Staff recruited for a project should be paid as per the norms and guidelines of the DST.", "fieldKey": null, "confidence": null, "sourceType": "raw_text"}], "enforcementLevel": "hard", "draftingVsSubmission": "both"}, {"key": "multi_institution_budget", "text": "For multi-institutional projects, the Principal Investigator must furnish a separate budget for each of the implementing institutions.", "appliesTo": ["workplan"], "rationale": "Financial accountability must be clearly delineated for each partner organization.", "ruleClass": "budget", "confidence": 1, "importance": "high", "sourceBlock": "budgetRules", "detectorHints": ["budget_limit"], "draftingStage": ["budget_strategy"], "sourceAnchors": [{"url": null, "note": null, "quote": "In case of multi-institutional project, the Principal Investigator (PI) must furnish formal agreement from the collaborating institutions/scientists along with separate budget for each of the implementing institutions.", "fieldKey": null, "confidence": null, "sourceType": "raw_text"}], "enforcementLevel": "hard", "draftingVsSubmission": "both"}, {"key": "construction_cost_limits", "text": "The budget under construction cost is only for low-cost structures like a Common Facility Centre (CFC) and/or renovation or refurbishing of existing space, not for construction of new buildings or structures.", "appliesTo": ["workplan"], "rationale": "This rule strictly limits capital expenditure on construction to prevent large-scale building projects.", "ruleClass": "budget", "confidence": 1, "importance": "high", "sourceBlock": "budgetRules", "detectorHints": ["budget_limit"], "draftingStage": ["budget_strategy"], "sourceAnchors": [{"url": null, "note": null, "quote": "The budget under construction cost is only for low-cost structures like Common Facility Centre (CFC) and/or renovation or refurbishing of existing space and not for construction of new buildings or structures.", "fieldKey": null, "confidence": null, "sourceType": "raw_text"}], "enforcementLevel": "hard", "draftingVsSubmission": "both"}, {"key": "equipment_quotations", "text": "If the project is approved, a minimum of 3 budgetary quotations will be required to support estimates for equipment.", "appliesTo": ["workplan"], "rationale": "This is a post-approval requirement but informs the need for realistic and justifiable equipment costs in the proposal.", "ruleClass": "budget", "confidence": 1, "importance": "medium", "sourceBlock": "budgetRules", "detectorHints": ["budget_limit"], "draftingStage": ["budget_strategy"], "sourceAnchors": [{"url": null, "note": null, "quote": "Budgetary quotations (min. 3 no.) will be required in support of estimates for equipment, if project is approved for financial support.", "fieldKey": null, "confidence": null, "sourceType": "raw_text"}], "enforcementLevel": "hard", "draftingVsSubmission": "both"}, {"key": "review_meeting_budget", "text": "A tentative budget should be proposed for two DST field visits/annual review meetings per year.", "appliesTo": ["workplan"], "rationale": "Applicants must proactively budget for funder-mandated oversight activities.", "ruleClass": "budget", "confidence": 1, "importance": "medium", "sourceBlock": "budgetRules", "detectorHints": ["budget_limit", "duration_limit"], "draftingStage": ["budget_strategy"], "sourceAnchors": [{"url": null, "note": null, "quote": "DST's Field visits/annual review meetings etc. (Tentative budget to be proposed for two meetings per year and should cover the travel cost, accommodation and local field visits of 4-6 experts)", "fieldKey": null, "confidence": null, "sourceType": "raw_text"}], "enforcementLevel": "hard", "draftingVsSubmission": "both"}], "formatRules": [{"key": "project_summary_limit", "text": "The Project Summary must be 250 words only.", "appliesTo": ["summary"], "rationale": "A strict word limit for a key proposal section.", "ruleClass": "format", "confidence": 1, "importance": "high", "sourceBlock": "formatRules", "detectorHints": ["word_limit", "character_limit", "format_rule"], "draftingStage": ["final_pitch"], "sourceAnchors": [{"url": null, "note": null, "quote": "Project Summary (in 250 words only...)", "fieldKey": null, "confidence": null, "sourceType": "raw_text"}], "enforcementLevel": "hard", "draftingVsSubmission": "both"}, {"key": "project_title_content", "text": "The Project Title should include the problem, proposed solution/technology, target community/beneficiaries, and the name of implementing Districts and State.", "appliesTo": ["problem_need", "objectives"], "rationale": "Specifies the required components of the project title for clarity and searchability.", "ruleClass": "format", "confidence": 1, "importance": "medium", "sourceBlock": "formatRules", "detectorHints": ["word_limit", "character_limit", "format_rule"], "draftingStage": ["problem_definition", "beneficiaries"], "sourceAnchors": [{"url": null, "note": null, "quote": "Project Title (should include problem, proposed solution/technology, target community/beneficiaries and name of implementing Districts and State for establishment of STI hub/ WTP/SUNIL etc.)", "fieldKey": null, "confidence": null, "sourceType": "raw_text"}], "enforcementLevel": "hard", "draftingVsSubmission": "both"}, {"key": "objectives_limit", "text": "The proposal should contain only 4-5 objectives.", "appliesTo": ["all"], "rationale": "A numerical limit on the number of project objectives to ensure focus.", "ruleClass": "format", "confidence": 1, "importance": "medium", "sourceBlock": "formatRules", "detectorHints": ["word_limit", "character_limit", "format_rule"], "draftingStage": [], "sourceAnchors": [{"url": null, "note": null, "quote": "Proposed Objectives (aligned with title of project and 4-5 only)", "fieldKey": null, "confidence": null, "sourceType": "raw_text"}], "enforcementLevel": "hard", "draftingVsSubmission": "both"}, {"key": "problem_statement_limit", "text": "The problem statement section is limited to 200 words only.", "appliesTo": ["problem_need"], "rationale": "Strict word limit for the problem description.", "ruleClass": "format", "confidence": 1, "importance": "medium", "sourceBlock": "formatRules", "detectorHints": ["word_limit", "character_limit", "format_rule"], "draftingStage": ["problem_definition"], "sourceAnchors": [{"url": null, "note": null, "quote": "State the target population related problem you seek to address and brief of their Socio-Economic status, in 200 words only", "fieldKey": null, "confidence": null, "sourceType": "raw_text"}], "enforcementLevel": "hard", "draftingVsSubmission": "both"}, {"key": "pi_work_summary_limit", "text": "Summary of work accomplished by the PI/Lead Institute in the proposed area during the last 5 years is limited to 100 words.", "appliesTo": ["summary"], "rationale": "Strict word limit for demonstrating prior experience.", "ruleClass": "format", "confidence": 1, "importance": "medium", "sourceBlock": "formatRules", "detectorHints": ["word_limit", "character_limit", "format_rule", "duration_limit"], "draftingStage": ["final_pitch"], "sourceAnchors": [{"url": null, "note": null, "quote": "Summary of work accomplished by PI/ Lead Institute in the proposed area during last 5 years (100 words):", "fieldKey": null, "confidence": null, "sourceType": "raw_text"}], "enforcementLevel": "hard", "draftingVsSubmission": "both"}, {"key": "various_word_limits", "text": "Multiple sections have strict word limits: Industrial Scenario (100 words), Existing solutions (200 words), Government Initiatives (100 words), Community participation (100 words), Equipment plan (50 words), Dissemination plan (50 words), Sustainability plan (100 words), Relevance to SMEs (50 words), Replication plan (50 words), and PI Experience (50 words).", "appliesTo": ["alignment", "sustainability"], "rationale": "This summarizes numerous specific word count constraints throughout the application form that must be adhered to.", "ruleClass": "format", "confidence": 1, "importance": "medium", "sourceBlock": "formatRules", "detectorHints": ["word_limit", "character_limit", "format_rule", "budget_limit"], "draftingStage": ["beneficiaries", "fit_and_scope", "budget_strategy", "sustainability_and_scale"], "sourceAnchors": [{"url": null, "note": null, "quote": "Brief Industrial Scenario of the target area, in 100 words only... Existing regional/ National/ International solutions for the proposed problem, (in 200 words only)... Any other Government National Initiatives related to proposed activities to solve this problem (mention outcomes of the initiatives, in 100 words only)... Details/Mechanism for ensuring the involvement and participation of target population in the project area, (in 100 words only)... Plan of the institution about the usage, maintenance and retention of capital equipment to be procured under project (in 50 words only)... PUBLICITY, PROMOTION & DISSEMINATION PLAN... (in 50 words only)... Self-sustainability/revenue generation plan of the project work, in 100 words only... Relevance of the proposed interventions to the existing Micro & Small Enterprises... (in 50 words only)... Possibility of replication of project in similar areas... (in 50 words only)... Field of Experience relevant to current proposal area (in 50 words only)", "fieldKey": null, "confidence": null, "sourceType": "raw_text"}], "enforcementLevel": "hard", "draftingVsSubmission": "both"}, {"key": "publications_limit", "text": "Applicants can list a maximum of 10 significant publications and a maximum of 10 publications from the last five years related to the proposed area.", "appliesTo": ["all"], "rationale": "A numerical limit on the number of publications to be listed.", "ruleClass": "format", "confidence": 1, "importance": "low", "sourceBlock": "formatRules", "detectorHints": ["word_limit", "character_limit", "format_rule", "duration_limit"], "draftingStage": [], "sourceAnchors": [{"url": null, "note": null, "quote": "Significant publications (Maximum 10) ... List of proposed area related publications from last five years (Maximum 10)", "fieldKey": null, "confidence": null, "sourceType": "raw_text"}], "enforcementLevel": "hard", "draftingVsSubmission": "both"}], "mustAddress": [{"key": "pra_swot_analysis", "text": "Investigators must clearly specify the relevance of objectives based strictly on PRA (Participatory Rural Appraisal) and SWOT analysis conducted in the targeted project area.", "appliesTo": ["alignment"], "rationale": "This requires that project objectives are evidence-based and grounded in a thorough analysis of the local context.", "ruleClass": "must_address", "confidence": 1, "importance": "high", "sourceBlock": "mustAddress", "detectorHints": [], "draftingStage": ["fit_and_scope"], "sourceAnchors": [{"url": null, "note": null, "quote": "The investigators may clearly specify the relevance of objectives strictly based on PRA and SWOT analysis done in the targeted project area.", "fieldKey": null, "confidence": null, "sourceType": "raw_text"}], "enforcementLevel": "hard", "draftingVsSubmission": "drafting"}, {"key": "quantify_socioeconomic_enhancement", "text": "The proposal must clearly indicate the quantum increase in socioeconomic enhancement for stakeholders resulting from the technological interventions.", "appliesTo": ["all"], "rationale": "Reviewers expect specific, measurable projections of the project's impact on the community's economic status.", "ruleClass": "must_address", "confidence": 1, "importance": "high", "sourceBlock": "mustAddress", "detectorHints": [], "draftingStage": [], "sourceAnchors": [{"url": null, "note": null, "quote": "The investigators may clearly indicate the quantum increase in socioeconomic enhancement of stake holders after intervention of the location specific technologies.", "fieldKey": null, "confidence": null, "sourceType": "raw_text"}], "enforcementLevel": "hard", "draftingVsSubmission": "drafting"}, {"key": "justify_hub_establishment", "text": "The proposal must clearly establish the significance of establishing the STI Hub and its impact on the targeted areas.", "appliesTo": ["impact_outcomes"], "rationale": "The proposal needs a strong justification for why a Hub is the right solution for the identified problems.", "ruleClass": "must_address", "confidence": 1, "importance": "medium", "sourceBlock": "mustAddress", "detectorHints": [], "draftingStage": ["outcomes"], "sourceAnchors": [{"url": null, "note": null, "quote": "The investigators may clearly establish the significance of establishment of STI Hub and its impact on the targeted areas.", "fieldKey": null, "confidence": null, "sourceType": "raw_text"}], "enforcementLevel": "hard", "draftingVsSubmission": "drafting"}, {"key": "define_partner_roles", "text": "The proposal must clearly define the significant role of partner Institutions in the project.", "appliesTo": ["all"], "rationale": "Partnerships should be meaningful and well-defined, not just nominal.", "ruleClass": "must_address", "confidence": 1, "importance": "medium", "sourceBlock": "mustAddress", "detectorHints": [], "draftingStage": ["team_and_partnerships"], "sourceAnchors": [{"url": null, "note": null, "quote": "The investigators may clearly define the significant role of partner Institutions in the project.", "fieldKey": null, "confidence": null, "sourceType": "raw_text"}], "enforcementLevel": "hard", "draftingVsSubmission": "drafting"}, {"key": "justify_technology_choice", "text": "Investigators must justify how the proposed technologies are essentially required for the livelihood enhancement of the SC community.", "appliesTo": ["all"], "rationale": "There must be a clear, direct link between the chosen technology and the specific livelihood needs of the community.", "ruleClass": "must_address", "confidence": 1, "importance": "high", "sourceBlock": "mustAddress", "detectorHints": [], "draftingStage": ["beneficiaries"], "sourceAnchors": [{"url": null, "note": null, "quote": "The investigators may justify how the technologies to be intervened in the targeted areas is essentially required for livelihood enhancement of the SC community.", "fieldKey": null, "confidence": null, "sourceType": "raw_text"}], "enforcementLevel": "hard", "draftingVsSubmission": "drafting"}, {"key": "academic_ngo_collaboration", "text": "Academic institutions must engage with local NGOs for sustainable rural livelihoods planning and knowledge dissemination.", "appliesTo": ["all"], "rationale": "This collaboration is mandatory for academic applicants to ensure field-level implementation and community reach.", "ruleClass": "must_address", "confidence": 1, "importance": "high", "sourceBlock": "mustAddress", "detectorHints": [], "draftingStage": [], "sourceAnchors": [{"url": null, "note": null, "quote": "Academic institutions must engage with local NGOs for sustainable rural livelihoods planning, and dissemination of the knowledge and technological know-how gained through the project to the target populations;", "fieldKey": null, "confidence": null, "sourceType": "raw_text"}], "enforcementLevel": "hard", "draftingVsSubmission": "drafting"}, {"key": "ngo_s&t_collaboration", "text": "Voluntary organizations should partner with S&T institutions and R&D labs to develop location-specific, need-based technologies.", "appliesTo": ["problem_need"], "rationale": "This collaboration is a strong expectation for NGO applicants to ensure technological rigor.", "ruleClass": "must_address", "confidence": 1, "importance": "high", "sourceBlock": "mustAddress", "detectorHints": [], "draftingStage": ["problem_definition", "team_and_partnerships"], "sourceAnchors": [{"url": null, "note": null, "quote": "voluntary organizations should partner with S&T institutions and R&D labs to develop location-specific, need-based technologies.", "fieldKey": null, "confidence": null, "sourceType": "raw_text"}], "enforcementLevel": "soft", "draftingVsSubmission": "drafting"}, {"key": "location_criteria", "text": "STI Hubs should be established in areas with a predominant SC population.", "appliesTo": ["all"], "rationale": "The project's geographical location must align with the target demographic.", "ruleClass": "must_address", "confidence": 1, "importance": "high", "sourceBlock": "mustAddress", "detectorHints": [], "draftingStage": ["beneficiaries"], "sourceAnchors": [{"url": null, "note": null, "quote": "STI Hubs should be established in areas with a predominant SC population.", "fieldKey": null, "confidence": null, "sourceType": "raw_text"}], "enforcementLevel": "soft", "draftingVsSubmission": "drafting"}, {"key": "beneficiary_percentage", "text": "At least 60–70% of beneficiaries must belong to SC communities.", "appliesTo": ["all"], "rationale": "This is a strict, quantitative requirement for beneficiary composition.", "ruleClass": "must_address", "confidence": 1, "importance": "high", "sourceBlock": "mustAddress", "detectorHints": [], "draftingStage": [], "sourceAnchors": [{"url": null, "note": null, "quote": "At least 60–70% of beneficiaries must belong to SC communities.", "fieldKey": null, "confidence": null, "sourceType": "raw_text"}], "enforcementLevel": "hard", "draftingVsSubmission": "drafting"}, {"key": "intervention_limit", "text": "Each Hub should focus on not more than 4–5 interventions.", "appliesTo": ["all"], "rationale": "This rule promotes depth and focus over breadth, preventing projects from becoming too diffuse.", "ruleClass": "must_address", "confidence": 1, "importance": "medium", "sourceBlock": "mustAddress", "detectorHints": [], "draftingStage": [], "sourceAnchors": [{"url": null, "note": null, "quote": "Each Hub should focus on not more than 4–5 interventions.", "fieldKey": null, "confidence": null, "sourceType": "raw_text"}], "enforcementLevel": "soft", "draftingVsSubmission": "drafting"}, {"key": "sustainability_pathway", "text": "The project must show and enable the community the pathway to achieve sustainability after the project period is over.", "appliesTo": ["all"], "rationale": "A clear, credible plan for long-term viability beyond the grant period is a mandatory proposal component.", "ruleClass": "must_address", "confidence": 1, "importance": "high", "sourceBlock": "mustAddress", "detectorHints": [], "draftingStage": ["beneficiaries"], "sourceAnchors": [{"url": null, "note": null, "quote": "The project must show and enable the community the pathway to achieve sustainability after the project period is over.", "fieldKey": null, "confidence": null, "sourceType": "raw_text"}], "enforcementLevel": "hard", "draftingVsSubmission": "drafting"}, {"key": "sdg_alignment", "text": "The project must meet or promote connected SDG objectives.", "appliesTo": ["all"], "rationale": "Proposals need to explicitly connect their activities and outcomes to the Sustainable Development Goals.", "ruleClass": "must_address", "confidence": 1, "importance": "medium", "sourceBlock": "mustAddress", "detectorHints": [], "draftingStage": [], "sourceAnchors": [{"url": null, "note": null, "quote": "Must meet or promote connected SDG objectives.", "fieldKey": null, "confidence": null, "sourceType": "raw_text"}], "enforcementLevel": "hard", "draftingVsSubmission": "drafting"}, {"key": "long_term_sustainability_system", "text": "The project must create a robust system for long-term sustainability, and the key points and process of this system must be clearly enumerated in the proposal.", "appliesTo": ["all"], "rationale": "This is a core objective requiring a detailed plan for how the project's impact will continue after funding ends.", "ruleClass": "must_address", "confidence": 1, "importance": "high", "sourceBlock": "mustAddress", "detectorHints": [], "draftingStage": [], "sourceAnchors": [{"url": null, "note": null, "quote": "To create a robust system in place for long term sustainability of the project undertaken, key points of sustainability and process must be clearly enumerated.", "fieldKey": null, "confidence": null, "sourceType": "raw_text"}], "enforcementLevel": "hard", "draftingVsSubmission": "drafting"}], "durationRules": [{"key": "project_duration", "text": "The project duration is 3 years.", "appliesTo": ["workplan"], "rationale": "This is a fixed duration for all projects funded under this call.", "ruleClass": "duration", "confidence": 1, "importance": "high", "sourceBlock": "durationRules", "detectorHints": ["duration_limit"], "draftingStage": ["workplan"], "sourceAnchors": [{"url": null, "note": null, "quote": "Project Duration: 3 years", "fieldKey": null, "confidence": null, "sourceType": "raw_text"}], "enforcementLevel": "hard", "draftingVsSubmission": "both"}], "sourceAnchors": [], "reviewerSignals": [{"key": "collaborative_model", "text": "A strong proposal will follow a collaborative, networked, and partnership model to address last-mile challenges in technology delivery and management.", "appliesTo": ["all"], "rationale": "The funder explicitly values proposals that demonstrate a robust partnership approach.", "ruleClass": "reviewer_signal", "confidence": 0.95, "importance": "high", "sourceBlock": "reviewerSignals", "detectorHints": [], "draftingStage": ["thrust_alignment"], "sourceAnchors": [{"url": null, "note": null, "quote": "Framework: Setting up of STI Hubs to follow collaborative, networked, and partnership models to address last-mile challenges in technology induction, delivery, management, utilization, and extension.", "fieldKey": null, "confidence": null, "sourceType": "raw_text"}], "enforcementLevel": "soft", "draftingVsSubmission": "drafting"}, {"key": "collaborative_proposal_encouraged", "text": "A collaborative proposal from two or three different types of institutes will be encouraged.", "appliesTo": ["all"], "rationale": "The application form explicitly signals that proposals involving multiple types of institutions (e.g., academic, NGO) are viewed favorably.", "ruleClass": "reviewer_signal", "confidence": 1, "importance": "medium", "sourceBlock": "reviewerSignals", "detectorHints": [], "draftingStage": ["thrust_alignment"], "sourceAnchors": [{"url": null, "note": null, "quote": "Type of the Lead Institute (collaborative proposal from two/three different types of Institutes will be encouraged)", "fieldKey": null, "confidence": null, "sourceType": "raw_text"}], "enforcementLevel": "soft", "draftingVsSubmission": "drafting"}, {"key": "strong_linkages", "text": "Proposals demonstrating backward connections with higher educational and scientific institutions (e.g., Agricultural Universities, IITs, NITs) to access frontier technologies will be viewed favorably.", "appliesTo": ["all"], "rationale": "This indicates that leveraging high-level scientific expertise is a mark of a strong project.", "ruleClass": "reviewer_signal", "confidence": 0.95, "importance": "medium", "sourceBlock": "reviewerSignals", "detectorHints": [], "draftingStage": ["thrust_alignment"], "sourceAnchors": [{"url": null, "note": null, "quote": "Linkages: Backward connections with higher educational and scientific institutions (Agricultural Universities, IITs, NITs, KVKs, central departments etc.) will enable access to frontier technologies.", "fieldKey": null, "confidence": null, "sourceType": "raw_text"}], "enforcementLevel": "soft", "draftingVsSubmission": "drafting"}, {"key": "deep_community_engagement", "text": "A strong proposal will involve community organizations like Self-Help Groups (SHGs), Farmer Producer Organisations (FPOs), and Farmer Producer Companies (FPCs) to ensure community adoption.", "appliesTo": ["impact_outcomes"], "rationale": "Demonstrating genuine, structured community involvement is a positive signal.", "ruleClass": "reviewer_signal", "confidence": 0.95, "importance": "medium", "sourceBlock": "reviewerSignals", "detectorHints": [], "draftingStage": ["beneficiaries", "outcomes"], "sourceAnchors": [{"url": null, "note": null, "quote": "Community Engagement: SHGs, FPOs, and FPCs should be involved to ensure reaching the community for the adaptation of the new and improved systematic approach developed and recommended for a sustainable future.", "fieldKey": null, "confidence": null, "sourceType": "raw_text"}], "enforcementLevel": "soft", "draftingVsSubmission": "drafting"}, {"key": "novel_technologies", "text": "Proposals that develop and deliver novel or innovative technologies are likely to be viewed more favorably than those using standard ones.", "appliesTo": ["innovation"], "rationale": "The exclusion of routine technologies implies a preference for innovation.", "ruleClass": "reviewer_signal", "confidence": 0.9, "importance": "high", "sourceBlock": "reviewerSignals", "detectorHints": [], "draftingStage": ["innovation"], "sourceAnchors": [{"url": null, "note": null, "quote": "Focus Areas Ο ...Develops and delivers novel/innovative technologies.", "fieldKey": null, "confidence": null, "sourceType": "raw_text"}], "enforcementLevel": "soft", "draftingVsSubmission": "drafting"}], "submissionRules": [{"key": "online_submission_only", "text": "The project proposal must be submitted online only through DST's Electronic Project Management System (e-PMS) at www.onlinedst.gov.in.", "appliesTo": ["all"], "rationale": "This is the only accepted method for proposal submission.", "ruleClass": "submission", "confidence": 1, "importance": "high", "sourceBlock": "submissionRules", "detectorHints": ["submission_checklist"], "draftingStage": [], "sourceAnchors": [{"url": null, "note": null, "quote": "The Principal Investigator should submit the project proposal online only through DST's Electronic Project Management System (e-PMS) on portal www.onlinedst.gov.in the given format along with necessary documents.", "fieldKey": null, "confidence": null, "sourceType": "raw_text"}], "enforcementLevel": "hard", "draftingVsSubmission": "submission"}, {"key": "no_alternate_submission", "text": "Proposals submitted by any other means will be summarily rejected.", "appliesTo": ["all"], "rationale": "Reinforces the mandatory nature of the online portal submission.", "ruleClass": "submission", "confidence": 1, "importance": "high", "sourceBlock": "submissionRules", "detectorHints": ["submission_checklist"], "draftingStage": [], "sourceAnchors": [{"url": null, "note": null, "quote": "Proposal submitted by any other means will be summarily rejected.", "fieldKey": null, "confidence": null, "sourceType": "raw_text"}], "enforcementLevel": "hard", "draftingVsSubmission": "submission"}, {"key": "submission_deadline", "text": "The Last Date for Submission of Online Proposals is 16/05/2026.", "appliesTo": ["all"], "rationale": "This is the final, non-negotiable deadline for proposal submission.", "ruleClass": "submission", "confidence": 1, "importance": "high", "sourceBlock": "submissionRules", "detectorHints": ["submission_checklist"], "draftingStage": [], "sourceAnchors": [{"url": null, "note": null, "quote": "The Last Date for Submission of Online Proposals is 16/05/2026 after which the web-link will be automatically disabled for any usage.", "fieldKey": null, "confidence": null, "sourceType": "raw_text"}], "enforcementLevel": "hard", "draftingVsSubmission": "submission"}, {"key": "annexure_submission", "text": "The enclosed annexures (Annexure I – Annexure V) must also be signed and submitted.", "appliesTo": ["all"], "rationale": "A procedural requirement for submitting signed supporting documents.", "ruleClass": "submission", "confidence": 1, "importance": "high", "sourceBlock": "submissionRules", "detectorHints": ["submission_checklist"], "draftingStage": [], "sourceAnchors": [{"url": null, "note": null, "quote": "The enclosed annexures (Annexure I – Annexure V) should also be signed and submitted.", "fieldKey": null, "confidence": null, "sourceType": "raw_text"}], "enforcementLevel": "hard", "draftingVsSubmission": "submission"}, {"key": "multi_institution_agreement", "text": "For multi-institutional projects, the PI must furnish a formal agreement from the collaborating institutions/scientists.", "appliesTo": ["all"], "rationale": "A formal agreement is a required submission document for collaborative proposals.", "ruleClass": "submission", "confidence": 1, "importance": "high", "sourceBlock": "submissionRules", "detectorHints": ["submission_checklist"], "draftingStage": [], "sourceAnchors": [{"url": null, "note": null, "quote": "In case of multi-institutional project, the Principal Investigator (PI) must furnish formal agreement from the collaborating institutions/scientists...", "fieldKey": null, "confidence": null, "sourceType": "raw_text"}], "enforcementLevel": "hard", "draftingVsSubmission": "submission"}], "deliverableRules": [{"key": "socioeconomic_empowerment", "text": "A key outcome is the socioeconomic empowerment of SC communities through improved livelihood systems, creation of new options, and equitable growth.", "appliesTo": ["impact_outcomes"], "rationale": "This defines the ultimate impact and deliverable of the project.", "ruleClass": "deliverable", "confidence": 1, "importance": "high", "sourceBlock": "deliverableRules", "detectorHints": [], "draftingStage": ["outcomes"], "sourceAnchors": [{"url": null, "note": null, "quote": "Outcomes: STI Hubs to facilitate socioeconomic empowerment of SC communities through improvement of the existing livelihood systems, besides creation of newer and viable options, equitable growth, productivity enhancement, social enterprise development, and equity with inclusion.", "fieldKey": null, "confidence": null, "sourceType": "raw_text"}], "enforcementLevel": "soft", "draftingVsSubmission": "drafting"}, {"key": "ngo_capacity_building", "text": "Projects must build NGO capacity, expand institutional outreach, and promote sustainable knowledge for community development.", "appliesTo": ["workplan"], "rationale": "Deliverables include strengthening the local ecosystem, not just direct intervention.", "ruleClass": "deliverable", "confidence": 1, "importance": "medium", "sourceBlock": "deliverableRules", "detectorHints": [], "draftingStage": ["beneficiaries", "team_and_partnerships"], "sourceAnchors": [{"url": null, "note": null, "quote": "By strengthening delivery mechanisms and applying S&T interventions, it must build NGO capacity, expand institutional outreach, and promote sustainable knowledge for community development.", "fieldKey": null, "confidence": null, "sourceType": "raw_text"}], "enforcementLevel": "hard", "draftingVsSubmission": "drafting"}, {"key": "quantitative_outputs", "text": "The work plan should define expected deliverables in terms of anticipated quantitative output, outcome, and socio-economic impact on target beneficiaries.", "appliesTo": ["objectives", "workplan", "impact_outcomes"], "rationale": "Reviewers expect specific, measurable deliverables to be listed in the proposal.", "ruleClass": "deliverable", "confidence": 1, "importance": "high", "sourceBlock": "deliverableRules", "detectorHints": [], "draftingStage": ["workplan", "outcomes"], "sourceAnchors": [{"url": null, "note": null, "quote": "Expected deliverables (anticipated quantitative output, outcome & socio-economic impact on target beneficiaries)", "fieldKey": null, "confidence": null, "sourceType": "raw_text"}], "enforcementLevel": "soft", "draftingVsSubmission": "drafting"}, {"key": "ipr_generation", "text": "Expected outputs include Intellectual Property Rights (IPR) such as Geographical Indication (GI) tags, copyrights, patents, and trademarks.", "appliesTo": ["workplan"], "rationale": "The funder encourages the formalization of intellectual property as a project deliverable.", "ruleClass": "deliverable", "confidence": 1, "importance": "low", "sourceBlock": "deliverableRules", "detectorHints": [], "draftingStage": ["workplan"], "sourceAnchors": [{"url": null, "note": null, "quote": "IPR on technology projects process design | • Geographical Indication (GI) tags | (details of applied/ granted) | • Copyright • Trademarks/ Trade secrets • Patents", "fieldKey": null, "confidence": null, "sourceType": "raw_text"}], "enforcementLevel": "info", "draftingVsSubmission": "drafting"}, {"key": "contribution_to_sdgs", "text": "A required deliverable is the project's contribution towards Sustainable Development Goals (SDGs) and National Missions (NMs), which must be explicitly mapped.", "appliesTo": ["workplan"], "rationale": "Projects must demonstrate alignment with and contribution to broader national and international development goals.", "ruleClass": "budget", "confidence": 1, "importance": "medium", "sourceBlock": "deliverableRules", "detectorHints": ["budget_limit", "deliverable_presence"], "draftingStage": ["workplan"], "sourceAnchors": [{"url": null, "note": null, "quote": "Contribution towards Sustainable Development Goals (SDGs) and National Missions (NMs)- provide name of indicator of project mapped with SDGs and NMs", "fieldKey": null, "confidence": null, "sourceType": "raw_text"}], "enforcementLevel": "hard", "draftingVsSubmission": "drafting"}], "evaluationCriteria": [{"key": "resource_utilization", "text": "Interventions will be evaluated on whether they utilize available local resources and build on community skills.", "appliesTo": ["all"], "rationale": "Projects should be contextually appropriate, leveraging existing assets and knowledge.", "ruleClass": "evaluation", "confidence": 1, "importance": "medium", "sourceBlock": "evaluationCriteria", "detectorHints": [], "draftingStage": ["beneficiaries"], "sourceAnchors": [{"url": null, "note": null, "quote": "Ensure interventions suggested utilize available resources and build on community skills.", "fieldKey": null, "confidence": null, "sourceType": "raw_text"}], "enforcementLevel": "soft", "draftingVsSubmission": "drafting"}, {"key": "drudgery_reduction", "text": "Technologies will be assessed on their ability to ease manual effort and improve working conditions.", "appliesTo": ["all"], "rationale": "Improving the quality of life and work for beneficiaries is a key evaluation criterion.", "ruleClass": "evaluation", "confidence": 1, "importance": "medium", "sourceBlock": "evaluationCriteria", "detectorHints": [], "draftingStage": ["evaluation"], "sourceAnchors": [{"url": null, "note": null, "quote": "Introduce technologies that ease manual effort and improve working conditions.", "fieldKey": null, "confidence": null, "sourceType": "raw_text"}], "enforcementLevel": "soft", "draftingVsSubmission": "drafting"}, {"key": "efficiency_enhancement", "text": "The project will be judged on its capacity to strengthen productivity and streamline livelihood processes.", "appliesTo": ["all"], "rationale": "Demonstrating clear gains in efficiency is a measure of a successful intervention.", "ruleClass": "evaluation", "confidence": 1, "importance": "medium", "sourceBlock": "evaluationCriteria", "detectorHints": [], "draftingStage": ["team_and_partnerships"], "sourceAnchors": [{"url": null, "note": null, "quote": "Strengthen productivity and streamline livelihood processes.", "fieldKey": null, "confidence": null, "sourceType": "raw_text"}], "enforcementLevel": "soft", "draftingVsSubmission": "drafting"}, {"key": "market_integration", "text": "A criterion for selection is whether the project enables communities to move up the value chain and access higher market opportunities.", "appliesTo": ["all"], "rationale": "Projects should connect beneficiaries to larger economic systems, not just improve subsistence.", "ruleClass": "evaluation", "confidence": 1, "importance": "high", "sourceBlock": "evaluationCriteria", "detectorHints": [], "draftingStage": ["evaluation"], "sourceAnchors": [{"url": null, "note": null, "quote": "Enable communities to move up the value chain and access higher market opportunities.", "fieldKey": null, "confidence": null, "sourceType": "raw_text"}], "enforcementLevel": "soft", "draftingVsSubmission": "drafting"}, {"key": "adaptability_affordability", "text": "Interventions are evaluated on being cost-effective, scalable, and culturally adaptable.", "appliesTo": ["all"], "rationale": "Proposed solutions must be practical and sustainable for the target community to adopt and maintain.", "ruleClass": "budget", "confidence": 1, "importance": "high", "sourceBlock": "evaluationCriteria", "detectorHints": ["budget_limit"], "draftingStage": ["budget_strategy"], "sourceAnchors": [{"url": null, "note": null, "quote": "Ensure interventions are cost-effective, scalable, and culturally adaptable.", "fieldKey": null, "confidence": null, "sourceType": "raw_text"}], "enforcementLevel": "soft", "draftingVsSubmission": "drafting"}, {"key": "sustainability_linkages", "text": "The proposal will be evaluated on the strength of its linkages to knowledge institutes, field-level organizations, and national/state-level programmes to ensure sustainability.", "appliesTo": ["all"], "rationale": "Strong partnerships are seen as crucial for long-term success and technological relevance.", "ruleClass": "evaluation", "confidence": 1, "importance": "high", "sourceBlock": "evaluationCriteria", "detectorHints": [], "draftingStage": ["evaluation"], "sourceAnchors": [{"url": null, "note": null, "quote": "Links to knowledge institute(s) to ensure technology updates and capacity enhancement Ο Links to field level organization to ensure last mile connectivity Ο Links interventions to national/state-level programmes.", "fieldKey": null, "confidence": null, "sourceType": "raw_text"}], "enforcementLevel": "soft", "draftingVsSubmission": "drafting"}, {"key": "environmental_safeguards", "text": "The project's design will be assessed on whether it avoids environmental degradation, reduces carbon footprint, and is sensitive to ecological balance.", "appliesTo": ["all"], "rationale": "Environmental sustainability is a key consideration for all proposed interventions.", "ruleClass": "evaluation", "confidence": 1, "importance": "medium", "sourceBlock": "evaluationCriteria", "detectorHints": [], "draftingStage": ["evaluation"], "sourceAnchors": [{"url": null, "note": null, "quote": "Project avoids environmental degradation and reduces carbon footprint. Ο Project is sensitive to any alterations in ecological balance.", "fieldKey": null, "confidence": null, "sourceType": "raw_text"}], "enforcementLevel": "soft", "draftingVsSubmission": "drafting"}, {"key": "employment_orientation", "text": "Projects will be evaluated on their ability to generate self-employment opportunities and create additional revenue streams.", "appliesTo": ["all"], "rationale": "The ultimate goal is economic self-reliance, which is measured by job and income creation.", "ruleClass": "evaluation", "confidence": 1, "importance": "high", "sourceBlock": "evaluationCriteria", "detectorHints": [], "draftingStage": ["evaluation"], "sourceAnchors": [{"url": null, "note": null, "quote": "Generates self-employment opportunities. Ο Creates additional revenue streams.", "fieldKey": null, "confidence": null, "sourceType": "raw_text"}], "enforcementLevel": "soft", "draftingVsSubmission": "drafting"}, {"key": "simplicity_of_skills", "text": "The skills needed by beneficiaries for the project must be simple and easy to grasp.", "appliesTo": ["all"], "rationale": "This ensures a low barrier to entry for community members and increases the likelihood of successful adoption.", "ruleClass": "evaluation", "confidence": 1, "importance": "medium", "sourceBlock": "evaluationCriteria", "detectorHints": [], "draftingStage": ["evaluation"], "sourceAnchors": [{"url": null, "note": null, "quote": "Skills needed and associated for the beneficiaries of the project must be simple and easy to grasp.", "fieldKey": null, "confidence": null, "sourceType": "raw_text"}], "enforcementLevel": "hard", "draftingVsSubmission": "drafting"}, {"key": "capacity_building", "text": "The project will be assessed on its ability to build S&T absorption capacity and improve knowledge and innovation capabilities among beneficiaries.", "appliesTo": ["innovation"], "rationale": "Beyond direct economic benefits, the project should leave the community with enhanced skills and knowledge.", "ruleClass": "evaluation", "confidence": 1, "importance": "medium", "sourceBlock": "evaluationCriteria", "detectorHints": [], "draftingStage": ["team_and_partnerships", "innovation"], "sourceAnchors": [{"url": null, "note": null, "quote": "Builds S&T absorption capacity. Ο Improves knowledge and innovation capabilities among beneficiaries.", "fieldKey": null, "confidence": null, "sourceType": "raw_text"}], "enforcementLevel": "soft", "draftingVsSubmission": "drafting"}]}	null	\N	\N	2026-04-24 11:07:49.604	2026-04-24 11:09:42.62
cmojqa9k10009c2ddr7ihrzrl	cmojqa9hw0001c2dd41j7g3t6	cmojqa9jm0005c2ddtcxy8dbn	needs_review	gemini-2.5-pro	funding-guideline-v2	{"avoid": [{"key": "external_evaluation", "text": "Do not propose evaluations of educational interventions if you were not involved in their development or implementation.", "rationale": null, "confidence": 0.98, "importance": "high", "sourceAnchors": [{"url": null, "note": null, "quote": "Evaluation of educational intervention by scholars who are not involved in the development or implementation of those interventions will not be encouraged.", "fieldKey": null, "confidence": null, "sourceType": "raw_text"}]}, {"key": "no_honorarium_salary", "text": "Do not budget for honorarium or salary for academic and project staff, other than the specified Junior Project Fellow (JPF) role.", "rationale": null, "confidence": 0.98, "importance": "high", "sourceAnchors": [{"url": null, "note": null, "quote": "The ERIC funding does not provide any honorarium or salary for academic and project staff except for Junior Project Fellow (JPF)", "fieldKey": null, "confidence": null, "sourceType": "raw_text"}]}, {"key": "no_furniture_durable_assets", "text": "Do not include the purchase of furniture and durable assets in the project budget.", "rationale": null, "confidence": 0.98, "importance": "high", "sourceAnchors": [{"url": null, "note": null, "quote": "Furniture and durable assets are not allowed to be included in the project budget.", "fieldKey": null, "confidence": null, "sourceType": "raw_text"}]}, {"key": "no_hardware_assets", "text": "The purchase of hardware and durable assets such as almirahs, furniture, and computers is not admissible in the budget.", "rationale": null, "confidence": 0.98, "importance": "high", "sourceAnchors": [{"url": null, "note": null, "quote": "Purchase of hardwares and durable assets such as almirah, furniture, computer, etc. is not admissible.", "fieldKey": null, "confidence": null, "sourceType": "raw_text"}]}, {"key": "no_pre_commencement_expenditure", "text": "The project budget will not support any expenditure incurred before the commencement of the project.", "rationale": null, "confidence": 0.98, "importance": "high", "sourceAnchors": [{"url": null, "note": null, "quote": "The project budget will not support any expenditure incurred before the commencement of the project.", "fieldKey": null, "confidence": null, "sourceType": "raw_text"}]}, {"key": "no_air_travel", "text": "Air travel is not permitted and should not be included in the travel expenses budget.", "rationale": null, "confidence": 0.98, "importance": "high", "sourceAnchors": [{"url": null, "note": null, "quote": "Travel expenses (TA/DA) of the persons involved (Air travel not permitted).", "fieldKey": null, "confidence": null, "sourceType": "raw_text"}]}], "priorities": [{"key": "nep_2020_alignment", "text": "Research proposals related to the priority areas defined by National Education Policy 2020 will receive priority.", "rationale": null, "confidence": 0.98, "importance": "high", "sourceAnchors": [{"url": null, "note": null, "quote": "In view of National Education Policy 2020, a new set of priority areas for funding of researches under ERIC... The research proposals/ doctoral fellowships related to these priority areas will receive priority.", "fieldKey": null, "confidence": null, "sourceType": "raw_text"}]}, {"key": "priority_approach_policy_research", "text": "Priority will be given to proposals using a Policy Research in Education approach.", "rationale": null, "confidence": 0.98, "importance": "high", "sourceAnchors": [{"url": null, "note": null, "quote": "In order to make educational research relevant, effective, and meaningful, ERIC shall give priority to the following research approaches. • Policy research in education", "fieldKey": null, "confidence": null, "sourceType": "raw_text"}]}, {"key": "priority_approach_qualitative", "text": "Priority will be given to proposals using qualitative and participatory approaches involving triangulation of methodologies.", "rationale": null, "confidence": 0.98, "importance": "high", "sourceAnchors": [{"url": null, "note": null, "quote": "In order to make educational research relevant, effective, and meaningful, ERIC shall give priority to the following research approaches... • Qualitative and participatory approaches involving triangulation of methodologies", "fieldKey": null, "confidence": null, "sourceType": "raw_text"}]}, {"key": "priority_approach_mixed_methods", "text": "Priority will be given to proposals using case studies and mixed method research approaches.", "rationale": null, "confidence": 0.98, "importance": "high", "sourceAnchors": [{"url": null, "note": null, "quote": "In order to make educational research relevant, effective, and meaningful, ERIC shall give priority to the following research approaches... • Case studies and mixed method researches", "fieldKey": null, "confidence": null, "sourceType": "raw_text"}]}, {"key": "priority_approach_collaborative", "text": "Priority will be given to proposals that are inter-disciplinary, collaborative, multi-centric, and pan-Indian.", "rationale": null, "confidence": 0.98, "importance": "high", "sourceAnchors": [{"url": null, "note": null, "quote": "In order to make educational research relevant, effective, and meaningful, ERIC shall give priority to the following research approaches... • Inter-disciplinary, collaborative, multi-centric, and pan-Indian researches", "fieldKey": null, "confidence": null, "sourceType": "raw_text"}]}, {"key": "priority_topic_ecce", "text": "Proposals focusing on Early Childhood Care and Education are a priority area.", "rationale": null, "confidence": 0.95, "importance": "high", "sourceAnchors": [{"url": null, "note": null, "quote": "Priority Areas of research... 1. Early Childhood Care and Education", "fieldKey": null, "confidence": null, "sourceType": "raw_text"}]}, {"key": "priority_topic_foundational_learning", "text": "Proposals focusing on Foundational Learning are a priority area.", "rationale": null, "confidence": 0.95, "importance": "high", "sourceAnchors": [{"url": null, "note": null, "quote": "Priority Areas of research... 2. Foundational Learning", "fieldKey": null, "confidence": null, "sourceType": "raw_text"}]}, {"key": "priority_topic_dropouts_access", "text": "Proposals focusing on Curtailing dropouts and ensuring Universal Access to Education at All Levels are a priority area.", "rationale": null, "confidence": 0.95, "importance": "high", "sourceAnchors": [{"url": null, "note": null, "quote": "Priority Areas of research... 3. Curtailing dropouts and ensuring Universal Access to Education at All Levels", "fieldKey": null, "confidence": null, "sourceType": "raw_text"}]}, {"key": "priority_topic_curriculum_pedagogy", "text": "Proposals focusing on Curriculum and Pedagogy in Schools are a priority area.", "rationale": null, "confidence": 0.95, "importance": "high", "sourceAnchors": [{"url": null, "note": null, "quote": "Priority Areas of research... 4. Curriculum and Pedagogy in Schools", "fieldKey": null, "confidence": null, "sourceType": "raw_text"}]}, {"key": "priority_topic_teacher_education", "text": "Proposals focusing on Teachers and Teacher Education are a priority area.", "rationale": null, "confidence": 0.95, "importance": "high", "sourceAnchors": [{"url": null, "note": null, "quote": "Priority Areas of research... 5. Teachers and Teacher Education", "fieldKey": null, "confidence": null, "sourceType": "raw_text"}]}, {"key": "priority_topic_inclusive_education", "text": "Proposals focusing on Equitable and Inclusive Education (Learning for All) are a priority area.", "rationale": null, "confidence": 0.95, "importance": "high", "sourceAnchors": [{"url": null, "note": null, "quote": "Priority Areas of research... 6. Equitable and Inclusive Education: Learning for All", "fieldKey": null, "confidence": null, "sourceType": "raw_text"}]}], "budgetRules": [{"key": "jpf_stipend", "text": "The only personnel cost allowed is for a Junior Project Fellow (JPF) at a consolidated rate of Rs. 14,000/- per month (Non-NET) or Rs. 16,000/- per month (NET).", "rationale": null, "confidence": 0.99, "importance": "high", "sourceAnchors": [{"url": null, "note": null, "quote": "The ERIC funding does not provide any honorarium or salary for academic and project staff except for Junior Project Fellow (JPF) @ Rs.14,000/- (Non-NET) Rs. 16,000/- (NET) per month (consolidated).", "fieldKey": null, "confidence": null, "sourceType": "raw_text"}]}, {"key": "annual_installments", "text": "For projects exceeding 12 months, the research grant will be released in the form of annual installments.", "rationale": null, "confidence": 0.98, "importance": "high", "sourceAnchors": [{"url": null, "note": null, "quote": "Research grant for the project will be released in the form of annual installments, if the project duration exceeds 12 months.", "fieldKey": null, "confidence": null, "sourceType": "raw_text"}]}, {"key": "final_installment_release", "text": "Fifteen percent of the final installment and overhead charges will be released only after the submission of the final report and audited accounts.", "rationale": null, "confidence": 0.98, "importance": "high", "sourceAnchors": [{"url": null, "note": null, "quote": "Fifteen percent of the final installment and overhead charges (wherever applicable) will be released only after submission of the final report after completion of the project and after receipt of the statement of audited accounts along with the utilization certificate by the competent authority of the Institution receiving the project grant.", "fieldKey": null, "confidence": null, "sourceType": "raw_text"}]}, {"key": "purchased_books_deposit", "text": "Any literature, books, or journals purchased with project funds must be deposited in the institution where the research was conducted.", "rationale": null, "confidence": 0.98, "importance": "medium", "sourceAnchors": [{"url": null, "note": null, "quote": "Any literature, books or journals purchased under the project released funds should be deposited in the institution where the research has been conducted.", "fieldKey": null, "confidence": null, "sourceType": "raw_text"}]}, {"key": "overhead_charges", "text": "Overhead charges of 5% of the total project cost are admissible for institutions other than NCERT, upon production of a certificate.", "rationale": null, "confidence": 0.98, "importance": "high", "sourceAnchors": [{"url": null, "note": null, "quote": "Overhead charges( 5 per cent of the total cost of the project) admissible on production of certificate from the Institution other than NCERT", "fieldKey": null, "confidence": null, "sourceType": "raw_text"}]}, {"key": "yearly_budget_breakup", "text": "The head-wise budget break-up must be submitted in yearly installments.", "rationale": null, "confidence": 0.98, "importance": "high", "sourceAnchors": [{"url": null, "note": null, "quote": "The head-wise budget break-up may be submitted in yearly installments.", "fieldKey": null, "confidence": null, "sourceType": "raw_text"}]}, {"key": "no_reappropriation", "text": "Reappropriation of expenditure from one sanctioned budget subhead to another is generally not permitted.", "rationale": null, "confidence": 0.95, "importance": "high", "sourceAnchors": [{"url": null, "note": null, "quote": "Reappropriation of expenditure from one sanctioned subhead to another is generally not permitted.", "fieldKey": null, "confidence": null, "sourceType": "raw_text"}]}, {"key": "jpf_funds_non_transferable", "text": "JPF fellowship money cannot be re-appropriated to any other head and cannot be utilized for any other purpose.", "rationale": null, "confidence": 0.98, "importance": "high", "sourceAnchors": [{"url": null, "note": null, "quote": "JPF fellowship money cannot be re-appropriated to any other head and cannot be utilized for any other purpose.", "fieldKey": null, "confidence": null, "sourceType": "raw_text"}]}], "formatRules": [{"key": "cover_page_content", "text": "The cover page of the proposal must contain the names, full addresses, telephone and fax numbers, and e-mail addresses of the PI and any Co-PIs.", "rationale": null, "confidence": 0.98, "importance": "high", "sourceAnchors": [{"url": null, "note": null, "quote": "The cover page of the proposal should contain names, and full addresses, telephone and fax numbers, and e-mail addresses of the Pl and Co-PI.", "fieldKey": null, "confidence": null, "sourceType": "raw_text"}]}, {"key": "summary_word_limit", "text": "The summary of the final report must be within 1000 words.", "rationale": null, "confidence": 0.98, "importance": "high", "sourceAnchors": [{"url": null, "note": null, "quote": "Two copies of draft report (word processed and spiral/soft bound form) along with three copies of the summary (within 1000 words) are required to be sent.", "fieldKey": null, "confidence": null, "sourceType": "raw_text"}]}], "mustAddress": [{"key": "intro_indian_context", "text": "The introduction must focus on the need of the study in the Indian context.", "rationale": null, "confidence": 0.98, "importance": "high", "sourceAnchors": [{"url": null, "note": null, "quote": "This section may focus on need of the study in the Indian context, overview of the work already done in the area and its linkage with the proposed study, and theoretical perspective (if any, to be followed).", "fieldKey": null, "confidence": null, "sourceType": "raw_text"}]}, {"key": "intro_literature_review", "text": "The introduction must provide an overview of the work already done in the area and its linkage with the proposed study.", "rationale": null, "confidence": 0.98, "importance": "high", "sourceAnchors": [{"url": null, "note": null, "quote": "This section may focus on need of the study in the Indian context, overview of the work already done in the area and its linkage with the proposed study...", "fieldKey": null, "confidence": null, "sourceType": "raw_text"}]}, {"key": "intro_significance", "text": "The introduction must include the educational significance and rationale of the study.", "rationale": null, "confidence": 0.98, "importance": "high", "sourceAnchors": [{"url": null, "note": null, "quote": "It will also include educational significance alongwith rationale of the study.", "fieldKey": null, "confidence": null, "sourceType": "raw_text"}]}, {"key": "objectives_research_questions", "text": "The proposal must state specific, achievable objectives or corresponding research questions.", "rationale": null, "confidence": 0.98, "importance": "high", "sourceAnchors": [{"url": null, "note": null, "quote": "Specific achievable objectives or the corresponding research questions may be spelt out.", "fieldKey": null, "confidence": null, "sourceType": "raw_text"}]}, {"key": "hypotheses", "text": "Any hypotheses for the study must be stated.", "rationale": null, "confidence": 0.98, "importance": "medium", "sourceAnchors": [{"url": null, "note": null, "quote": "Hypothesis, if any, may also be spelt out.", "fieldKey": null, "confidence": null, "sourceType": "raw_text"}]}, {"key": "outcomes_benefits", "text": "The likely outcome of the study and its benefits for school education and teacher education must be precisely stated.", "rationale": null, "confidence": 0.98, "importance": "high", "sourceAnchors": [{"url": null, "note": null, "quote": "Likely outcome of the study and benefits in the context of school education and teacher education needs to be precisely stated.", "fieldKey": null, "confidence": null, "sourceType": "raw_text"}]}, {"key": "methodology_details", "text": "The methodology section must detail the research design, how information will be collected, and how the collected information will be analyzed.", "rationale": null, "confidence": 0.98, "importance": "high", "sourceAnchors": [{"url": null, "note": null, "quote": "This should include the details of the research design, the modality of collecting information and also the methodology of providing meaning to the collected information.", "fieldKey": null, "confidence": null, "sourceType": "raw_text"}]}, {"key": "organizational_framework", "text": "An organizational chart must be provided, indicating the tasks and duration for the PI, any Co-PIs, and any JPF.", "rationale": null, "confidence": 0.98, "importance": "high", "sourceAnchors": [{"url": null, "note": null, "quote": "An organizational chart indicating the tasks of the PI, Co-Pls (if any), and JPF (if any) with their duration should be given.", "fieldKey": null, "confidence": null, "sourceType": "raw_text"}]}], "durationRules": [{"key": "duration_statement", "text": "The proposal must include a statement specifying the time duration in which the study is proposed to be completed.", "rationale": null, "confidence": 0.98, "importance": "high", "sourceAnchors": [{"url": null, "note": null, "quote": "The proposal must include a statement about time duration in which the study is proposed to be completed.", "fieldKey": null, "confidence": null, "sourceType": "raw_text"}]}, {"key": "time_budgeting_stages", "text": "It is desirable to present the project timeline by visualizing the various stages involved in the study and the time requirement for each stage.", "rationale": null, "confidence": 0.95, "importance": "medium", "sourceAnchors": [{"url": null, "note": null, "quote": "To make it more rational, it may be desirable to visualize various stages involved in the study vis-à-vis the time requirement for each stage.", "fieldKey": null, "confidence": null, "sourceType": "raw_text"}]}, {"key": "project_commencement_date", "text": "The project's official start date is considered the date on which the institution receives the first funding installment.", "rationale": null, "confidence": 0.98, "importance": "high", "sourceAnchors": [{"url": null, "note": null, "quote": "The date of receipt of the first installment by the institution would be considered as the date of commencement of the project.", "fieldKey": null, "confidence": null, "sourceType": "raw_text"}]}], "sourceAnchors": [{"url": null, "note": "The entire provided source text was used for this extraction.", "quote": null, "fieldKey": "primary_source_text", "confidence": 1, "sourceType": "raw_text"}], "reviewerSignals": [{"key": "field_based_innovations", "text": "Preference will be given to proposals from PIs with field-based experience and that demonstrate innovations in conducting research.", "rationale": null, "confidence": 0.98, "importance": "high", "sourceAnchors": [{"url": null, "note": null, "quote": "* Preference will be given to the proposals having field based experience and innovations in conducting research by the Project Investigator.", "fieldKey": null, "confidence": null, "sourceType": "raw_text"}]}, {"key": "definition_of_innovation", "text": "Proposals for 'studies of innovation' are encouraged, defined as the development and testing of alternate methods, curricular inputs, classroom practices, or management practices.", "rationale": null, "confidence": 0.95, "importance": "high", "sourceAnchors": [{"url": null, "note": null, "quote": "ERIC recognizes development and testing of alternate methods, curricular inputs, classroom practices, management practices to improve quality and quantity of educational outcomes by individual/or a team of professionals as studies of innovation.", "fieldKey": null, "confidence": null, "sourceType": "raw_text"}]}, {"key": "collaborative_national_importance", "text": "The funder values research proposals developed under a common design on issues of national importance and implemented collaboratively by institutions across the country.", "rationale": null, "confidence": 0.95, "importance": "high", "sourceAnchors": [{"url": null, "note": null, "quote": "ERIC gives importance to research proposals developed under common design on the issues of national importance and implemented in collaborative way by institutions located in different parts of the country.", "fieldKey": null, "confidence": null, "sourceType": "raw_text"}]}, {"key": "title_quality", "text": "The project title should be brief, crisp, and clearly communicate the intent of the study.", "rationale": null, "confidence": 0.9, "importance": "low", "sourceAnchors": [{"url": null, "note": null, "quote": "Title of the Study/Project: It should be brief, crisp, and communicate the intent of the study.", "fieldKey": null, "confidence": null, "sourceType": "raw_text"}]}], "submissionRules": [{"key": "rolling_submission", "text": "Proposals can be submitted to ERIC at any time of the year.", "rationale": null, "confidence": 0.98, "importance": "high", "sourceAnchors": [{"url": null, "note": null, "quote": "All research proposals have to be formulated in the enclosed format and submitted to ERIC at any time of the year...", "fieldKey": null, "confidence": null, "sourceType": "raw_text"}]}, {"key": "institutional_affiliation", "text": "Proposals are only accepted from individuals or groups of researchers affiliated with recognized institutions.", "rationale": null, "confidence": 0.98, "importance": "high", "sourceAnchors": [{"url": null, "note": null, "quote": "Research proposals by individuals/group of researchers affiliated to recognized institutions only are entertained for funding purposes.", "fieldKey": null, "confidence": null, "sourceType": "raw_text"}]}, {"key": "institutional_routing", "text": "All proposals must be routed through the respective head of the institution.", "rationale": null, "confidence": 0.98, "importance": "high", "sourceAnchors": [{"url": null, "note": null, "quote": "All proposals need to be routed through the respective head of the institution with a commitment to administer the funds and also be accountable for grants received from NCERT.", "fieldKey": null, "confidence": null, "sourceType": "raw_text"}]}, {"key": "submission_copies", "text": "Applicants must submit two hard copies and one soft copy of the detailed proposal via email to ncertder@gmail.com.", "rationale": null, "confidence": 0.98, "importance": "high", "sourceAnchors": [{"url": null, "note": null, "quote": "Two hard copies as well as soft copy of the detailed proposal through email (ncertder@gmail.com) in the prescribed format (Appendix I).", "fieldKey": null, "confidence": null, "sourceType": "raw_text"}]}, {"key": "required_documents", "text": "The submission must include the detailed proposal, an undertaking by the institution (Appendix II), an undertaking by the PI (Appendix III), and the PI's bio-data (Appendix IV).", "rationale": null, "confidence": 0.98, "importance": "high", "sourceAnchors": [{"url": null, "note": null, "quote": "To help the speedy decisions towards funding, the following documents are required: i. Two hard copies as well as soft copy... ii. The undertaking by the institution... iii. An undertaking by the PI... iv. Bio-data of the Project Incharge...", "fieldKey": null, "confidence": null, "sourceType": "raw_text"}]}, {"key": "ngo_requirements", "text": "Proposals from non-governmental organizations must include a registration certificate, and audited annual accounts and annual reports for the past two years.", "rationale": null, "confidence": 0.98, "importance": "high", "sourceAnchors": [{"url": null, "note": null, "quote": "In the case of proposals emanating from non- government organization, the evidence to support the status of organization in the form of registration certificate, audited annual accounts and annual reports for the past two years immediately preceding the date of submission of proposal.", "fieldKey": null, "confidence": null, "sourceType": "raw_text"}]}, {"key": "other_funding_disclosure", "text": "Applicants must disclose if the proposal has been submitted to, or is being supported by, any other funding agency.", "rationale": null, "confidence": 0.98, "importance": "high", "sourceAnchors": [{"url": null, "note": null, "quote": "In case the above research project or an allied project receives assistance from any other source, I shall inform NCERT accordingly.", "fieldKey": null, "confidence": null, "sourceType": "raw_text"}]}], "deliverableRules": [{"key": "draft_report_submission", "text": "Two copies of a draft report (word processed and in spiral/soft bound form) must be submitted.", "rationale": null, "confidence": 0.98, "importance": "high", "sourceAnchors": [{"url": null, "note": null, "quote": "Two copies of draft report (word processed and spiral/soft bound form) along with three copies of the summary (within 1000 words) are required to be sent.", "fieldKey": null, "confidence": null, "sourceType": "raw_text"}]}, {"key": "summary_submission", "text": "Three copies of a summary (within 1000 words) must be submitted along with the draft report.", "rationale": null, "confidence": 0.98, "importance": "high", "sourceAnchors": [{"url": null, "note": null, "quote": "Two copies of draft report (word processed and spiral/soft bound form) along with three copies of the summary (within 1000 words) are required to be sent.", "fieldKey": null, "confidence": null, "sourceType": "raw_text"}]}, {"key": "report_revision", "text": "The PI is required to revise the draft final report based on anonymous expert review.", "rationale": null, "confidence": 0.95, "importance": "high", "sourceAnchors": [{"url": null, "note": null, "quote": "Draft project report will be reviewed anonymously by an expert... Subsequently, the Pl is required to revise the draft final report...", "fieldKey": null, "confidence": null, "sourceType": "raw_text"}]}, {"key": "final_report_submission", "text": "Three hard-bound copies and a soft copy of the revised final report must be submitted.", "rationale": null, "confidence": 0.98, "importance": "high", "sourceAnchors": [{"url": null, "note": null, "quote": "the Pl is required to revise the draft final report and send three copies in hard bound form for further action along with soft copy.", "fieldKey": null, "confidence": null, "sourceType": "raw_text"}]}, {"key": "progress_reporting_multiyear", "text": "For projects longer than 12 months, a progress report must be submitted after nine months to trigger the release of the second installment.", "rationale": null, "confidence": 0.98, "importance": "high", "sourceAnchors": [{"url": null, "note": null, "quote": "Second installment onwards, as the case may be, will be released subject to submission of the progress report after the completion of nine months...", "fieldKey": null, "confidence": null, "sourceType": "raw_text"}]}], "evaluationCriteria": [{"key": "spmc_evaluation", "text": "All proposals are evaluated by the Screening-cum-Progress Monitoring Committee (SPMC), which consists of experts from different areas of educational research.", "rationale": null, "confidence": 0.95, "importance": "high", "sourceAnchors": [{"url": null, "note": null, "quote": "All proposals will be evaluated by the Screening-cum-Progress Monitoring Committee (SPMC) consisting of the experts from different areas of educational research.", "fieldKey": null, "confidence": null, "sourceType": "raw_text"}]}, {"key": "holistic_review", "text": "The SPMC evaluates all aspects of the proposal, including the budget, before recommending it for funding, resubmission, or rejection.", "rationale": null, "confidence": 0.95, "importance": "high", "sourceAnchors": [{"url": null, "note": null, "quote": "After evaluating all aspects of the proposal including the budget, the SPMC would recommend in terms of either acceptance of the proposals for funding or resubmission of the proposals after incorporating suggested revisions or rejection of the proposal.", "fieldKey": null, "confidence": null, "sourceType": "raw_text"}]}]}	{"avoid": [{"key": "external_evaluation", "text": "Do not propose evaluations of educational interventions if you were not involved in their development or implementation.", "appliesTo": ["methodology"], "rationale": null, "ruleClass": "avoid", "confidence": 0.98, "importance": "high", "sourceBlock": "avoid", "detectorHints": [], "draftingStage": ["methodology"], "sourceAnchors": [{"url": null, "note": null, "quote": "Evaluation of educational intervention by scholars who are not involved in the development or implementation of those interventions will not be encouraged.", "fieldKey": null, "confidence": null, "sourceType": "raw_text"}], "enforcementLevel": "hard", "draftingVsSubmission": "drafting"}, {"key": "no_honorarium_salary", "text": "Do not budget for honorarium or salary for academic and project staff, other than the specified Junior Project Fellow (JPF) role.", "appliesTo": ["all"], "rationale": null, "ruleClass": "budget", "confidence": 0.98, "importance": "high", "sourceBlock": "avoid", "detectorHints": ["budget_limit"], "draftingStage": ["budget_strategy"], "sourceAnchors": [{"url": null, "note": null, "quote": "The ERIC funding does not provide any honorarium or salary for academic and project staff except for Junior Project Fellow (JPF)", "fieldKey": null, "confidence": null, "sourceType": "raw_text"}], "enforcementLevel": "hard", "draftingVsSubmission": "drafting"}, {"key": "no_furniture_durable_assets", "text": "Do not include the purchase of furniture and durable assets in the project budget.", "appliesTo": ["all"], "rationale": null, "ruleClass": "budget", "confidence": 0.98, "importance": "high", "sourceBlock": "avoid", "detectorHints": ["budget_limit"], "draftingStage": ["budget_strategy"], "sourceAnchors": [{"url": null, "note": null, "quote": "Furniture and durable assets are not allowed to be included in the project budget.", "fieldKey": null, "confidence": null, "sourceType": "raw_text"}], "enforcementLevel": "hard", "draftingVsSubmission": "drafting"}, {"key": "no_hardware_assets", "text": "The purchase of hardware and durable assets such as almirahs, furniture, and computers is not admissible in the budget.", "appliesTo": ["all"], "rationale": null, "ruleClass": "budget", "confidence": 0.98, "importance": "high", "sourceBlock": "avoid", "detectorHints": ["budget_limit"], "draftingStage": ["budget_strategy"], "sourceAnchors": [{"url": null, "note": null, "quote": "Purchase of hardwares and durable assets such as almirah, furniture, computer, etc. is not admissible.", "fieldKey": null, "confidence": null, "sourceType": "raw_text"}], "enforcementLevel": "soft", "draftingVsSubmission": "drafting"}, {"key": "no_pre_commencement_expenditure", "text": "The project budget will not support any expenditure incurred before the commencement of the project.", "appliesTo": ["all"], "rationale": null, "ruleClass": "budget", "confidence": 0.98, "importance": "high", "sourceBlock": "avoid", "detectorHints": ["budget_limit"], "draftingStage": ["budget_strategy"], "sourceAnchors": [{"url": null, "note": null, "quote": "The project budget will not support any expenditure incurred before the commencement of the project.", "fieldKey": null, "confidence": null, "sourceType": "raw_text"}], "enforcementLevel": "soft", "draftingVsSubmission": "drafting"}, {"key": "no_air_travel", "text": "Air travel is not permitted and should not be included in the travel expenses budget.", "appliesTo": ["all"], "rationale": null, "ruleClass": "budget", "confidence": 0.98, "importance": "high", "sourceBlock": "avoid", "detectorHints": ["budget_limit"], "draftingStage": ["budget_strategy"], "sourceAnchors": [{"url": null, "note": null, "quote": "Travel expenses (TA/DA) of the persons involved (Air travel not permitted).", "fieldKey": null, "confidence": null, "sourceType": "raw_text"}], "enforcementLevel": "hard", "draftingVsSubmission": "drafting"}], "priorities": [{"key": "nep_2020_alignment", "text": "Research proposals related to the priority areas defined by National Education Policy 2020 will receive priority.", "appliesTo": ["alignment"], "rationale": null, "ruleClass": "priority", "confidence": 0.98, "importance": "high", "sourceBlock": "priorities", "detectorHints": ["priority_alignment"], "draftingStage": ["thrust_alignment"], "sourceAnchors": [{"url": null, "note": null, "quote": "In view of National Education Policy 2020, a new set of priority areas for funding of researches under ERIC... The research proposals/ doctoral fellowships related to these priority areas will receive priority.", "fieldKey": null, "confidence": null, "sourceType": "raw_text"}], "enforcementLevel": "soft", "draftingVsSubmission": "drafting"}, {"key": "priority_approach_policy_research", "text": "Priority will be given to proposals using a Policy Research in Education approach.", "appliesTo": ["methodology", "alignment"], "rationale": null, "ruleClass": "priority", "confidence": 0.98, "importance": "high", "sourceBlock": "priorities", "detectorHints": ["priority_alignment"], "draftingStage": ["thrust_alignment", "methodology"], "sourceAnchors": [{"url": null, "note": null, "quote": "In order to make educational research relevant, effective, and meaningful, ERIC shall give priority to the following research approaches. • Policy research in education", "fieldKey": null, "confidence": null, "sourceType": "raw_text"}], "enforcementLevel": "soft", "draftingVsSubmission": "drafting"}, {"key": "priority_approach_qualitative", "text": "Priority will be given to proposals using qualitative and participatory approaches involving triangulation of methodologies.", "appliesTo": ["alignment"], "rationale": null, "ruleClass": "priority", "confidence": 0.98, "importance": "high", "sourceBlock": "priorities", "detectorHints": ["priority_alignment"], "draftingStage": ["thrust_alignment"], "sourceAnchors": [{"url": null, "note": null, "quote": "In order to make educational research relevant, effective, and meaningful, ERIC shall give priority to the following research approaches... • Qualitative and participatory approaches involving triangulation of methodologies", "fieldKey": null, "confidence": null, "sourceType": "raw_text"}], "enforcementLevel": "soft", "draftingVsSubmission": "drafting"}, {"key": "priority_approach_mixed_methods", "text": "Priority will be given to proposals using case studies and mixed method research approaches.", "appliesTo": ["methodology", "alignment"], "rationale": null, "ruleClass": "priority", "confidence": 0.98, "importance": "high", "sourceBlock": "priorities", "detectorHints": ["priority_alignment"], "draftingStage": ["thrust_alignment", "methodology"], "sourceAnchors": [{"url": null, "note": null, "quote": "In order to make educational research relevant, effective, and meaningful, ERIC shall give priority to the following research approaches... • Case studies and mixed method researches", "fieldKey": null, "confidence": null, "sourceType": "raw_text"}], "enforcementLevel": "soft", "draftingVsSubmission": "drafting"}, {"key": "priority_approach_collaborative", "text": "Priority will be given to proposals that are inter-disciplinary, collaborative, multi-centric, and pan-Indian.", "appliesTo": ["alignment"], "rationale": null, "ruleClass": "priority", "confidence": 0.98, "importance": "high", "sourceBlock": "priorities", "detectorHints": ["priority_alignment"], "draftingStage": ["thrust_alignment"], "sourceAnchors": [{"url": null, "note": null, "quote": "In order to make educational research relevant, effective, and meaningful, ERIC shall give priority to the following research approaches... • Inter-disciplinary, collaborative, multi-centric, and pan-Indian researches", "fieldKey": null, "confidence": null, "sourceType": "raw_text"}], "enforcementLevel": "soft", "draftingVsSubmission": "drafting"}, {"key": "priority_topic_ecce", "text": "Proposals focusing on Early Childhood Care and Education are a priority area.", "appliesTo": ["alignment"], "rationale": null, "ruleClass": "priority", "confidence": 0.95, "importance": "high", "sourceBlock": "priorities", "detectorHints": ["priority_alignment"], "draftingStage": ["thrust_alignment"], "sourceAnchors": [{"url": null, "note": null, "quote": "Priority Areas of research... 1. Early Childhood Care and Education", "fieldKey": null, "confidence": null, "sourceType": "raw_text"}], "enforcementLevel": "soft", "draftingVsSubmission": "drafting"}, {"key": "priority_topic_foundational_learning", "text": "Proposals focusing on Foundational Learning are a priority area.", "appliesTo": ["alignment"], "rationale": null, "ruleClass": "priority", "confidence": 0.95, "importance": "high", "sourceBlock": "priorities", "detectorHints": ["priority_alignment"], "draftingStage": ["thrust_alignment"], "sourceAnchors": [{"url": null, "note": null, "quote": "Priority Areas of research... 2. Foundational Learning", "fieldKey": null, "confidence": null, "sourceType": "raw_text"}], "enforcementLevel": "soft", "draftingVsSubmission": "drafting"}, {"key": "priority_topic_dropouts_access", "text": "Proposals focusing on Curtailing dropouts and ensuring Universal Access to Education at All Levels are a priority area.", "appliesTo": ["alignment"], "rationale": null, "ruleClass": "priority", "confidence": 0.95, "importance": "high", "sourceBlock": "priorities", "detectorHints": ["priority_alignment"], "draftingStage": ["thrust_alignment"], "sourceAnchors": [{"url": null, "note": null, "quote": "Priority Areas of research... 3. Curtailing dropouts and ensuring Universal Access to Education at All Levels", "fieldKey": null, "confidence": null, "sourceType": "raw_text"}], "enforcementLevel": "soft", "draftingVsSubmission": "drafting"}, {"key": "priority_topic_curriculum_pedagogy", "text": "Proposals focusing on Curriculum and Pedagogy in Schools are a priority area.", "appliesTo": ["alignment"], "rationale": null, "ruleClass": "priority", "confidence": 0.95, "importance": "high", "sourceBlock": "priorities", "detectorHints": ["priority_alignment"], "draftingStage": ["thrust_alignment"], "sourceAnchors": [{"url": null, "note": null, "quote": "Priority Areas of research... 4. Curriculum and Pedagogy in Schools", "fieldKey": null, "confidence": null, "sourceType": "raw_text"}], "enforcementLevel": "soft", "draftingVsSubmission": "drafting"}, {"key": "priority_topic_teacher_education", "text": "Proposals focusing on Teachers and Teacher Education are a priority area.", "appliesTo": ["alignment"], "rationale": null, "ruleClass": "priority", "confidence": 0.95, "importance": "high", "sourceBlock": "priorities", "detectorHints": ["priority_alignment"], "draftingStage": ["thrust_alignment"], "sourceAnchors": [{"url": null, "note": null, "quote": "Priority Areas of research... 5. Teachers and Teacher Education", "fieldKey": null, "confidence": null, "sourceType": "raw_text"}], "enforcementLevel": "soft", "draftingVsSubmission": "drafting"}, {"key": "priority_topic_inclusive_education", "text": "Proposals focusing on Equitable and Inclusive Education (Learning for All) are a priority area.", "appliesTo": ["alignment"], "rationale": null, "ruleClass": "priority", "confidence": 0.95, "importance": "high", "sourceBlock": "priorities", "detectorHints": ["priority_alignment"], "draftingStage": ["thrust_alignment"], "sourceAnchors": [{"url": null, "note": null, "quote": "Priority Areas of research... 6. Equitable and Inclusive Education: Learning for All", "fieldKey": null, "confidence": null, "sourceType": "raw_text"}], "enforcementLevel": "soft", "draftingVsSubmission": "drafting"}], "budgetRules": [{"key": "jpf_stipend", "text": "The only personnel cost allowed is for a Junior Project Fellow (JPF) at a consolidated rate of Rs. 14,000/- per month (Non-NET) or Rs. 16,000/- per month (NET).", "appliesTo": ["workplan"], "rationale": null, "ruleClass": "budget", "confidence": 0.99, "importance": "high", "sourceBlock": "budgetRules", "detectorHints": ["budget_limit", "duration_limit"], "draftingStage": ["budget_strategy"], "sourceAnchors": [{"url": null, "note": null, "quote": "The ERIC funding does not provide any honorarium or salary for academic and project staff except for Junior Project Fellow (JPF) @ Rs.14,000/- (Non-NET) Rs. 16,000/- (NET) per month (consolidated).", "fieldKey": null, "confidence": null, "sourceType": "raw_text"}], "enforcementLevel": "hard", "draftingVsSubmission": "both"}, {"key": "annual_installments", "text": "For projects exceeding 12 months, the research grant will be released in the form of annual installments.", "appliesTo": ["workplan"], "rationale": null, "ruleClass": "budget", "confidence": 0.98, "importance": "high", "sourceBlock": "budgetRules", "detectorHints": ["budget_limit", "duration_limit"], "draftingStage": ["budget_strategy"], "sourceAnchors": [{"url": null, "note": null, "quote": "Research grant for the project will be released in the form of annual installments, if the project duration exceeds 12 months.", "fieldKey": null, "confidence": null, "sourceType": "raw_text"}], "enforcementLevel": "hard", "draftingVsSubmission": "both"}, {"key": "final_installment_release", "text": "Fifteen percent of the final installment and overhead charges will be released only after the submission of the final report and audited accounts.", "appliesTo": ["workplan"], "rationale": null, "ruleClass": "submission", "confidence": 0.98, "importance": "high", "sourceBlock": "budgetRules", "detectorHints": ["budget_limit", "submission_checklist"], "draftingStage": ["budget_strategy"], "sourceAnchors": [{"url": null, "note": null, "quote": "Fifteen percent of the final installment and overhead charges (wherever applicable) will be released only after submission of the final report after completion of the project and after receipt of the statement of audited accounts along with the utilization certificate by the competent authority of the Institution receiving the project grant.", "fieldKey": null, "confidence": null, "sourceType": "raw_text"}], "enforcementLevel": "hard", "draftingVsSubmission": "submission"}, {"key": "purchased_books_deposit", "text": "Any literature, books, or journals purchased with project funds must be deposited in the institution where the research was conducted.", "appliesTo": ["workplan"], "rationale": null, "ruleClass": "budget", "confidence": 0.98, "importance": "medium", "sourceBlock": "budgetRules", "detectorHints": ["budget_limit"], "draftingStage": ["beneficiaries"], "sourceAnchors": [{"url": null, "note": null, "quote": "Any literature, books or journals purchased under the project released funds should be deposited in the institution where the research has been conducted.", "fieldKey": null, "confidence": null, "sourceType": "raw_text"}], "enforcementLevel": "hard", "draftingVsSubmission": "both"}, {"key": "overhead_charges", "text": "Overhead charges of 5% of the total project cost are admissible for institutions other than NCERT, upon production of a certificate.", "appliesTo": ["workplan"], "rationale": null, "ruleClass": "submission", "confidence": 0.98, "importance": "high", "sourceBlock": "budgetRules", "detectorHints": ["budget_limit", "submission_checklist"], "draftingStage": ["budget_strategy"], "sourceAnchors": [{"url": null, "note": null, "quote": "Overhead charges( 5 per cent of the total cost of the project) admissible on production of certificate from the Institution other than NCERT", "fieldKey": null, "confidence": null, "sourceType": "raw_text"}], "enforcementLevel": "hard", "draftingVsSubmission": "submission"}, {"key": "yearly_budget_breakup", "text": "The head-wise budget break-up must be submitted in yearly installments.", "appliesTo": ["workplan"], "rationale": null, "ruleClass": "budget", "confidence": 0.98, "importance": "high", "sourceBlock": "budgetRules", "detectorHints": ["budget_limit"], "draftingStage": ["budget_strategy"], "sourceAnchors": [{"url": null, "note": null, "quote": "The head-wise budget break-up may be submitted in yearly installments.", "fieldKey": null, "confidence": null, "sourceType": "raw_text"}], "enforcementLevel": "hard", "draftingVsSubmission": "both"}, {"key": "no_reappropriation", "text": "Reappropriation of expenditure from one sanctioned budget subhead to another is generally not permitted.", "appliesTo": ["workplan"], "rationale": null, "ruleClass": "budget", "confidence": 0.95, "importance": "high", "sourceBlock": "budgetRules", "detectorHints": ["budget_limit"], "draftingStage": ["budget_strategy"], "sourceAnchors": [{"url": null, "note": null, "quote": "Reappropriation of expenditure from one sanctioned subhead to another is generally not permitted.", "fieldKey": null, "confidence": null, "sourceType": "raw_text"}], "enforcementLevel": "hard", "draftingVsSubmission": "both"}, {"key": "jpf_funds_non_transferable", "text": "JPF fellowship money cannot be re-appropriated to any other head and cannot be utilized for any other purpose.", "appliesTo": ["workplan"], "rationale": null, "ruleClass": "budget", "confidence": 0.98, "importance": "high", "sourceBlock": "budgetRules", "detectorHints": ["budget_limit"], "draftingStage": ["budget_strategy"], "sourceAnchors": [{"url": null, "note": null, "quote": "JPF fellowship money cannot be re-appropriated to any other head and cannot be utilized for any other purpose.", "fieldKey": null, "confidence": null, "sourceType": "raw_text"}], "enforcementLevel": "hard", "draftingVsSubmission": "both"}], "formatRules": [{"key": "cover_page_content", "text": "The cover page of the proposal must contain the names, full addresses, telephone and fax numbers, and e-mail addresses of the PI and any Co-PIs.", "appliesTo": ["all"], "rationale": null, "ruleClass": "format", "confidence": 0.98, "importance": "high", "sourceBlock": "formatRules", "detectorHints": ["word_limit", "character_limit", "format_rule"], "draftingStage": [], "sourceAnchors": [{"url": null, "note": null, "quote": "The cover page of the proposal should contain names, and full addresses, telephone and fax numbers, and e-mail addresses of the Pl and Co-PI.", "fieldKey": null, "confidence": null, "sourceType": "raw_text"}], "enforcementLevel": "hard", "draftingVsSubmission": "both"}, {"key": "summary_word_limit", "text": "The summary of the final report must be within 1000 words.", "appliesTo": ["summary"], "rationale": null, "ruleClass": "format", "confidence": 0.98, "importance": "high", "sourceBlock": "formatRules", "detectorHints": ["word_limit", "character_limit", "format_rule"], "draftingStage": ["final_pitch"], "sourceAnchors": [{"url": null, "note": null, "quote": "Two copies of draft report (word processed and spiral/soft bound form) along with three copies of the summary (within 1000 words) are required to be sent.", "fieldKey": null, "confidence": null, "sourceType": "raw_text"}], "enforcementLevel": "hard", "draftingVsSubmission": "both"}], "mustAddress": [{"key": "intro_indian_context", "text": "The introduction must focus on the need of the study in the Indian context.", "appliesTo": ["problem_need"], "rationale": null, "ruleClass": "must_address", "confidence": 0.98, "importance": "high", "sourceBlock": "mustAddress", "detectorHints": [], "draftingStage": ["problem_definition"], "sourceAnchors": [{"url": null, "note": null, "quote": "This section may focus on need of the study in the Indian context, overview of the work already done in the area and its linkage with the proposed study, and theoretical perspective (if any, to be followed).", "fieldKey": null, "confidence": null, "sourceType": "raw_text"}], "enforcementLevel": "hard", "draftingVsSubmission": "drafting"}, {"key": "intro_literature_review", "text": "The introduction must provide an overview of the work already done in the area and its linkage with the proposed study.", "appliesTo": ["summary"], "rationale": null, "ruleClass": "must_address", "confidence": 0.98, "importance": "high", "sourceBlock": "mustAddress", "detectorHints": [], "draftingStage": ["final_pitch"], "sourceAnchors": [{"url": null, "note": null, "quote": "This section may focus on need of the study in the Indian context, overview of the work already done in the area and its linkage with the proposed study...", "fieldKey": null, "confidence": null, "sourceType": "raw_text"}], "enforcementLevel": "hard", "draftingVsSubmission": "drafting"}, {"key": "intro_significance", "text": "The introduction must include the educational significance and rationale of the study.", "appliesTo": ["problem_need"], "rationale": null, "ruleClass": "must_address", "confidence": 0.98, "importance": "high", "sourceBlock": "mustAddress", "detectorHints": [], "draftingStage": [], "sourceAnchors": [{"url": null, "note": null, "quote": "It will also include educational significance alongwith rationale of the study.", "fieldKey": null, "confidence": null, "sourceType": "raw_text"}], "enforcementLevel": "hard", "draftingVsSubmission": "drafting"}, {"key": "objectives_research_questions", "text": "The proposal must state specific, achievable objectives or corresponding research questions.", "appliesTo": ["all"], "rationale": null, "ruleClass": "must_address", "confidence": 0.98, "importance": "high", "sourceBlock": "mustAddress", "detectorHints": [], "draftingStage": [], "sourceAnchors": [{"url": null, "note": null, "quote": "Specific achievable objectives or the corresponding research questions may be spelt out.", "fieldKey": null, "confidence": null, "sourceType": "raw_text"}], "enforcementLevel": "hard", "draftingVsSubmission": "drafting"}, {"key": "hypotheses", "text": "Any hypotheses for the study must be stated.", "appliesTo": ["all"], "rationale": null, "ruleClass": "must_address", "confidence": 0.98, "importance": "medium", "sourceBlock": "mustAddress", "detectorHints": [], "draftingStage": [], "sourceAnchors": [{"url": null, "note": null, "quote": "Hypothesis, if any, may also be spelt out.", "fieldKey": null, "confidence": null, "sourceType": "raw_text"}], "enforcementLevel": "hard", "draftingVsSubmission": "drafting"}, {"key": "outcomes_benefits", "text": "The likely outcome of the study and its benefits for school education and teacher education must be precisely stated.", "appliesTo": ["impact_outcomes"], "rationale": null, "ruleClass": "must_address", "confidence": 0.98, "importance": "high", "sourceBlock": "mustAddress", "detectorHints": [], "draftingStage": ["outcomes"], "sourceAnchors": [{"url": null, "note": null, "quote": "Likely outcome of the study and benefits in the context of school education and teacher education needs to be precisely stated.", "fieldKey": null, "confidence": null, "sourceType": "raw_text"}], "enforcementLevel": "hard", "draftingVsSubmission": "drafting"}, {"key": "methodology_details", "text": "The methodology section must detail the research design, how information will be collected, and how the collected information will be analyzed.", "appliesTo": ["methodology"], "rationale": null, "ruleClass": "must_address", "confidence": 0.98, "importance": "high", "sourceBlock": "mustAddress", "detectorHints": [], "draftingStage": [], "sourceAnchors": [{"url": null, "note": null, "quote": "This should include the details of the research design, the modality of collecting information and also the methodology of providing meaning to the collected information.", "fieldKey": null, "confidence": null, "sourceType": "raw_text"}], "enforcementLevel": "hard", "draftingVsSubmission": "drafting"}, {"key": "organizational_framework", "text": "An organizational chart must be provided, indicating the tasks and duration for the PI, any Co-PIs, and any JPF.", "appliesTo": ["all"], "rationale": null, "ruleClass": "duration", "confidence": 0.98, "importance": "high", "sourceBlock": "mustAddress", "detectorHints": ["duration_limit"], "draftingStage": [], "sourceAnchors": [{"url": null, "note": null, "quote": "An organizational chart indicating the tasks of the PI, Co-Pls (if any), and JPF (if any) with their duration should be given.", "fieldKey": null, "confidence": null, "sourceType": "raw_text"}], "enforcementLevel": "hard", "draftingVsSubmission": "drafting"}], "durationRules": [{"key": "duration_statement", "text": "The proposal must include a statement specifying the time duration in which the study is proposed to be completed.", "appliesTo": ["workplan"], "rationale": null, "ruleClass": "duration", "confidence": 0.98, "importance": "high", "sourceBlock": "durationRules", "detectorHints": ["duration_limit"], "draftingStage": ["workplan"], "sourceAnchors": [{"url": null, "note": null, "quote": "The proposal must include a statement about time duration in which the study is proposed to be completed.", "fieldKey": null, "confidence": null, "sourceType": "raw_text"}], "enforcementLevel": "hard", "draftingVsSubmission": "both"}, {"key": "time_budgeting_stages", "text": "It is desirable to present the project timeline by visualizing the various stages involved in the study and the time requirement for each stage.", "appliesTo": ["workplan"], "rationale": null, "ruleClass": "duration", "confidence": 0.95, "importance": "medium", "sourceBlock": "durationRules", "detectorHints": ["duration_limit", "deliverable_presence"], "draftingStage": ["workplan"], "sourceAnchors": [{"url": null, "note": null, "quote": "To make it more rational, it may be desirable to visualize various stages involved in the study vis-à-vis the time requirement for each stage.", "fieldKey": null, "confidence": null, "sourceType": "raw_text"}], "enforcementLevel": "hard", "draftingVsSubmission": "both"}, {"key": "project_commencement_date", "text": "The project's official start date is considered the date on which the institution receives the first funding installment.", "appliesTo": ["workplan"], "rationale": null, "ruleClass": "duration", "confidence": 0.98, "importance": "high", "sourceBlock": "durationRules", "detectorHints": ["duration_limit"], "draftingStage": ["beneficiaries"], "sourceAnchors": [{"url": null, "note": null, "quote": "The date of receipt of the first installment by the institution would be considered as the date of commencement of the project.", "fieldKey": null, "confidence": null, "sourceType": "raw_text"}], "enforcementLevel": "hard", "draftingVsSubmission": "both"}], "sourceAnchors": [{"url": null, "note": "The entire provided source text was used for this extraction.", "quote": null, "fieldKey": "primary_source_text", "confidence": 1, "sourceType": "raw_text"}], "reviewerSignals": [{"key": "field_based_innovations", "text": "Preference will be given to proposals from PIs with field-based experience and that demonstrate innovations in conducting research.", "appliesTo": ["all"], "rationale": null, "ruleClass": "reviewer_signal", "confidence": 0.98, "importance": "high", "sourceBlock": "reviewerSignals", "detectorHints": [], "draftingStage": ["thrust_alignment"], "sourceAnchors": [{"url": null, "note": null, "quote": "* Preference will be given to the proposals having field based experience and innovations in conducting research by the Project Investigator.", "fieldKey": null, "confidence": null, "sourceType": "raw_text"}], "enforcementLevel": "soft", "draftingVsSubmission": "drafting"}, {"key": "definition_of_innovation", "text": "Proposals for 'studies of innovation' are encouraged, defined as the development and testing of alternate methods, curricular inputs, classroom practices, or management practices.", "appliesTo": ["innovation"], "rationale": null, "ruleClass": "reviewer_signal", "confidence": 0.95, "importance": "high", "sourceBlock": "reviewerSignals", "detectorHints": [], "draftingStage": ["innovation"], "sourceAnchors": [{"url": null, "note": null, "quote": "ERIC recognizes development and testing of alternate methods, curricular inputs, classroom practices, management practices to improve quality and quantity of educational outcomes by individual/or a team of professionals as studies of innovation.", "fieldKey": null, "confidence": null, "sourceType": "raw_text"}], "enforcementLevel": "soft", "draftingVsSubmission": "drafting"}, {"key": "collaborative_national_importance", "text": "The funder values research proposals developed under a common design on issues of national importance and implemented collaboratively by institutions across the country.", "appliesTo": ["all"], "rationale": null, "ruleClass": "reviewer_signal", "confidence": 0.95, "importance": "high", "sourceBlock": "reviewerSignals", "detectorHints": [], "draftingStage": ["thrust_alignment"], "sourceAnchors": [{"url": null, "note": null, "quote": "ERIC gives importance to research proposals developed under common design on the issues of national importance and implemented in collaborative way by institutions located in different parts of the country.", "fieldKey": null, "confidence": null, "sourceType": "raw_text"}], "enforcementLevel": "soft", "draftingVsSubmission": "drafting"}, {"key": "title_quality", "text": "The project title should be brief, crisp, and clearly communicate the intent of the study.", "appliesTo": ["all"], "rationale": null, "ruleClass": "reviewer_signal", "confidence": 0.9, "importance": "low", "sourceBlock": "reviewerSignals", "detectorHints": [], "draftingStage": ["thrust_alignment"], "sourceAnchors": [{"url": null, "note": null, "quote": "Title of the Study/Project: It should be brief, crisp, and communicate the intent of the study.", "fieldKey": null, "confidence": null, "sourceType": "raw_text"}], "enforcementLevel": "soft", "draftingVsSubmission": "drafting"}], "submissionRules": [{"key": "rolling_submission", "text": "Proposals can be submitted to ERIC at any time of the year.", "appliesTo": ["all"], "rationale": null, "ruleClass": "submission", "confidence": 0.98, "importance": "high", "sourceBlock": "submissionRules", "detectorHints": ["duration_limit", "submission_checklist"], "draftingStage": [], "sourceAnchors": [{"url": null, "note": null, "quote": "All research proposals have to be formulated in the enclosed format and submitted to ERIC at any time of the year...", "fieldKey": null, "confidence": null, "sourceType": "raw_text"}], "enforcementLevel": "hard", "draftingVsSubmission": "submission"}, {"key": "institutional_affiliation", "text": "Proposals are only accepted from individuals or groups of researchers affiliated with recognized institutions.", "appliesTo": ["all"], "rationale": null, "ruleClass": "submission", "confidence": 0.98, "importance": "high", "sourceBlock": "submissionRules", "detectorHints": ["submission_checklist"], "draftingStage": [], "sourceAnchors": [{"url": null, "note": null, "quote": "Research proposals by individuals/group of researchers affiliated to recognized institutions only are entertained for funding purposes.", "fieldKey": null, "confidence": null, "sourceType": "raw_text"}], "enforcementLevel": "hard", "draftingVsSubmission": "submission"}, {"key": "institutional_routing", "text": "All proposals must be routed through the respective head of the institution.", "appliesTo": ["all"], "rationale": null, "ruleClass": "submission", "confidence": 0.98, "importance": "high", "sourceBlock": "submissionRules", "detectorHints": ["submission_checklist"], "draftingStage": ["beneficiaries"], "sourceAnchors": [{"url": null, "note": null, "quote": "All proposals need to be routed through the respective head of the institution with a commitment to administer the funds and also be accountable for grants received from NCERT.", "fieldKey": null, "confidence": null, "sourceType": "raw_text"}], "enforcementLevel": "hard", "draftingVsSubmission": "submission"}, {"key": "submission_copies", "text": "Applicants must submit two hard copies and one soft copy of the detailed proposal via email to ncertder@gmail.com.", "appliesTo": ["all"], "rationale": null, "ruleClass": "submission", "confidence": 0.98, "importance": "high", "sourceBlock": "submissionRules", "detectorHints": ["submission_checklist"], "draftingStage": [], "sourceAnchors": [{"url": null, "note": null, "quote": "Two hard copies as well as soft copy of the detailed proposal through email (ncertder@gmail.com) in the prescribed format (Appendix I).", "fieldKey": null, "confidence": null, "sourceType": "raw_text"}], "enforcementLevel": "hard", "draftingVsSubmission": "submission"}, {"key": "required_documents", "text": "The submission must include the detailed proposal, an undertaking by the institution (Appendix II), an undertaking by the PI (Appendix III), and the PI's bio-data (Appendix IV).", "appliesTo": ["all"], "rationale": null, "ruleClass": "submission", "confidence": 0.98, "importance": "high", "sourceBlock": "submissionRules", "detectorHints": ["word_limit", "character_limit", "format_rule", "submission_checklist"], "draftingStage": ["beneficiaries", "methodology"], "sourceAnchors": [{"url": null, "note": null, "quote": "To help the speedy decisions towards funding, the following documents are required: i. Two hard copies as well as soft copy... ii. The undertaking by the institution... iii. An undertaking by the PI... iv. Bio-data of the Project Incharge...", "fieldKey": null, "confidence": null, "sourceType": "raw_text"}], "enforcementLevel": "hard", "draftingVsSubmission": "submission"}, {"key": "ngo_requirements", "text": "Proposals from non-governmental organizations must include a registration certificate, and audited annual accounts and annual reports for the past two years.", "appliesTo": ["all"], "rationale": null, "ruleClass": "submission", "confidence": 0.98, "importance": "high", "sourceBlock": "submissionRules", "detectorHints": ["duration_limit", "submission_checklist"], "draftingStage": [], "sourceAnchors": [{"url": null, "note": null, "quote": "In the case of proposals emanating from non- government organization, the evidence to support the status of organization in the form of registration certificate, audited annual accounts and annual reports for the past two years immediately preceding the date of submission of proposal.", "fieldKey": null, "confidence": null, "sourceType": "raw_text"}], "enforcementLevel": "hard", "draftingVsSubmission": "submission"}, {"key": "other_funding_disclosure", "text": "Applicants must disclose if the proposal has been submitted to, or is being supported by, any other funding agency.", "appliesTo": ["all"], "rationale": null, "ruleClass": "submission", "confidence": 0.98, "importance": "high", "sourceBlock": "submissionRules", "detectorHints": ["submission_checklist"], "draftingStage": [], "sourceAnchors": [{"url": null, "note": null, "quote": "In case the above research project or an allied project receives assistance from any other source, I shall inform NCERT accordingly.", "fieldKey": null, "confidence": null, "sourceType": "raw_text"}], "enforcementLevel": "hard", "draftingVsSubmission": "submission"}], "deliverableRules": [{"key": "draft_report_submission", "text": "Two copies of a draft report (word processed and in spiral/soft bound form) must be submitted.", "appliesTo": ["workplan"], "rationale": null, "ruleClass": "format", "confidence": 0.98, "importance": "high", "sourceBlock": "deliverableRules", "detectorHints": ["word_limit", "character_limit", "format_rule"], "draftingStage": ["workplan"], "sourceAnchors": [{"url": null, "note": null, "quote": "Two copies of draft report (word processed and spiral/soft bound form) along with three copies of the summary (within 1000 words) are required to be sent.", "fieldKey": null, "confidence": null, "sourceType": "raw_text"}], "enforcementLevel": "hard", "draftingVsSubmission": "drafting"}, {"key": "summary_submission", "text": "Three copies of a summary (within 1000 words) must be submitted along with the draft report.", "appliesTo": ["summary"], "rationale": null, "ruleClass": "deliverable", "confidence": 0.98, "importance": "high", "sourceBlock": "deliverableRules", "detectorHints": [], "draftingStage": ["final_pitch"], "sourceAnchors": [{"url": null, "note": null, "quote": "Two copies of draft report (word processed and spiral/soft bound form) along with three copies of the summary (within 1000 words) are required to be sent.", "fieldKey": null, "confidence": null, "sourceType": "raw_text"}], "enforcementLevel": "hard", "draftingVsSubmission": "drafting"}, {"key": "report_revision", "text": "The PI is required to revise the draft final report based on anonymous expert review.", "appliesTo": ["workplan"], "rationale": null, "ruleClass": "deliverable", "confidence": 0.95, "importance": "high", "sourceBlock": "deliverableRules", "detectorHints": [], "draftingStage": ["workplan"], "sourceAnchors": [{"url": null, "note": null, "quote": "Draft project report will be reviewed anonymously by an expert... Subsequently, the Pl is required to revise the draft final report...", "fieldKey": null, "confidence": null, "sourceType": "raw_text"}], "enforcementLevel": "hard", "draftingVsSubmission": "drafting"}, {"key": "final_report_submission", "text": "Three hard-bound copies and a soft copy of the revised final report must be submitted.", "appliesTo": ["workplan"], "rationale": null, "ruleClass": "deliverable", "confidence": 0.98, "importance": "high", "sourceBlock": "deliverableRules", "detectorHints": [], "draftingStage": ["workplan"], "sourceAnchors": [{"url": null, "note": null, "quote": "the Pl is required to revise the draft final report and send three copies in hard bound form for further action along with soft copy.", "fieldKey": null, "confidence": null, "sourceType": "raw_text"}], "enforcementLevel": "hard", "draftingVsSubmission": "drafting"}, {"key": "progress_reporting_multiyear", "text": "For projects longer than 12 months, a progress report must be submitted after nine months to trigger the release of the second installment.", "appliesTo": ["workplan"], "rationale": null, "ruleClass": "duration", "confidence": 0.98, "importance": "high", "sourceBlock": "deliverableRules", "detectorHints": ["duration_limit"], "draftingStage": ["workplan"], "sourceAnchors": [{"url": null, "note": null, "quote": "Second installment onwards, as the case may be, will be released subject to submission of the progress report after the completion of nine months...", "fieldKey": null, "confidence": null, "sourceType": "raw_text"}], "enforcementLevel": "hard", "draftingVsSubmission": "drafting"}], "evaluationCriteria": [{"key": "spmc_evaluation", "text": "All proposals are evaluated by the Screening-cum-Progress Monitoring Committee (SPMC), which consists of experts from different areas of educational research.", "appliesTo": ["all"], "rationale": null, "ruleClass": "evaluation", "confidence": 0.95, "importance": "high", "sourceBlock": "evaluationCriteria", "detectorHints": [], "draftingStage": ["evaluation"], "sourceAnchors": [{"url": null, "note": null, "quote": "All proposals will be evaluated by the Screening-cum-Progress Monitoring Committee (SPMC) consisting of the experts from different areas of educational research.", "fieldKey": null, "confidence": null, "sourceType": "raw_text"}], "enforcementLevel": "soft", "draftingVsSubmission": "drafting"}, {"key": "holistic_review", "text": "The SPMC evaluates all aspects of the proposal, including the budget, before recommending it for funding, resubmission, or rejection.", "appliesTo": ["all"], "rationale": null, "ruleClass": "budget", "confidence": 0.95, "importance": "high", "sourceBlock": "evaluationCriteria", "detectorHints": ["budget_limit"], "draftingStage": ["budget_strategy"], "sourceAnchors": [{"url": null, "note": null, "quote": "After evaluating all aspects of the proposal including the budget, the SPMC would recommend in terms of either acceptance of the proposals for funding or resubmission of the proposals after incorporating suggested revisions or rejection of the proposal.", "fieldKey": null, "confidence": null, "sourceType": "raw_text"}], "enforcementLevel": "soft", "draftingVsSubmission": "drafting"}]}	null	\N	\N	2026-04-29 07:23:12.482	2026-04-29 07:24:52.515
