line": [138], "record": [183], "applied": [53], "cheques": [198], "complex": [33], "example": [11], "methods": [52, 126], "million": [197], "minimal": [46], "modules": [98], "network": [22, 160, 173], "overall": [132], "provide": [182], "reading": [162], "reviews": [50], "several": [196], "shapes,": [82], "surface": [35], "systems": [93, 119, 136], "trained": [3, 122], "various": [51], "accuracy": [184], "business": [186], "cheques.": [189], "classify": [38], "combined": [176], "compares": [59], "composed": [95], "decision": [34], "deployed": [192], "designed": [74], "document": [91], "globally": [123], "gradient": [15], "language": [105], "learning": [17, 25, 109], "measure.": [134], "minimize": [130], "multiple": [97], "networks": [2, 114], "personal": [188], "standard": [63], "training": [179], "Real-life": [90], "advantage": [146], "algorithm": [7], "character": [56, 174], "including": [99], "modeling.": [106], "networks,": [70], "networks.": [156], "paradigm,": [110], "patterns,": [40], "training,": [149], "Multilayer": [0], "algorithms": [26], "constitute": [8], "described.": [142, 168], "outperform": [86], "successful": [14], "synthesize": [31], "technique.": [18], "techniques": [180], "Experiments": [143], "appropriate": [21], "characters,": [44], "demonstrate": [144], "extraction,": [101], "flexibility": [152], "handwriting": [139], "handwritten": [43, 55, 64], "multimodule": [118], "performance": [133], "recognition": [57, 66, 92, 140], "recognizers": [175], "techniques.": [89], "transformer": [113, 155, 159], "variability": [79], "commercially": [193], "recognition,": [103], "segmentation": [102], "specifically": [73], "Convolutional": [68], "architecture,": [23], "convolutional": [171], "gradient-based": [24, 125], "preprocessing.": [47], "back-propagation": [6], "high-dimensional": [39]}, "cited_by_percentile_year": {"max": 100, "min": 99}, "corresponding_author_ids": ["https://openalex.org/A5001226970"], "countries_distinct_count": 2, "institutions_distinct_count": 4, "corresponding_institution_ids": ["https://openalex.org/I1283103587"], "sustainable_development_goals": [], "citation_normalized_percentile": {"value": 0.9891118, "is_in_top_1_percent": false, "is_in_top_10_percent": true}}, "abstract": "Multilayer neural networks trained with the back-propagation algorithm constitute the best example of a successful gradient based learning technique. Given an appropriate network architecture, gradient-based learning algorithms can be used to synthesize a complex decision surface that can classify high-dimensional patterns, such as handwritten characters, with minimal preprocessing. This paper reviews various methods applied to handwritten character recognition and compares them on a standard handwritten digit recognition task. Convolutional neural networks, which are specifically designed to deal with the variability of 2D shapes, are shown to outperform all other techniques. Real-life document recognition systems are composed of multiple modules including field extraction, segmentation recognition, and language modeling. A new learning paradigm, called graph transformer networks (GTN), allows such multimodule systems to be trained globally using gradient-based methods so as to minimize an overall performance measure. Two systems for online handwriting recognition are described. Experiments demonstrate the advantage of global training, and the flexibility of graph transformer networks. A graph transformer network for reading a bank cheque is also described. It uses convolutional neural network character recognizers combined with global training techniques to provide record accuracy on business and personal cheques. It is deployed commercially and reads several million cheques per day.", "publisher": "Institute of Electrical and Electronics Engineers", "citationCount": 57469, "fieldsOfStudy": ["Computer science", "Artificial intelligence", "Convolutional neural network", "Intelligent character recognition", "Handwri